/* 令和8年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r08.committeeSessions.push(...[{"id":"r08-20260224-8","meetingId":"r08-1t","date":"2026年2月24日","dateIso":"2026-02-24","committee":"建設委員会","time":"午前１０時００分～午後 ２時２１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３４号議案 品川区建築物不燃化促進助成条例の一部を改正する条例","agenda":"第３４号議案 品川区建築物不燃化促進助成条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回のプレス発表なのですけれども、今回説明を受けた都市防災不燃化促進事業以外にも、最後に少し説明がありましたけれども不燃化特区支援事業や、住宅・建築物耐震化支援事業、これらの３つの施策について、同様に高齢者・障害者等世帯の木造住宅の不燃化・耐震化促進について発表されていますけれども、今回、都市防災不燃化促進事業だけが条例として建設委員会に出てきているのはなぜなのか。","respondent":"小川木密整備推進課長","answer":"こちらは推測にはなるところですが、本事業は建物の不燃化促進の先駆けの事業となってございまして、昭和６２年から事業を開始しています。この事業の取組に当たって、しっかり確実にやっていきたいという考え方があるのかなと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"昭和６２年から始まっているということですけれども、事業対象の目的が、広域避難場所の安全確保と延焼遮断帯の形成ということです。防災性の向上というのであれば、区内全域で取り組むのも一つの考えだと思うのですけれども、そうではなく、広域避難場所の安全確保や延焼遮断帯の形成に事業を集中している理由は何かということを伺いたいと思います。","respondent":"小川木密整備推進課長","answer":"それと、あと都市計画道路と補助２９号線等の沿道は、避難道路、また救援救護路という位置づけがありますので、そういった役割をしっかりと担保させるといったところで、この都市防災不燃化促進事業、そして助成支援を行っていくものです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"そうなのです。そこで伺いたいのは、今回、高齢者・障害者がいる住宅を対象としているのだけれども、理由を見ると、財力や意欲の面から建て替えが進みにくいと。この理由を掲げているわけです。恐らく区内全域に広げていくと、区の持ち出しが当然増えることになるかと思うのですけれども、補助金の関係だけの判断なのか、それ以外にも理由があるのであればお伺いしたいと思います。","respondent":"小川木密整備推進課長","answer":"やはり、まず広域避難場所の安全性確保、また避難路・救援救護路の確保といったところで、持っている、求められているもの、それをしっかりと行っていく、担保させていくといったところまた地域として危険度が高いところをまずは優先的に対応していくというところで。","voiceIndex":10,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"優先的にというご説明です。それを思えば思うほど、やはり特に高齢者・障害者等の世帯は、一つ一つの住宅を防災上、安全にしていく。こうして品川区は進んでいるわけですから、こうした事業も、最悪の事態を想定して、まずそこを安全にするという考えは持ちながらも、区内全域の住宅の安全性を高めていくといった考え方も必要ではないかなと、意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"ゆきた委員","kind":"確認","question":"今回の障害者・高齢者の世帯への支援の上乗せというのは大変意義がある事業だと感じています。お話を伺った方がどのように受け止めるかというのはあると思うのですけれども、情報をその対象地域に、ご家族などにも周知していくというところが大事なところだと思います。ここへのアプローチの仕方というのはどういうふうに考えているのか、この１点だけご確認させていただければと思います。","respondent":"小川木密整備推進課長","answer":"それとはまた別に福祉部署と連携しまして、我々が福祉系の協議会などの場に出向きまして、こういった事業に令和８年度から取り組むという形で、しっかりと案内等させていただきたいと考えています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"安藤委員","kind":"意見","question":"これについて反対なのですが、高齢者・障害者の不燃化・耐震化の促進は重要だと思いますし、今回、プレス発表でも併せて打ち出された、区内全域を対象にした、こちらは建築課の事業だと思うのですけれども、こういった住宅耐震化支援事業における耐震化率の拡充などは大いに賛成するところです。先ほどもありましたけれども、不燃化特区の区内全域への拡大などが必要ではないかと思います。反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-006"},{"speaker":"中塚委員","kind":"意見","question":"広域避難場所の安全確保というのは必要な対応だと思います。補助２９号線を含めた延焼遮断帯の機能というところでは、結局、道路の際まで燃え尽きてしまうということになりますので、これは到底受け入れることはできません。事業として、高齢者・障害者世帯に拡大するという方向は必要だと思いますけれども、延焼遮断帯機能の形成というところは受け入れられませんので、全体として反対ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-007"}]},{"id":"topic-02","title":"第３５号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第３５号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"改正に賛成なのですけれども、ストレートに地下機械式駐輪場を当日利用に切り替えるということはできないのかを伺いたいと思います。それと、最新の利用率について伺いたいのですけれども、機械式の地下駐輪場の利用率と、あと公園内の平場の定期利用と当日利用、あと大森駅前住宅の前の駐輪場当日利用と、定期利用はあるのか分からないのですけれども、定期利用があれば、それぞれ伺います。","respondent":"山下交通安全担当課長","answer":"今後、当日利用に変更するとなりますと、あと精算機を、当日利用にできるようなシステムに改修する必要があると。併せて、当日利用者が利用する際に、その都度、ＩＣの交付のための車検をする必要があります。","voiceIndex":29,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。大森駅前住宅の駐輪場についてですけれども、景観等の関係から撤去してほしいという要望がやはり根強く、届けられているかと思います。今回のこういった措置を受けて、今後、利用状況なども見据えながら、大森駅前住宅の駐輪場の閉鎖に向けて動いていただきたいのですけれども、それについてはご答弁はいかがでしょうか。","respondent":"山下交通安全担当課長","answer":"時間によってはほぼ満車状態ということもありますので、今回、地下機械式の駐輪場の値段を下げることによって、現在、当日利用をしている方が、一応、見込みですが１００台以上は入るのかなと考えているところです。","voiceIndex":31,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"当日利用から定期利用への移行を促していきたいというご説明でしたけれども、定期利用率が低い理由というか、当初想定していたものより、少ない理由というのでしょうか、そこはどのように分析されているのかということを伺いたいと思います。併せて、定期利用ですけれども、契約は１年なのでしょうか、半年なのでしょうか、１か月なのでしょうか。そこが分からなかったので、ご説明いただきたいです。","respondent":"山下交通安全担当課長","answer":"約１００名ほどの回答があったのですけれども、その中では、やはり料金が高い、やや高いという方が６４％を超える状況でございました。は車検がある関係で、車検を通らなくて入れられないという回答もございました。","voiceIndex":34,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"仮に１か月で２０日間利用すると３,０００円なのです。定期代がかかる上に駐輪場が２,５００円、２,３００円ですから、例えば学生に限定してさらに減額していくというふうにするとどうかなと思ったのですけれども、いかがでしょうか。契約期間が１か月、３か月、６か月ということですから、学生によっては、大学生も含めて、夏休みは長いですから、そういうときは契約をしなかったり、いろいろ工夫すると。","respondent":"山下交通安全担当課長","answer":"将来的にどのようになるかというのは、今、申し上げられませんけれども、そういったご意見があるということもひとつ受け止めて、今後の検討課題にさせていただければと思います。","voiceIndex":36,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言。将来的にはまたいろいろ検討していただきたいと思いますし、当日利用から定期利用に移行していきたいということであります。学生と社会人は同等とおっしゃいますけれども、やはり学生はさらに負担を軽くして、学業や部活動に専念していただきたいと思うのです。とにかく一旦下げてみて、どういう状況なのかというのを把握した上で、その機会でまたご検討いただけたらと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問","question":"先ほどのご答弁で、定期利用の契約期間が１か月、３か月、６か月とご説明がありました。それで、今回、１０月施行とのことですが、１０月以降の定期利用分については自動的に月額２,０００円が適用されるのか、それとも更新時からの適用となるのか、施行日以前に契約して、既に、事前に複数月分納めている利用者についてはどういう対応となるのか、あと併せて周知方法についてもお聞きできればと思います。","respondent":"山下交通安全担当課長","answer":"よって４月に６か月を契約しますと、１０月３０日までの契約となるのですけれども、１０月分につきましては減額後の料金を反映するようにシステムを変更していく予定です。","voiceIndex":40,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、先ほど申しましたように、学割を検討していただきたいと思います。区として、高校３年生までは、料金を取らないということを行っているわけで、建設委員会の中でも、公園課が所管するプールなどが対象ですけれども、そうした区の全体の流れも踏まえて、社会人と学生は同等という考えはぜひ見直していただいて、学割制度の導入をご検討いただきたいと、改めて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-014"}]},{"id":"topic-03","title":"第５０号議案 専決処分の承認を求めること","agenda":"第５０号議案 専決処分の承認を求めること","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"幾つかお伺いします。１か月分の家賃は幾らだったのか。割り返せば出てくるのかなと思うのですけれども、それが１つ。専決処分にしなくてはいけなかった理由というのをお伺いしたいというのが２点目。それと、これは確認なのですけれども、家賃の支払いや明渡し等をしてもらうにあたって、今回のような訴訟を起こす以外の方法というのは何かあるのか、伺いたいと思います。","respondent":"川原住宅課長","answer":"そして２点目、専決処分の理由です。こちらは改めてのご説明になるのですけれども、専決処分は、第１７９条第３項の規定にのっとりまして、本件を議会に報告し、その承認を求めるという形になってあります。","voiceIndex":55,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"滞納整理の対応をするのは品川区の職員なのか、それとも指定管理者の方なのか、伺いたいと思うのです。例えば、区の書類をもって指定管理者の方がポストインするのか、それとも区の職員自体が、電気がついているとかメーターが回っているとか、そこにいらっしゃるということを確認するのか、どちらが確認するのか。それぞれどういうふうに役割を分けているのか。そこをご説明いただきたいと思います。","respondent":"川原住宅課長","answer":"結論から申し上げると、こういった長期滞納者については、双方からアクションを起こしているような形です。ただ、文書送付の９割は区から発送しているといったところです。最初に申し上げた督促状と催告書は、滞納整理要綱に基づき、区から発送しています。","voiceIndex":58,"id":"exchange-016"},{"speaker":"中塚委員","kind":"確認","question":"防災センターの方が何度も訪問されているということで、居住の実態はあるということですけれども、品川区としては直接、居住の実態というのは確認されていらっしゃるのか。どういうふうに確認するのか。やはり、何らかの問題や課題や困難を抱えている方だとするならば、支援につなげていきたい。区としても訪問しているのか。それをどういうふうに把握されるのか。そこを伺いたいと思います。","respondent":"川原住宅課長","answer":"実際の区としての踏み込んだ確認・支援などの対応というところと、課長としての対応というところのご質問があったかと思います。","voiceIndex":60,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"区としては、そこにいらっしゃるということを直接的には把握しているわけではなくて、指定管理者の動きを伺う、報告を上げてもらっているということなのか、区としても電話されたということは今おっしゃいましたけれども、現地に行っていらっしゃるのか。そこを確認させていただきたいと思います。指定管理者の方の業務だということも分かった上で、そこだけ確認させていただきたいと思います。","respondent":"川原住宅課長","answer":"滞納整理の状況を把握するとき、通常は区役所に管理者が来て説明を受けるのですけれども、場合によっては現地や同建物の防災センターでそういった話し合いをして、見回りに同行するといったことはございました。","voiceIndex":62,"id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"引き続き、丁寧な対応をお願いしたいと思います。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-019"},{"speaker":"ゆきた委員","kind":"質問","question":"今回の案件のように、保証限度額が約１９２万円に対して訴訟価額が約７２９万円となる事案について、今後同様のケースが増加した場合というのは、区の財政的負担というのは小さくないと思います。現在、区民住宅、それ以外の区営住宅等も含めて、長期滞納というのがどれだけあるのか。訴訟予備群というのが、今後考えられるものがどのぐらい案件としてはあるのか。この辺についてお聞きできればと思います。","respondent":"川原住宅課長","answer":"ただ残念ながらそれでも数か月にわたって滞納している方は、複数名いらっしゃるところです。ただ、全く連絡が取れていない方は、この方以外いらっしゃらないので、引き続き細かな連絡を取っていって、滞らないように対応していきたいと考えています。","voiceIndex":66,"id":"exchange-020"},{"speaker":"ゆきた委員","kind":"確認","question":"ほかにも複数名いらっしゃるということを確認させていただきました。滞納が長期化する前段階で、と先ほどもお話があったのですけれども、福祉的な支援とか、あと生活再建支援という仕組みを今後考えていく必要があると考えます。明渡訴訟、請求に至る前に、再発防止策というのはこれから必要になるなとは感じますが、ここについて教えてください。","respondent":"川原住宅課長","answer":"少し重複しての答弁となりますが、こういった滞納整理の事務をしっかりと基本にのっとって行うといったところと、当然、１か月滞納したときの督促状と２か月滞納の催告書には、このまま滞納を続けると使用許可も取消しになる、退去していただくことになるといったことも。","voiceIndex":68,"id":"exchange-021"},{"speaker":"ゆきた委員","kind":"意見","question":"通知していくというのは承知しているのですけれども、生活再建をしていく上でのアプローチの仕方が必要だとお伝えしているので、こちらについては受け止めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-022"},{"speaker":"せお副委員長","kind":"質問・要望","question":"すみません。私も今、ゆきた委員が言ったことと本当に同意見です。今、ゆきた委員が最後にちょっと要望されたのですけれども、そこのところを聞きたい。福祉的な支援は、こちらからアプローチしないと、多分、あちらからは来ないと思うのです。その方の状況がどこまで把握できるか分からないのですけれども、そういったところをこちらから発信していくというのはないのですか。","respondent":"川原住宅課長","answer":"ただ、そうすると、どうしても保護の方になると転居までの費用もかかってしまいますので、一定、退去までは時間を要してしまうということがあるのですけれども、そこの部分は寄り添った対応を、福祉部門とも連携して行っていったという事例は実際にあります。","voiceIndex":72,"id":"exchange-023"},{"speaker":"せお副委員長","kind":"質問・要望","question":"賛成です。今質問した区からのアプローチを積極的に、やっていらっしゃると思うのですが、より一層丁寧に行っていただきたいと要望して、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-024"},{"speaker":"中塚委員","kind":"提案","question":"賛成です。福祉的なアプローチのところ、少し議論や様々な提案があって、そのとおりだと思います。品川区も、初動といいますか、滞納額が増える前に、今ご説明もありましたけれども、ぜひ丁寧に引き続き進めていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-025"}]},{"id":"topic-04","title":"再開発準備組合の運営等に関する陳情","agenda":"再開発準備組合の運営等に関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"すみません。説明の最後のところで、今後のスケジュールなのですけれども、組合が認可されて、今後の事業のスケジュールというのですか、どんなふうに流れていくというスケジュールなのか、もう少し伺いたいと思います。これは前回も聞いたような気もするのですが、改めてそのことについて説明を求めたいと思います。処理がなぜ進んでいないかなどについて、区が知り得ている情報があれば伺いたいと思います。","respondent":"中道都市開発課長","answer":"続きまして、小山三丁目第２地区で火災があった原因等についてですけれども、区としては詳細の部分は把握していないです。","voiceIndex":87,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"どういうことをやってくれるのですかというのを伺いたいと思います。それと、火事については、部署をまたいででも、確認していただきたい。「やっぱり再開発というのは、こんなことが行われているのですか」みたいな感じで、すごく区民に衝撃を与えています。他の部署からでも情報を取って、「それはこういうことなのです」ということぐらいは説明していただきたいと思うのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"１つ、生活再建について区にどういったことができるのかです。事業スケジュールの件ですけれども、今週、２月２５日、２６日に、再開発組合では、各権利者または借家人に対し、説明会を行う予定です。","voiceIndex":89,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"それは自分でやってください」と言われるなど、いろいろな場合があるわけです。そこで、しっかり対応すべきだと思うのです。品川区は認可権者としての責任があるわけですから。区長もいろいろな事業のトップだから、逐一というのはなかなか難しいかもしれないのですけれども、この武蔵小山の開発事業についてどういう情報共有が行われているのかというのは、もう一回伺いたいと思います。","respondent":"中道都市開発課長","answer":"区としての対応ですけれども、区にご相談があった際には、適切に丁寧に対応していきたいと考えています。区長との情報共有ですけれども、まずこういった再開発ですと、節目節目といったものがありますので、そういった節目のときには、区長に随時、情報共有をしています。","voiceIndex":91,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"小山三丁目第１地区の事業費等の予定額なのですけれども、これは何年何月時点のものなのか伺いたいと思います。昨今の開発をめぐる環境・状況変化なども受けて、地権者には、本組合申請の前、申請が昨年の７月にあったということですけれども、その前にもう一度、最新の資金計画を説明するというのは当然あるべきなのではないかなと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"中道都市開発課長","answer":"この資金計画について、権利者に対しては昨年度などに説明しながら同意を取ってきているということは聞いてありますので、その資金計画も、そういった中で合意に結びついているという認識です。一方で、この資金計画ですけれども、今後、権利変換もあります。","voiceIndex":93,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"補助制度ができたから万々歳かというと、納税者からすると、とんでもないというか。この仕組みは一体何なのだと私は思います。４ページに進みます。マンションの区分所有者については、陳情にもずっと「不明」となっているのですけれども、マンション区分所有者の準備組合加入者・非加入者や同意・不同意の内訳についても教えていただければと思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"マンションごとの同意・不同意ですけれども、個別のマンションは１つの組織といった形の考え方で、今までもそうですけれども、いわゆるマンションの一組織としての判断ということになりますので、回答は控えします。","voiceIndex":95,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"どの個人が加入しているかというのを聞いているわけではないです。さっきも言いましたけれども、再開発に不同意の方というのは、具体的には本組合の設立に同意しない方、同意書を出さない方だと思うのです。だから、組合加入者の中で反対の人はと聞くつもりはないのですけれども、最終的にこの開発に同意した人というのは何人いるのか。そこを伺ったのです。その辺をもう一回お伺いします。","respondent":"中道都市開発課長","answer":"マンションごとですけれども、マンションごとの同意・不同意の数字について、区は把握しているという状況です。一方で、先ほどの理由のとおり、１つの組織の決定になりますので、区としては回答は控えするです。","voiceIndex":98,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"一軒一軒訪ねて同意書を集め回っているという話を聞いたのですけれども、そういうことなのか確認させていただきたいのと、あと同意者８３.６％というのは、私は権利者は全体でいうと６２名なのではないかと言いましたけれども、そのうちの８３.６を掛ければ人数が出てくるのでは。何で実人数を言ってくれないのかと。そこだけお伺いします。","respondent":"中道都市開発課長","answer":"総地権者数が６１.２２名、ここで同意しているのが５１.１６名というところで、８３.６％というところになります。","voiceIndex":100,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。次に６ページです。組合員総数でいうと、実人数でいうと１６８人に遠く及ばないのではないかと思うのですけれども、なぜ総会が成立とされたのか、伺いたいと思います。８ページにも関わるのですが、昨年の建設委員会の陳情審査で、準備組合の依頼を受けて、総会定足数の答弁を差し控えると言ったのはなぜなのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"前回の答弁で回答を控えするというところ、私のほうで答えましたけれども、こちらにつきましては、前回の理由のとおり、準備組合は民間の組織というところで、もちろん詳細な部分というのは区は全て把握しているものではないので、確認をしたところ、民間の組織のことなので。","voiceIndex":102,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"では組合員とは、法の解釈でいうとマンション１棟１人かもしれないのですけれども、実際にそこには、もうずっと暮らしてきた１人の人間がもう何百人と住んでいるわけではないですか。それで、組合員とはどう解釈するのか。ここについて、何というか、規約、民主主義にのっとった成立をしていないではないかという指摘について、改めて区として受け止める考えはあるのか、ないのか、伺いたいと思います。","respondent":"中道都市開発課長、新妻委員長","answer":"総会についてです。こういったマンション住民の一人一人にどう対応しているかです。準備組合はマンションの権利を持つ一人一人に対して、出席するかどうか、確認を取っているところです。私語はできません。傍聴人に申し上げます。静粛に願います。委員長の命令に従わないときは、品川区議会委員会傍聴規則第７条に基づき退場を命じますので、念のため申し上げておきます。","voiceIndex":104,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"認可時には２２９億円だった。どういうふうな判断基準があるのか、誰がどのようにして判断するのか伺いたい。それと、地権者の側からすると、ここに書いてありますような、補償はどうするのかということでありますが、中古マンションの価格も急騰していて、地権者への補償価格が２倍になるというような場合、どう補償するのか伺いたいと書いております。それも伺いたいと思います。","respondent":"中道都市開発課長","answer":"もちろん、回答に対して陳情者の方が全部が全部理解する、納得できたというわけではないのですけれども、そういった機会が設けられて、準備組合の考えていること、またはお互いに共通認識であったことを確認できたといったところもございました。","voiceIndex":107,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。最後に伺ったのは、補助金自体が相当上がってしまうというときに、行政というか、区民の側というのは何も判断できない。それに対して、指をくわえて待っているだけなのか。その際の判断基準というのは、誰がどのようにして判断するのか。そして、そういうふうに上がっていくものなのかというのを伺ったので、お答えください。","respondent":"中道都市開発課長","answer":"補助金の使い方です。こちらにつきましては、再開発事業の補助金要綱であったり手引であったりといったものがありますので、そうしたものにのっとって対応していくものです。","voiceIndex":109,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"要綱や手引にのっとって、どんどん上がっていくというのは、ちょっとおかしな仕組みだと思います。それと、様々、陳情者の方が疑問に思っていることなど、冒頭の説明ではかなり簡素な感じでしたので、きちんと住民の方の疑問には答えていっていただきたいと、改めて申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか伺いたいと思います。陳情のタイトルにあるとおり、３月２４日開催の臨時会総会の定足数について様々な質問が寄せられ、今、質疑がされたところです。７ページのところです。今の質疑ではこのご説明がなかったので、小数点になるのはなぜなのか、理由を伺いたいと思います。品川区としては、準備組合が差し控えてほしいという主張は正しいと思うのか、その理由も含めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"マンションは１棟ですけれども、そこに準備組合に加入されている方が５人いらっしゃったというところで、４名の方が出席すると０.８人という形になりますので、小数点というのは発生するもの、通常のほかの準備組合などの総会などを見ましても。","voiceIndex":113,"id":"exchange-038"},{"speaker":"中塚委員","kind":"確認","question":"それと、３つ目の質問の、総会の成立についてですけれども、弁護士も含めて、合っているかどうか確認しているというところでした。区としては成立していると思われているようですから、区としては成立していると思われている。準備組合から様々報告が上がっていて、成立していると区は思っているわけですから、そこを改めて伺いたいと思います。時間も時間なので、そこは改めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"総会の成立等々ですけれども、まず民間の組織のそれが成立しているかというところを、区が判断する立場ではないのかなと考えています。はその民間の組織の中でのルールというものがきちんと守られて、民間の中できちんと運営されているというところが重要かなと考えています。","voiceIndex":115,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"成立しているか、していないかということは、区が判断するものではないと。成立しているという報告を聞いているというご説明になるのでしょうか。初めて私もこの答弁を伺いますけれども、何で判断しないのでしょうか。規約や法令の違反があるかどうかは、具体的に事実を把握しなければ判断できないと思うのですが、判断する立場にないというのは、ちょっと違うなと思うのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"ですけれども、判断するには、やはり総会に必ず出て、区がそこで出席者の定足数を、その場できちんと「適正ですので運営を開始していいです」と判断する立場ではないのかなと思っています。","voiceIndex":117,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"ただ、総会が成立しているのか。その根拠というところに、一番最初の質問に戻るわけですけれども、こうやって疑問の声が上がっているわけですから、改めて準備組合に必要な把握をされているということですので、３月２４日の総会が成立していると区が判断している、改めて把握した上で判断している、その根拠は何か。最後にもう一度伺いたいと思います。","respondent":"中道都市開発課長","answer":"規約に、共有所有者の議決権は１とみなすと書いてあります。そうした中で、都市開発法も踏まえ、こういったマンションの権利者はやはり１名というカウントの中で、今、定足数を設定されてございまして、その過半数が出席すればその総会は成立する。","voiceIndex":119,"id":"exchange-041"},{"speaker":"松永委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。理由といたしましては、民間組織であるということがまず前提だと思います。その中で、先ほどご答弁の中で、規約違反や定足数を満たしていないという事実については、ないのであろうと判断させていただきました。事業の手続については適正に進められていると判断し、今回の陳情は不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-042"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。組合が都市再開発法に基づき適正に対応されていること、その点については弁護士を交えて確認していると、理事者からの答弁で改めて確認できました。ですので、引き続き権利者に寄り添い、必要な助言を継続していくことを求めて、この陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"採択を主張しますけれども、やはり再開発は地権者の皆さんにとっては本当に、命と暮らし、財産がかかった問題であります。新たな定数等の答弁もありましたけれども、住民・地権者の疑問には真摯に答えていただきたいと思いますので、採択ということで主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"陳情に寄せられている様々な疑問や意見に対しては、区としては丁寧に説明すべきだと思います。そもそも法律でマンション１棟の議決権を１人分とするというところがあまりにも乱暴な見方だなと思います。法律ですので、国会の議論もあるでしょうけれども、具体的に区としても、ここの規定で住民から声が上がっているわけですから、そのほうにはぜひ向き合って、丁寧な説明をしていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-045"}]},{"id":"topic-05","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今回の区営住宅ですけれども、賃料は月額幾らだったのか。結局、本人との接触といいますか、がどのようにあって、どのようなやり取りがあったのか、もう少し説明していただきたい。今回の場合、いろいろ事情を抱えている可能性がありますので、他部署との連携等、そういったことは何かあったのか伺いたいと思います。","respondent":"川原住宅課長","answer":"そういったやり取りをしていただく中で、滞納分の全額納付をするといった意思が、残念ながら見られませんでした。この状況を説明したところ、本人もそれには応じるというか、納得するといった話があったところです。他部署との連携については私も重視したいと考えています。","voiceIndex":135,"id":"exchange-046"},{"speaker":"安藤委員","kind":"確認","question":"確認なのですが、先ほどのやり取りの中で、最終催告書を送った後に一度接触があったということなのでした。ご本人と話すことができたということなのですが、分割という形でも応じられないかなどという話があったのかというのと、あと最終的には、今のお話ですと、本人も納得して退去するということに、その場ではなったということなのか、その辺を確認させてください。","respondent":"川原住宅課長","answer":"退去しなければいけないことに対しては、本人も状況としては理解はしているけれども、まずそもそも、使用料を、お仕事等もある一定、していらっしゃる方なので、自分の所得の中から払わなければいけないというところの認識が少し薄いのかなと感じておりまして。","voiceIndex":137,"id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"区営住宅ということですので、所得の少ない方が対象というだけに、より丁寧な対応と、また福祉部門との連携が必要であり、より求められると思います。区営住宅ですから、申し込んで、当たって入居するわけですけれども、その過程において何らかの支援が必要なのか、いや、支払うこと自体について、理解しているか確認されているのかというか、どうされていくのか。","respondent":"川原住宅課長","answer":"より早期に、早い段階で、きちんとした金銭管理や生活再生の支援を受け、こういった支援が必要な、方向けの自立支援の施設のほうに入所できれば一番よろしいのかなと考えているところですが、そちらは福祉のほうにつながせていただいているといったところです。","voiceIndex":140,"id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日は区民住宅と区営住宅の住宅使用料の滞納事案に対する対応を伺いました。滞納額の徴収と福祉的な支援をどうつなげていくのか。そこには専門的なスキルが必要だと思うのです。そうした専門的なスキルを福祉部との連携で進めていっていただきたいし、冒頭、様々生活再建のところは既に対応されているということですけれども、最後にそこだけもう一言、伺いたいと思います。","respondent":"川原住宅課長","answer":"住まいの管理を行っている課ですので、当然、福祉職などの専門職といった者は課にはいないわけでありますので、こういった支援が必要と判断している方については、速やかに福祉部につなぐといったことを引き続き行って。","voiceIndex":143,"id":"exchange-049"},{"speaker":"ゆきた委員","kind":"質問","question":"区が長期滞納と判断する基準です。６か月で最終催告と先ほどありましたが、何か月の待機をもって長期とするのか、明確な基準があるのであれば教えてください。先ほど７か月になった際に滞納事務に入るというお話がありましたが、使用許可の取消しや訴訟提起に至る判断基準になっているのか、お聞きできればと思います。","respondent":"川原住宅課長","answer":"滞納整理の開始に関する法的根拠といったご質問であったかと思います。区営住宅であっても、品川区営住宅条例の中で明渡請求権というものを明記しています。","voiceIndex":146,"id":"exchange-050"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。では、長期滞納という定義というところは特にはないということですか。先ほども訴えましたが、区営住宅については特に、住宅セーフティーネットになっていると捉えています。もし明確な基準がないのであれば、訴訟に至る前段階で制度として整備していくべきと考えますが、ここについてお聞きします。","respondent":"川原住宅課長","answer":"十分なヒアリングを行い、例えば病気ですごく医療費がかかっているといったことであれば、減額申請をまずしていただきましょうといった形で、十分に聞き取りをして、使用料が下がる見込みがある方であれば、まずお話をさせていただいています。","voiceIndex":148,"id":"exchange-051"},{"speaker":"ゆきた委員","kind":"意見","question":"もちろんケース・バイ・ケースで、あと個別のヒアリングによって対応が変わるところはあると思うのですけれども、最低限、ルールを明確に基準にしていっていいのかなとは感じましたので、ここについては進めていけるように考慮していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":150,"id":"exchange-052"}]},{"id":"topic-06","title":"目黒川航行マナー啓発活動の実施","agenda":"目黒川航行マナー啓発活動の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"運用が１０回目ということで、定着してきているのかなとは思うのですが、毎年実施していて、マナー啓発の取組の周知度というか、浸透度というのですか、どんなふうに感じていらっしゃるのか伺いたいと思います。未申請の船舶が来たケースなどというのは結構あるものなのか、その辺についても併せて伺います。","respondent":"関根河川下水道課長","answer":"例えば昨年度で申し上げますと、全体の事前の申請された船が１２０隻強、一方で未申請の船舶が１０隻強ということで、１割弱の船舶についてはまだ未申請というところがありますので、引き続き、こうした活動を継続していくことは重要かなと認識しています。","voiceIndex":159,"id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"目黒川のマナーガイドマップ。私は不勉強なので現状をよく把握していないのでご説明いただきたいと思うのですけれども、どんなマナー違反が多発しているのか、この取組をするに当たって、どういう問題が起きているのかということを伺いたいと思います。今のやり取りですと、未申請の船舶が１割程度ということでした。未申請の船舶というのは何の船なのですか。状況を改めてご説明いただきたいと思います。","respondent":"関根河川下水道課長","answer":"２点、ご質問を頂きました。どのようなマナー違反かです。委員ご指摘のとおり、やはり騒音というのも１つございまして、過去にもそういった苦情が寄せられていたところです。近年は騒音の苦情等は減っているところです。","voiceIndex":163,"id":"exchange-054"}]},{"id":"topic-07","title":"水辺のライトアップ更新検討","agenda":"水辺のライトアップ更新検討","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"事業費は幾らなのかということをお伺いしたいと思います。令和７年１２月に契約を締結とありますけれども、こちらの事業費に含まれているのか、ちょっとあれなのですが教えてください。そして、あと水辺のにぎわい創出を目的としてということですけれども、ライトアップが、にぎわいの創出につながっているのかどうか、品川区としてはどういうふうに認識されているのかお伺いしたいと思います。","respondent":"関根河川下水道課長","answer":"２点お尋ねがありました。１点目、費用です。昨年１２月に契約いたしました、水辺のライトアップ更新検討委託につきましては、契約金額９８１万４,２００円となっています。","voiceIndex":170,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと分からなかったのですけれども、いろいろな検討スケジュールが今後予定されているのですけれども、どこの部分が９８１万円なのかというのを、もう少し詳しく教えてもらいたいと思います。それと、にぎわいの創出の件についての、効果検証はこれからということなのですけれども、現時点では、このライトアップがにぎわい創出につながっているといった実態は把握していないという感じでしょうか。","respondent":"関根河川下水道課長","answer":"そういったところで、今後の検討の中ではしっかりと効果を検証する。こちらからも効果的にアピール、ＰＲをしていくためにはどういったものが効果的かということも含めて検討していきたいと考えています。","voiceIndex":172,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問","question":"構想策定に幾らかかるか分かりませんけれども、さらに年間の予算は増えていくという見通しなのか、伺いたいと思います。意外とこういうところにも都市計画交付金など入るのですか。よく分からないのですけれども、国や東京都からどんな補助金があるのか、一般財源を入れているのであればどれぐらいなのか、伺います。何でライトアップしなくてはいけないのか。そこも最後に３点目で伺いたいです。","respondent":"関根河川下水道課長","answer":"１点目の、事業費が増えていくのかという点です。先ほどご説明の中で、今後の検討スケジュール案をお示しさせていただきました。この試行実施あるいは構想策定に当たっては、一定引き続き、事業費を使って検討を進めていくということを考えてあります。","voiceIndex":175,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"これからの予算については検討していくということですけれども、きっと増えていくのかなと私は思っています。水辺は楽しいですよね。そこを説明いただきたいと思います。区の計画で位置づけがあるからという説明ですけれども、何でライトアップする位置づけがあるのか、改めてご説明いただきたいと思います。本当にこれは必要なのかなと正直思っているところなのですけれども、ご説明をお願いします。","respondent":"関根河川下水道課長","answer":"そういった人観点で、ライトアップ等でにぎわいを創出するということが必要だろうという形で、「ヒカリの水辺プロジェクト」を実施してライトアップを進めるというふうになったと認識しています。","voiceIndex":177,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"つまり、そのまちの魅力を、ライトアップで照らしてあげて、開発の機運を一層盛り上げるという、河川下水道課がそこまで考えているかどうかはよく分かりませんけれども、区全体ではそういう位置づけがここにあるのではないですか。水辺でライトアップ。違うなら違うで、何で水辺に、多様で魅力的な夜のライトアップを行うのか、最後まで私には理解できないのですけれども、改めて最後に伺いたいと思います。","respondent":"関根河川下水道課長","answer":"区の所有する橋のうち、目黒川あるいは運河を含め、１３の橋について実施しているものですので、目黒川をはじめとする品川区の水辺全体のにぎわいを創出するための取組ということでご理解いただければと考えています。","voiceIndex":179,"id":"exchange-059"},{"speaker":"ゆきた委員","kind":"確認","question":"１３の橋梁でライトアップを実施していると理解しております。これに関連して、地域の方々から、勝島橋のライトアップが現在行われていない、消えていることについて、疑問の声が寄せられています。現在の状況と、今後もう３月から試行実施ということになっていますが、こちらについて確認でお聞きできればと思います。","respondent":"関根河川下水道課長","answer":"そのため時間を要しており、年度内というのは少し難しいところではありますが、令和８年度には調査、また調査結果を踏まえて補修等を実施していきたいと考えているところです。","voiceIndex":182,"id":"exchange-060"},{"speaker":"ゆきた委員","kind":"確認","question":"現状を確認できました。ということは、勝島橋は、３月に行われる試行実施には間に合うかどうか、まだ不明ということでしょうか。","respondent":"関根河川下水道課長","answer":"３月の試行実施は品川橋のみで実施するという形で考えてあります。勝島橋につきましては、３月の試行実施を予定等はしてございません。","voiceIndex":184,"id":"exchange-061"},{"speaker":"ゆきた委員","kind":"確認","question":"大変失礼しました。確認できました。勝島橋を除いた１３橋梁で、現在、こういった場所というのはあるのかないのか、教えてください。","respondent":"関根河川下水道課長","answer":"やはり、足場をかけないといけなかったり、なかなか維持管理上、正直苦労しているところがあります。そうした中でも、補修等もしながら、今回、将来的な維持管理のしやすいライトアップというのをしっかりと検討して、それを実施していきたいと考えています。","voiceIndex":186,"id":"exchange-062"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"現在、２３区長会等でどのような検討が行われているのかというのを伺いたいのと、品川区としては、この物価高ですから、新たな負担増というのはやはりあり得ないのではないかと思っています。そういった負担増の施策について反対の意見を述べるべきだと思うのですけれども、そちらについての考え方はいかがかということをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"区役所に歩いて来るという訓練だったと思います。去年もやったと思うのですが、何人ぐらいで、実際に、どういう方々がどういうふうに公道を歩いてくるのか。装備はどうするのかなど、区民の方の目にどう映るか、具体的にもう少し教えていただきたいです。","respondent":"星災害対策担当課長","answer":"自転車で来るというところです。装備につきましては、現時点では聞いておりません。前回は訓練に伴うということで、災害時、首都直下地震のときにこちらに来て対応できるような装備で来ると、昨年はそのような状況でしたので、今年も同様の装備だと思います。","voiceIndex":196,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"すみません。こちらは、その他で報告されていますけれども、どこが主催でやるのでしょうか。必要な訓練なのかどうかというのがよく分からないのです。ですから、どこが主催なのかというのと、この訓練の意味というか目的というのですか。そうあってはならないでしょう。ですから、やはり何でこの訓練が必要なのかということを明確にお示しいただかないと、私は承服できないわけです。教えてください。","respondent":"星災害対策担当課長","answer":"昨年実施したときは、能登半島地震の際、道路が潰れてしまいまして、自衛隊の方が徒歩で山越えをして救助に向かったと。そちらを基に訓練を開始したと聞いておりますので、今回も同様の目的を持っての訓練と考えております。","voiceIndex":198,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"最後になりますけれども、「陸上自衛隊がやりますよ」ということで、自治体に協力をお願いしてきたのか、通知してきたのか分からないのですけれども、全ての自治体がやっているわけではないわけです。今回この訓練の、受入れになるのか分からないのですけれども、実施に至るまで、陸上自衛隊と品川区で、どのようなやり取りがあって、受入れに至ったのかというのを、最後に教えてください。","respondent":"星災害対策担当課長","answer":"到着後、隊員がトイレ休憩といったところで、トイレの使用をさせていただきたいと、電話での連絡が入ったところで、品川区役所としても了承して対応するというところになっております。","voiceIndex":200,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7315#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":53001,"voices":205}},{"id":"r08-20260224-9","meetingId":"r08-1t","date":"2026年2月24日","dateIso":"2026-02-24","committee":"文教委員会","time":"午前１０時００分～午後 １時５８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"関係条例の整備等（3議案）","agenda":"関係条例の整備等（3議案）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、主務教諭というのを新たにつくるということで、まずそこを伺っていきたいと思うのですけれども、今回、主務教諭がつくられた理由、背景を伺います。それと、東京都では既に主任教諭というのがあるということで、運用上は主任教諭の名称で扱うということですけれども、主務教諭と主任教諭の関係がどうなるのか伺いたいと思います。今、主任教諭は何人いらっしゃるのか伺います。","respondent":"酒川指導課長","answer":"主任教諭と主務教諭の関係ですけれども、既に２０年ほど前から、一般の教諭よりもより困難な職務を遂行する職として主任教諭というものが置かれておりますので、今回、主務教諭についても、例えば情報教育の推進、地域連携の推進、防災安全教育の推進など。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"確認","question":"国が進める中で、都がやっている主任教諭を参考にされたみたいですけれども、全日本教職員組合の調査では、全国でも東京都の超過勤務が多いということで、待遇改善していると思いますが、いかがでしょうか。給与は、４万円から５万円違うと結構違うという感じがしたのですけれども、これは月額ですか。同じ年齢、同じ経験年数の場合、これだけ違うのか伺います。","respondent":"酒川指導課長","answer":"品川区全体で見ますと、時間外勤務の時間数は国の目標を既に下回っておりますので、主任教諭についても大きな負担になっているとは認識しておりません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"最後の給与の違いは、つまり、単純には比較できないという答弁と認識いたしました。教員同士の協働を困難にしてしまう、上下関係ができてしまうと思うのです。本来、子どもの成長を教員同士一緒に見守っていくということでは、そうした階層をつくるべきではないと思います。実際、分断が生まれると思うのですけれども、いかがでしょうか。こうした実態を区はつかんでいるのか伺います。","respondent":"酒川指導課長","answer":"確かに職層が１つ増えることで、上下関係ができるということは言えると考えていますけれども、主務教諭ですけれども、教諭層の育成サポートを担っておりますので、分断が生まれているとか差別が生じているといった状況については把握しておりません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"そうしたことは把握していない、選考は論文によるということですけれども、あと選考基準はその間の実績も含まれると思うのですが、そうすると、論文だけではないところで管理職の覚えがいい人が受かっていくことになっていくと思うのですが、改めて伺いたいと思います。そうしたことはやはりあってはいけないと思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"把握していないということなので、把握していただけたらと思うのですけれども、いかがでしょうか。ぜひこうした声を区も聞いていただきたいと思うのです。実態を把握していただきたいと思いますが、いかがでしょうか。","respondent":"酒川指導課長","answer":"もちろん不当な理由で合格できないという状況は避けていきたいと思います。これは東京都が行う選考ですので、そちらとも連携していきたいと思います。","voiceIndex":13,"id":"exchange-005"},{"speaker":"のだて委員","kind":"意見","question":"新たに主務教諭を追加することは、教員の間に階層化と分断を生み、教員同士が対等な立場で協働することを困難にするおそれがあります。実際に影響が出ているということで先ほど言いました。業務負担の増大も懸念されます。階層化を条例に位置づけるものですので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-006"},{"speaker":"のだて委員","kind":"意見","question":"管理職の処遇改善は前進面ではありますけれども、主務教諭を新たに追加するのは、第１８号議案と同様の理由で、やるべきではないと考えますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-007"}]},{"id":"topic-02","title":"第１９号・第２１号議案（児童センター・保育所条例）","agenda":"第１９号・第２１号議案（児童センター・保育所条例）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回の条例変更で、三ツ木保育園を品川区立保育所条例から削除するということで、そうすると三ツ木保育園は公立ではなくなるということでいいのか、そこを確認させていただきたいと思います。それと、自治体の保育の実施責任があると思うのですけれども、今回こうした民営化を進めていくのは、保育の実施責任を後退させていくものと思うのですけれども、いかがでしょうか。","respondent":"芝野保育入園調整課長","answer":"品川区の保育責任ですが、こちらは公私連携型の法人になりますので、引き続き協定書内で品川区の保育理念をしっかりと継承させていただき、運営についてもしっかりとモニタリングをさせていただきながら進めていきますので。","voiceIndex":43,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"条例から三ツ木保育園の名称が削除されるこの条例案を見まして、本当に公立ではなくなるのだと感じました。実施責任との関係で、三ツ木保育園を廃止することをどのように認識されているのか伺いたいと思います。併せて、公私連携型保育所になると何が変わるのか伺います。","respondent":"芝野保育入園調整課長","answer":"実施責任ですが、具体的に言いますと、モニタリングをしっかりとやらせていただく、保護者へのアンケート、第三者評価、そして最終的に運営委員会に品川区がしっかりと関与させていただきながら、モニタリングをさせていただきたいと考えています。","voiceIndex":45,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった認識が区としてはあるのかどうか、そこも伺います。今回、２回目の候補者選定委員会では、委員の意見として、事業者の運営規模や過去の施設運営実績を鑑みて、安定的な運営が期待できると述べられているわけですけれども、これが実際にどういう規模で、どういう実績だから継続的かつ安定的だということなのか、具体的に分かっていれば伺います。","respondent":"芝野保育入園調整課長","answer":"例えば小学校との連携ですとか防災関係、地域との交流、こういうところも、地域の子育て施設という観点から、しっかりと運営の中にそれを取り込んでいただくことを目的に、公共性・公益性を、今後、事業者と一緒に詰めていきたいと考えております。","voiceIndex":47,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"勤続年数は５年ということで、以前の質問の中では、区立だと勤続年数は１２.９年、株式会社では６.３年で、やはり職員の勤続年数も区立と私立で変わっている、民間は約半分になっているということです。そうしたことが子どもたちの成長・発達を見守って豊かな保育を実施していく土台になると思いますので、民営化は進めるべきではないと言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほど特定財源が望まれるというお話だったのですが、三ツ木保育園は８０人ぐらいの規模だと伺っています。そうすると、大まかな数字でいいのですが、区の財政負担は今までこれぐらいだったけれども、特定財源やそのほか補助金等でどのぐらい区の負担が減るのか分かる範囲で結構ですので、具体的な数字が分かれば知りたいのでお願いします。","respondent":"芝野保育入園調整課長","answer":"公私連携型保育所に移行した場合、特定財源が見込まれるので、区負担としては年間７,０００万円程度になるという試算をしております。そのため、年間で約９,０００万円の財政負担軽減が見込まれてあります。","voiceIndex":51,"id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問","question":"財政のことだけお尋ねするのですが、９,０００万円の財政負担の軽減について、公私連携型を導入する１つの大きな理由だと思うのですけれども、９,０００万円削減になることについて、区としてどのようにお考えですか。","respondent":"芝野保育入園調整課長","answer":"９,０００万円削減は非常に大きな効果だということもありますが、公私連携型に移行することによって、保育の質が落ちてしまうとかそういうことがあっては制度の趣旨から外れてしまいますので、こちらはしっかりと担保していきたいと考えております。","voiceIndex":53,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"意見","question":"後段でご説明いただいたように、公立でなくなることで保育の質がというところについては十分に留意して、先ほどからご説明いただいていますけれども、そこはきちんとやっていくと理解していますので、こういった財源についての考え方は、今後、いろいろな支出が増えていく中でとても重要だと思うので、今お話があったような形で、公私連携型については、質を担保するのはもちろん前提条件で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-014"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"要望ですけれども、先ほどのだて委員からありました公共性・公益性の部分で、私もやはり園内保育だけにとどまらず、例えば園内解放とか、子育て世代の相談支援といったものを、三ツ木保育園が地域福祉の拠点になるような、何かそういった取組はぜひ区から要望していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-015"},{"speaker":"筒井副委員長","kind":"質問","question":"そもそも公私連携型保育所制度は、財政負担の軽減というメリットとかそういうものがありながらも、完全に民営化してしまうと不安だという声もあるので、その両方のバランスをとった制度だと思っているのですけれども、その他、公私連携型保育所制度の捉え方、意味合いを改めて教えてください。","respondent":"芝野保育入園調整課長","answer":"公私連携型保育所の意味合いは、今副委員長からご説明がありましたとおりの内容でございまして、完全なる民間の保育園ではなく、行政が協定をもって関与していく。","voiceIndex":59,"id":"exchange-016"},{"speaker":"筒井副委員長","kind":"質問","question":"それで、土地・建物は無償貸与していくということなのですけれども、修繕とか、その点、建物もだんだん傷んでくると思うのですが、それは民間事業者が負担するのですか。土地・建物の維持管理とか将来的な修繕の負担はどちらなのかを教えてください。","respondent":"芝野保育入園調整課長","answer":"建物の維持管理ですが、こちらは事業者側に負担させる内容で協定を結ぶ予定です。","voiceIndex":61,"id":"exchange-017"},{"speaker":"若林委員","kind":"提案","question":"それが４つ目。もう１つ、全部聞いてしまいます、選定委員会の委員の意見で、ここが提案としては１つ特記されていると思うのですけれども、３番目のとこで、防災の関係で提案がされていると、防災士の資格取得を奨励するなど、地域の防災力向上に向けた具体的な取組みが提案されていると強調されておりますので、どんな提案内容なのかも教えていただきたいと思います。","respondent":"芝野保育入園調整課長","answer":"選定委員会で防災関係の評価ということで書かれてありますが、具体的には、区が主催する防災訓練等に参加していこうということで、今、準備を進めているということと、あと、研修等も品川区で実施しておりますので、とにかく地域の防災をまず知って。","voiceIndex":64,"id":"exchange-018"},{"speaker":"若林委員","kind":"確認","question":"最初の指定管理者制度の選考方法に準じてとは、どこが決めたのでしょうか。そこは確認したいと思います。","respondent":"芝野保育入園調整課長","answer":"５年間の効果検証を、指定管理者制度も原則５年ということで進めていますが、その後、指定管理を更新する際に、ガイドラインに基づいてやっている。それが今回の公私連携型の選定方法に一番合致しているという考え方を基に、今回採用させていただいているところです。","voiceIndex":66,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"そうすると、子ども未来部で決定して、区の執行部も了解したというということで認識したいと思いますが、お聞きします。","respondent":"芝野保育入園調整課長","answer":"そうです、きっちりとトップまで決裁を取りまして、区の決定として今回の選定を行っております。","voiceIndex":68,"id":"exchange-020"},{"speaker":"横山委員","kind":"質問・要望","question":"１点、文教委員会で報告があったと思うのですけれども、そのときにインセンティブの付与とあったのですが、確認ですけれども、インセンティブの付与はどういった内容で最終的には確定しているのか、土地と建物なのか、設備面も何かあるのか教えてください。","respondent":"芝野保育入園調整課長","answer":"児童虐待の取組ですが、こちらにつきましては、提案書でいただいているのですが、複数人保育の徹底とか、あと、定期的な研修の実施、園全体でこれに対しては積極的に取り組んでいこうという考え方を示しておりますので、年度が変わって公私連携型になっても、区も関与しますので。","voiceIndex":71,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"児童虐待はやっていただくと確認していたのですけれども、質問したのが、子どもの事故の予防の部分、例えば子どもの事故の予防について、研修であるとか、あとハード面の整備、そういった両面で子どもの事故の予防は大切になってくると思いますので、その辺りも区として研修を充実していただくような働きかけであったり、ハード面の整備であったりは事業者でやっていただくお話になると思いますので。","respondent":"芝野保育入園調整課長","answer":"保育園の事故予防については、しっかりと連携をとりながら、事業者任せにしないというのが第一にありますので、しっかりと機会を捉えて、こちらでも働きかけを行っていきたいと考えております。","voiceIndex":73,"id":"exchange-022"},{"speaker":"若林委員","kind":"意見","question":"東五反田保育園・児童センターを忘れていました。ケアすべきなのはどういうところと考えていらっしゃるのかというのが１つ。東五反田のときは、周りにはそういう子どもの教育関連施設はなかったと思うのですけれども、そういう環境に移るということで、そんなに何年もここにいらっしゃるわけではないのですが、新しい環境の中でどのように事業展開を考えておられるのか、お考えは聞いておきたいと思います。","respondent":"上野子ども育成課長","answer":"１点目、児童センターの移転に伴って、子どもたちの顔ぶれが変わる見込みについて、どうケアをしていくかですけれども、まずは、現施設から仮施設に移るということで、移転先のご案内はしっかりしていく、それから子どもたちの様子につきましても。","voiceIndex":76,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"すみません、最後に。公私連携型保育所と結ばれる協定書の中身で何を決めるのか、先ほど来、区の理念はそこで継承されるということでしたけれども、区の理念は何なのかを伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"こちらの保育理念をしっかりと公私連携型の法人にも伝え、継承していっていただきたいと考えております。","voiceIndex":78,"id":"exchange-024"}]},{"id":"topic-03","title":"第２０号議案、品川区子ども家庭支援センター条例の一部を改正する条例","agenda":"第２０号議案、品川区子ども家庭支援センター条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"品川区子ども家庭支援センターの賃貸借契約期間が満了ということですけれども、契約継続は検討したのか。移転の経緯を伺います。移ろうとしている場所は、広さ的にはどうなるのでしょうか。広くなるのか狭くなるのか、十分な業務上の広さを確保できるのか、あと、場所が変わることになると、利用者への周知もやっていただきたいと思うのですが、どのようにしようとしているのか伺います。","respondent":"吉野子ども家庭支援センター長","answer":"こちらも利用するようになりますが、若干狭くはなります。それから、利用の周知ですけれども、こちらはホームページ、それから４月１日号の広報にてお知らせする予定です。","voiceIndex":100,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"広さは狭くなるということで、今までの業務を今後、十分継続できるのか伺いたいのと、あと、利用者の周知は広報でやるということで、当然利用者の方には直接通知をしていくということでいいのでしょうか。","respondent":"吉野子ども家庭支援センター長","answer":"今までの業務には、支障がないようにしっかりとやっていきたいと考えております。周知ですけれども、現在利用されている方にも周知をしっかりとやっていきたいと思います。","voiceIndex":102,"id":"exchange-026"}]},{"id":"topic-04","title":"第２２号・第２３号議案（乳児等通園支援事業）","agenda":"第２２号・第２３号議案（乳児等通園支援事業）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この中身は国が進めるこども誰でも通園制度のものだと思います。条例は、第２２号議案のところで伺いたいのですが、第１７条で利用定員が、もともと乳児および幼児の区分ごとの利用定員となっていたのが、単に利用定員に変更されるということですけれども、こうした理由を伺いたいのと、変更によって生じるメリット・デメリットを伺いたいと思います。それと、第２２号議案と第２３号議案の関係性を伺います。","respondent":"佐藤保育事業担当課長","answer":"利用定員の区分の変更について、国に確認したところ、乳児と幼児の区分をなくすことによって、より柔軟に受入れをすることができるようになり、利用者にとっての利便性が向上することを理由に、区分ごとの分けがなくなったと認識しています。","voiceIndex":116,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"第２２号議案の利用定員ですけれども、メリットの面は柔軟に対応できるということで伺ったのですが、デメリットはないのか伺いたいと思います。今回、一般型と余裕活用型ということで実施方法がありますけれども、一般型のやり方を選択した事業者は、どういった理由から選択しているのか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"一般型は専任の職員の方がついて対応することになりますので、懸念されていたような危険性には対応できるものと考えております。次に、国との事業の違いについてですが、大きな違いとしては、まず利用料金の設定が、区としては無償となっている。","voiceIndex":118,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり体制の問題です。時間のところは、今回、月３０時間にしたということで、そうすると、１日６時間利用したら月５回、５時間だったら６回で、週一、二回になると思うのですけれども、そうするとなかなか保育園に慣れない、週１回になってしまうとまたゼロに戻ってしまう感じもするのですが、今後、利用時間の拡大の可能性はあるのか伺います。","respondent":"佐藤保育事業担当課長","answer":"大きな違いとして、国は１時間当たりで補助、公定価格として支給されるのですけれども、区としては、まず定額で２０万円を超える補助事業を実施予定です。","voiceIndex":120,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回実施していく園の候補が６０園あるということで、すみません、さっき聞きそびれたのですけれども、第２２号議案と第２３号議案の基準で、項目があるものとないものがあると思うのですが、同じものがあるとすれば、違いとかはあるのか伺います。つまり、どちらかは、認可はされるけれども確認はされない、つまり公定価格が出ない、そうしたこともあるのか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"横の連携についてですが、区といたしましても、先ほどお話しさせていただいたような事業実施に当たる懸念事項などについては、様々な園に共有していただきたいと考えていますし、その対策については、好事例についても共有していきたいと思ってありますので、今後。","voiceIndex":122,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"園長だけでなく、職員同士も実際に現場でできるところがあれば、ぜひそうした交流もしていただけたらと思います。０～２歳ということで実施されると思うのですけれども、やはりこうした年齢は事故とかが一番起こりやすい年齢になりますので、こうしたことがないように、また、豊かな保育ができる体制をとっていくようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-031"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"利用者が急増したときでも、財政的な安定はあるのか１つ教えていただきたいのと、今お話がありましたけれども、８割ぐらいが余裕活用型です。これは各クラスの保育者による受入れが基本となっていますが、例えば突発的な利用があると、さっきの話ではないですけれども、現場の保育士の過重労働につながらないのか心配があるのですが、まずそこを教えてください。","respondent":"佐藤保育事業担当課長","answer":"予算につきましては、今年度よりも約倍増した形で予算措置を予定していますので、一定程度の需給に関しては対応できると考えています。空き利用に関する現場負担ですが、一般型を利用されている園に関しては、定員がありますので、一定程度予定されているものです。","voiceIndex":126,"id":"exchange-032"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"仕方ないことかもしれないですけれども、これは本当にとてもいいことなので、やはり全区的な標準化に向けて、未実施の園へインセンティブを付与していくとか、そういった検討などもぜひしていただきたいと思うのですが、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"利用者が利用したいときに使えないことがあるのかですが、現在、計画上では、各地域ごとの未就学児童の人口ですとか、その方たちがどれだけ保育園などを利用されているか、また、乳児等通園支援事業の利用率などを勘案して。","voiceIndex":128,"id":"exchange-033"},{"speaker":"筒井副委員長","kind":"質問","question":"定期利用についてですけれども、利用する曜日や時間帯を固定してということですが、あらかじめ決まっているほうが保育園は対応しやすいと思うのですけれども、利用者が定期利用で登録していた日以外に急に利用したい場合はどう対応されるのか、試行的事業のときにそういったことは出てこなかったのか、その点をお聞きしたいと思います。","respondent":"佐藤保育事業担当課長","answer":"利用者の予定変更についてですけれども、まず、本事業は、お子様の良質な成育環境の提供が大きな目的ですので、急な予定により保育施設等を利用したいというものとは目的が異なるものでございまして、急に保育園等が必要になった場合は、一時保育利用がありますので。","voiceIndex":131,"id":"exchange-034"},{"speaker":"筒井副委員長","kind":"質問","question":"ほかに、試行的事業のときに出た課題、これは直さなければいけないという点が何かありましたら、教えてください。","respondent":"佐藤保育事業担当課長","answer":"来年度に向けた課題としては、予約システム等が新たに始まりますので、施設の方に丁寧な説明をさせていただきたい、また、利用者にとっても分かりやすく利用できるような支援をしていきたいと考えております。","voiceIndex":133,"id":"exchange-035"},{"speaker":"横山委員","kind":"確認","question":"令和７年度も実施をしていると思うのですけれども、定期的に保護者の方と実施の施設で面談を行うですとか、あとは、利用中・利用前・利用後のアンケートなどにもご協力いただいてきたと思うのですけれども、どういった内容のアンケート結果ですとかお声があったのか、効果検証をしていただいての、今回、これからの実施だと思うのですけれども、どういった形で検証されたのか。","respondent":"佐藤保育事業担当課長","answer":"来年度に向けた事業の検証についてですが、先ほどのアンケートや、実施していただいている事業者とお話をさせていただいて、良質な成育環境の提供においては非常に意義のある事業であると考えておりまして、特に時間について。","voiceIndex":136,"id":"exchange-036"},{"speaker":"横山委員","kind":"確認","question":"お子さんのコミュニケーションであったりとか社会性を身につける部分での成長であったり、保護者の方のリフレッシュであったり、ご自身の子育てがどういった形で、評価や専門の保育園の先生からのフィードバックがあって安心されたりというような効果が出ていると、確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-037"},{"speaker":"若林委員","kind":"意見","question":"第２３号議案で、第６条に、保護者から利用の申込みを受けたときは、正当な理由がなければ、これを拒んではならないという条文がありますけれども、逆に拒むときもあるということですよね。それは、試行実施の中も含めて、どういうご様子、また、考え方なのか。国ではこのように示されているとか、何かコメントをいただければと思います。","respondent":"佐藤保育事業担当課長","answer":"試行的事業の中において、そこが争点となるようなご意見やクレームを受けたことはなかったと認識しております。","voiceIndex":140,"id":"exchange-038"},{"speaker":"若林委員","kind":"確認","question":"全然関連する話ではありませんが、いわゆる幼稚園・保育園も特別支援という教育・保育があって、面談をした上で、親御さんも確認しながらですが、逆に、通常の保育・幼稚園ではそういう方が普通に在籍していらっしゃる、これは当たり前の話で、そうすると、こども誰でも通園についても、いわゆる特別な支援が必要な方がいらっしゃるのは当たり前のことで、そういったときに、園の体制。","respondent":"佐藤保育事業担当課長","answer":"保育体制が厳しい状況も想定されるのですけれども、区としては来年度、医療的ケアが必要なお子さんの居宅に訪問してお預かりするような事業も新たに実施予定ですので、様々な取組の中で、そうしたニーズにも応えていける体制づくりも継続して実施しています。","voiceIndex":142,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"しっかりと事故も起きないように、豊かな保育が実施できるような体制をとることを求めたいと思います。今回、区がやる中で、時間利用も月３０時間に拡大し、無償で利用できる、安定的にできるように定期利用にしていく。国は３歳になったら打ち切りという感じですけれども、区では年度末まで利用できるというところで、こうした前進面も評価をして、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-040"}]},{"id":"topic-05","title":"品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回増額になるということですけれども、その理由、背景を伺います。実際にこれまで区ではこうした事例はあるのか伺いたいと思います。","respondent":"石井学務課長","answer":"本件ですが、平成１３年度までは東京都の条例だったのですけれども、その後、区に条例が移管された後は、本条例による補償は今まで発生してございません。","voiceIndex":164,"id":"exchange-041"}]},{"id":"topic-06","title":"令和８年請願第１号、一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"令和８年請願第１号、一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、一人ひとりの子どもが大切にされる品川区を求める請願ということで出されて、１,２４２名、後日１１名と、あと本日もあったので、１,２５３名プラス本日分ということで、多くの方から署名が集まっている。今回、職員の配置基準、そしてベースの拡充を求める中身になっておりますが、先ほど国の配置基準を説明いただきました。区としてはこの配置基準で十分だと考えているのか伺います。","respondent":"佐藤保育事業担当課長","answer":"区の認識ですが、まず国の配置基準につきましては、様々、国におきまして有識者等との話合い等が行われた上で、保育園を運営するために必要な基準を設けてありますので、区としても、園を運営していくために必要な最低基準としては、この基準が適切と考えています。","voiceIndex":183,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"最低基準としては適切だということで、実際に保育をやっていく上でどれだけ必要なのかという点では、十分だと考えているのか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"ですので、明確に十分な基準をお伝えするのはなかなか難しいですが、区としては、充実した人員配置は必要である、または支援していく必要性があると考えておりまして、冒頭でご説明させていただいたような補助メニューを整備しています。","voiceIndex":185,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"区としては支援しているということで、そうであるならば、配置基準もぜひ区独自に引き上げていくことをお願いしたいと思うのですけれども、いかがでしょうか。やはり充実した保育を行っていくという点では、この基準をさらに上げていくことが必要だと思いますけれども、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"基準について様々なお考え、または状況があるかと認識していますけれども、国の基準につきましても、冒頭でお話しさせていただいたように、令和５年度には状況等を考えた上での改善をされてあります。","voiceIndex":187,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区は増えている部分もあるとは思うのですけれども、そうした中で保育の質を上げていくことも一緒に求められてくると思います。これは認可保育所でも認証保育所でも声が出ています。いかがでしょうか。今の制度が、子どもはいないけれども定員数の保育士を配置しなければならないわけですから、そこに対する委託費が出ない制度は問題だと思うのですけれども、区は問題と思わないのか、認識を伺います。","respondent":"佐藤保育事業担当課長","answer":"続きまして、公定価格の支給基準ですが、制度自体は国において定められているものですので、適切かについてはなかなか明確なご回答が難しいですが、区としても経営支援は重要な課題と認識していますので、看護師の配置ですとか。","voiceIndex":189,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"定員割れのところは、なかなか明確な答弁は難しいと。各区の取組を見ると、２３区の中でも２０区が定員割れに対する何らかの補助を行っているということで、認証保育所にも補助金を出している区が複数あるのですから、ぜひ品川区としても定員未充足に対する補填、補助をやっていただきたい。それがやはり区の保育を豊かにしていく、守っていくことになると思うのですけれども、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"最低水準以上の職員配置ができているかですけれども、冒頭でご説明させていただいたような補助を実施してございまして、事業実績がありますので、様々な事業所において国基準以上の人員が配置されていると認識しております。","voiceIndex":191,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"認証保育所については都の制度であるのは確かですけれども、区の保育を担っている園であることも確かですので、そこはぜひしっかりと運営していけるように支援をしていただきたいと思うのですが、いかがでしょうか。もし閉園になってしまったら、通っていた人たちは保育を受けられなくなってしまうことになるわけですから、そうした影響をどう考えていらっしゃるのか伺います。","respondent":"佐藤保育事業担当課長","answer":"認証保育所につきましては、先ほどお伝えさせていただいたように、根本的な運営につきましては東京都において検討され、広域的に実施されるのが適切と考えています。","voiceIndex":193,"id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ支援はしていると言いながら、定員未充足の補助はしないということで、直接的なところでは、今の運営自体が大変になっている中で、新たにこども誰でも通園制度ですとか、ほかの子どもを空いているところで受け入れてやっていくことは保育士にも負担になって、やはり運営努力だけではどうにもならない状況になっているので、ぜひそこは補助をやっていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-048"},{"speaker":"筒井副委員長","kind":"意見","question":"国の最低基準は２年ほど前の国のこども未来戦略会議等で話し合われたばかりですし、実際、基準を上回るものを品川区で独自に設定した場合、実質上、物理的な問題や、やったところで困難だということと、不足分の補填につきましては、品川区としてもほかの様々な支援策をやっている中、さらにその不足分を補填するのは、区の財政負担もありますので、今回はそうした理由で不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":198,"id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。基準、それから補填の考え方も議論がありました。いずれにしても、区立保育園のみならず、私立保育園、しっかりと行政が一定の関与をし続けながら、そのときのニーズに応じて質のよい保育行政に邁進していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。保育士の配置基準も平米数もぜひ引き上げて、豊かな保育にしていただきたいと思いますし、定員割れの補助についても、やはり今、園運営が大変なところをしっかり支援していくべきだと思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。今ご説明いただいたように、国基準を超える様々な形の補助をしている状況であります。ということから、請願でいただいたご希望には沿い難いということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-052"},{"speaker":"横山委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。区として様々取り組んでいただいている内容のご説明がありました。引き続き子どもたちを中心に据えて、現場の方々のお声を伺いながら、品川区の実情に合わせた運営への支援をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-053"}]},{"id":"topic-07","title":"令和８年陳情第８号、生成ＡＩ時代におけるネットリテラシー教育の機会創出を求める陳情","agenda":"令和８年陳情第８号、生成ＡＩ時代におけるネットリテラシー教育の機会創出を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"区としては、こうした危険性、リスクをどう考えているのかを伺います。現状、先ほど少しご説明ありましたけれども、ＧＩＧＡワークブックとうきょうで、生成ＡＩ、ディープフェイクなどを含め、危険性を学んでいるのか、もし学んでいるとしたら、どんな形でやっているのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"今後、さらに急速に発展していくものではありますけれども、児童生徒向けの教材や、そうしたものは出てくるものと捉えているところです。","voiceIndex":210,"id":"exchange-054"},{"speaker":"のだて委員","kind":"提案","question":"この陳情で提案されているのが、講座ですとかワークショップをやって、恐らく体験しながら、危険性、あと有用性も学んでいこうということだと思います。こうした取組についての区の認識を伺います。実際に今こういうことをやっているのであれば、そのご説明もいただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"そういったものを各学校の担当者、管理職、また、教育委員会が判断しながら進めていくことが望ましいと考えております。","voiceIndex":212,"id":"exchange-055"},{"speaker":"のだて委員","kind":"意見","question":"そうですね、未然に防ぐということで、こうしたことを事前に知らないと、本物のようなディープフェイクがあふれておりますので、そうしたものにだまされないような教育を、区でも既に始めている部分もありながら、やっていく方向だということですので、ぜひ議会としてもこれを後押しするということで進めていきたいと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":214,"id":"exchange-056"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"１番目については、東京都のＧＩＧＡワークブックとうきょうを使用した教育をやっており、ほか、外部講師をお招きし、授業をやられているということと、２つ目については、無償・有償を問わず、講師を招かれており、必要があれば費用もお支払いしているということで、求めることについてはかなりかなっていると思います。したがって、結論としては不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":217,"id":"exchange-057"},{"speaker":"若林委員","kind":"意見","question":"重なりますけれども、東京都のＧＩＧＡワークブックとうきょう、また、携帯電話会社も含めた講師のご協力を得て、ネットリテラシー教育をやっていらっしゃるというのは一定程度認識いたしましたし、今後、生成ＡＩについて、どこまで学校現場で、文部科学省のガイドラインでも保護者との連携が重要視されていますので、総合的に、本当にどこまで、日進月歩ですので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":218,"id":"exchange-058"},{"speaker":"のだて委員","kind":"提案","question":"本日結論を出すということで、採択を主張します。今、区もやっている中で、そうした中にこの提案も盛り込みながらやっていけばいいと思いますし、やはりだまされないようにしていくためには、これを学んでいくことは重要だと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":219,"id":"exchange-059"},{"speaker":"高橋（し）委員","kind":"質問","question":"ただ、それは実は単発であって、やはりどこが大事かというと、通常の授業の中で各先生方が、例えば国語の授業だとか社会科の授業の中でネットリテラシー、そして生成ＡＩを活用して、１年間の授業の中、６年間の授業の中で働きかけをするチャンスはたくさんあるので、学校公開に行くと、そういう授業をされている先生方もいらっしゃるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-060"}]},{"id":"topic-08","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、損害賠償額が１３０万円で、少し大きいと思ったのですけれども、これは門扉を全部新しいものに取り替えたのですか。一部破損だけれども、使えなくなってしまったということなのか伺います。","respondent":"舩木庶務課長","answer":"ただいま委員のご指摘のとおり、破損した門扉が廃盤品だったことから、類似品同等品を新たに新規に交換しなければならなかったこと、そして、門扉以外のブロックフェンスも基礎から交換するという工事が伴いまして、資料にあります損害賠償額になったものです。","voiceIndex":228,"id":"exchange-061"},{"speaker":"まつざわ委員","kind":"確認","question":"こういう事故はいろいろなところで起こるのですけれども、例えば本当はバックソナーなんかが付いているといいのでしょうが、なかなかそういうものがないとすると、安全基準のマニュアルですか、私、消防団だと、消防車を運行するときは絶対に２人、バックするときは必ず後方確認をすることは決められているのです。","respondent":"舩木庶務課長","answer":"狭隘な道路だったこともありますが、そういった部分についてはより一層、運転の技術力もあるのかもしれませんけれども、そこについてはやはり区の職員という意識を強く持って、安全確認を含めて、繰り返しになりますけれども。","voiceIndex":232,"id":"exchange-062"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"おっしゃることはよく分かりますけれども、でも、やはり事故は起こってしまう。よりしっかりするには、やはりルールづくり、体制づくりはある程度マニュアル化したほうがいいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":234,"id":"exchange-063"}]},{"id":"topic-09","title":"令和８年度私立保育園の設置等","agenda":"令和８年度私立保育園の設置等","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"後ろの設置者の変更です。これは変更になった理由、背景を伺いたいと思います。併せて、株式会社ディアローグは、区内で実施するのは初めてですか。今回、見ると、定員６０名の中で、１歳から５歳、全部１２名で、大体区のものだと年齢によって定員数が変わってくると思うのですけれども、こうした定員になっているのはどういった理由なのか伺います。確認させていただきたいと思います。","respondent":"佐藤保育事業担当課長、芝野保育入園調整課長","answer":"設置者の変更についてですが、もともと株式会社ソラストに事業運営をしていただいておりまして、こちらの法人は様々な事業、例えば介護とか、幅広く実施されていた事業者でございました。私からは、新規園２園の状況についてご説明申し上げます。株式会社ディアローグと株式会社テノ．コーポレーションの人件費比率等は、申し訳ございません、いずれも数字を持ち合わせておりません。","voiceIndex":241,"id":"exchange-064"},{"speaker":"のだて委員","kind":"質問・要望","question":"新規園の設置者の人件費とかは分からないということで、ぜひそこは把握していただいて、把握せずに保育の質を担保できるのかというのがあるのですけれども、そこを伺いたいと思います。安全性も含めてそうした保育が確保されるように、区としても支援していただけたらと思いますし、ぜひ園庭を設置できるような、園庭を設置する補助もやっていただきたいと思います。","respondent":"芝野保育入園調整課長","answer":"保育の質の担保のご質問ですが、先ほども申しましたように、株式会社ディアローグは都内でしっかりと園を運営しておりますし、株式会社テノ．コーポレーションも区内２か所、東五反田と東品川で運営実績が今ありますので、こちらも踏まえまして、質を十分担保できるだろうと。","voiceIndex":244,"id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ保育の質を担保し、よくしていくというところで、保育士の待遇も含めて確認していただいて、区の保育がよくなるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":246,"id":"exchange-066"}]},{"id":"topic-10","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"」という話になるので、教育委員会としてどのようにして周知していくのかをお尋ねします。それから３つ目は、これは正確か、（仮称）サポートセンターを令和８年度ですか、というお話があったので、それについて、現時点でお答えできる範囲で、どのような事業として、それが教員の様々な働き方をカバーしていくのか教えてください。３つ、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":249,"id":"exchange-067"},{"speaker":"横山委員","kind":"質問","question":"私も高橋しんじ委員とかぶってしまうのですけれども、一部、周知で、学校・保護者という話があったのですけれども、地域や議会に対してですとか、区内全体、どのように周知していくのかをお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-068"},{"speaker":"高橋（し）委員","kind":"質問","question":"今委員長にご説明いただいたのですけれども、ガイドラインはまだ実際にこれで品川区の学校で何かをしたということは恐らくないと思うので、それが来年度、現実的に、これまで小中学校でこういうことがあったけれども、それはこのガイドラインによってこう解決していくだろうということをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7313#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":47121,"voices":256}},{"id":"r08-20260224-5","meetingId":"r08-1t","date":"2026年2月24日","dateIso":"2026-02-24","committee":"総務委員会","time":"午前１０時００分～午後 ４時４４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を139件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４０号議案、電線共同溝等工事（競馬場通り）委託契約の変更","agenda":"第４０号議案、電線共同溝等工事（競馬場通り）委託契約の変更","exchanges":[{"speaker":"西本委員","kind":"確認","question":"工期を延長というのは分かりました。私が聞き漏らしていたら、ごめんなさい。延長した理由というか、もう一度、説明してください。それと、変更金額ですけれども、それは全額は、東京都から出していただけるということなのでしょうか。確認いたします。","respondent":"森道路課長","answer":"費用につきましては、東京都に出していただける部分もありますし、国から出てくる分もあります。それは例えば２分の１だったり、１０分の５.５だったりという形になりますけれども、残りの部分については、区の負担ということになります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"事前には、やはり分からないものなのですか。それと、品川区も費用を出すことになるのですか。もともと競馬場通りの無電柱化は、東京オリンピックがあって、その中で、ここを無電柱化にするという話になっているわけだから、別に品川区が要望しているわけではなくて、東京オリンピックがあってということだと思ったのですけれども、それで品川区は負担があるのか、ないのか、そこをもう少し教えてください。","respondent":"森道路課長","answer":"オリンピックも１つの契機ではありますけれども、無電柱化するための１つの大きな目的としては、緊急輸送道路の無電柱化をして、電柱の倒壊を未然に防ぐというところがありますので、区としても一定の負担が出ることになります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"意見","question":"負担額はどのぐらいを検討していますか。初めからそういうお約束でしたかという、そこら辺の変更があったのか、初めからそういう状況でしたよということなのか、あと、区の負担額、どのぐらいになるのか、もう一度ご説明ください。","respondent":"森道路課長","answer":"東京都が２１％、国から１４％という形で、半分近くが国や都の補助金ということになります。本路線につきましては、先ほど申しましたように、防災に寄与する路線というふうに位置づけられておりまして、当初からそういった目的があったものと認識しております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"意見だけなのですけれども、契約金額が当初約４億円がかかっている中で、今回、６億１,７３９万円余となる。昨今は、本当にこういう地中埋設物等いろいろあって、金額というよりは、その割合が５割も上がっていくということに、我々もだんだん違和感がなくなってきてしまうのです。こういう状況を見て、埋設物がありました。それだけ意見として言わせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"}]},{"id":"topic-02","title":"第４１号議案、（仮称）勝島人道橋上部工整備工事請負契約の変更","agenda":"第４１号議案、（仮称）勝島人道橋上部工整備工事請負契約の変更","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今の説明だけでは少し分からないです。なぜ工期が延伸になったのですか。その理由をお尋ねします。そして、変更金額が約１億円になるので、これもなぜというところがあるので、もう少しご説明をお願いします。","respondent":"森道路課長","answer":"現場に持ってきて、５０ｍ以上の長さがありますけれども、それを５分割して持ってきて、１つずつジャッキアップをして、溶接して接続するという方法をとろうと、これは変わらないのですけれども、実際に設置するに当たって、高欄が先についていると。","voiceIndex":25,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"そうなのです、説明してほしかった。そうすると、今回は分かりました。後でやるところが、前倒しでできるようになった。そのため、工事費も増えたと。後で行う工事の金額は変わらないのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"意見","question":"共産党は、この下部工事にも反対をしておりまして、まちづくりとはいえ、再開発につながるというところを危惧しておりますということで反対をしてきました。この橋をつけること自体に反対をしてきましたので、本件についても反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-007"}]},{"id":"topic-03","title":"第４２号議案、勝島地区雨水管整備工事請負契約の変更","agenda":"第４２号議案、勝島地区雨水管整備工事請負契約の変更","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これも変更の理由というところのご説明をぜひお願いいたします。それと、契約金額がプラスになっているものについて、品川区の負担額はどうなっているかということを伺います。","respondent":"関根河川下水道課長","answer":"私から、変更の理由、それから区の負担についてご説明します。変更の理由、具体的なところですが、実際に整備内容としましては、地面を掘って縦穴をつくり、地下から下水道管、トンネルの形で下水道管を整備するものです。","voiceIndex":47,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"この地下埋設物は何ですか。どういうものなのかというところが分かれば、教えてほしいと思います。工期の延長が３４０日ということは、１年なのですね。大きな影響はないのか。ただ単に工期が延びるだけですという説明でいいのか、埋設物を掘り返していくのでしょうから、それによっては工事のエリアが広がってしまうということも考えられるのですけれども、それはいかがでしょうか。","respondent":"関根河川下水道課長","answer":"工事の延長に伴う住民の方へのご説明ですが、こちらは、大井競馬場の近くで工事をするということもございまして、大井競馬場には個別にご説明をさせていただいているほか、まちづくり協議会のほうにも出席をして、工事の状況ですとか。","voiceIndex":49,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"先ほどもありましたけれども、台帳と比べてとあるのですけれども、位置がずれているわけですよね。これはやはりずれるものなのですか。これは掘ってみないと分からないということで、そこは誤差の範囲のものなのか、そこの度合いはどのようなものか教えてほしいのですけれども。","respondent":"関根河川下水道課長","answer":"今回の工事につきましては、想定の位置から１ｍぐらい我々の造るマンホールの位置に近かったです。","voiceIndex":51,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"これに準ずるかどうか分からないのですが、先ほどもほかの事業であったのですけれども、後で埋設物が近くに見つかった云々あるのですけれども、逆に、工事が始まる前に、ボーリング調査をやる。それをやったほうが安く上がるのでしょうか。要は、ボーリング調査をある程度やると、結果が出る。それを避けて設計ができる。では、設計変更しようという形に持っていくのですか。","respondent":"関根河川下水道課長","answer":"事前にやっても、その結果として、より高価な方法を選択せざるを得ないという形になりますと、一概に先にやったから必ず経済的になるかどうかというのは、なかなか断定はできないかなというふうに考えてあります。","voiceIndex":53,"id":"exchange-011"}]},{"id":"topic-04","title":"第４３号議案、第二戸越幹線整備工事（取水および空気抜き設備等整備）請負契約の変更","agenda":"第４３号議案、第二戸越幹線整備工事（取水および空気抜き設備等整備）請負契約の変更","exchanges":[{"speaker":"西本委員","kind":"質問","question":"申し訳ないのですけれども、変更の理由を教えてくださいということと、それと、これ、工期は変わらないのですね。開口補強ということで、新たな工事があるようになるのですけれども、このまま後期の変更なしでできるのかどうかお聞かせください。","respondent":"関根河川下水道課長","answer":"工期の延伸は必要ないかですが、今回の変更につきましては、工事の延長は必要ないという形で、当初の工期どおり施工ができる見込みです。","voiceIndex":68,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"計算でという形なのですよね。結構難しいところに下から上に上がっていくわけですから、そこが少しずれただけでも、またきちんとつながればいいのですけれども、そこを今、計算というふうな形でおっしゃったと思うのですけれども、そうなってくると、計算値と実際とかずれたりとかというようなことは生じない。結構精度が高い形でこの工法をやれているよということなのか、その辺はいかがですか。","respondent":"関根河川下水道課長","answer":"その一環という意味では、今回の変更の中でも、９ページの６、変更概要の３つ目の項目、準備費のところに、変位計設置工事の追加というふうにあります。こういったいろいろな計測を活用しながら、精度よく工事を進めていくという予定にしています。","voiceIndex":70,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"少しお聞きしたいのですが、これも制限付一般競争入札ということですけれども、入札価格を試算するに当たって、やはり専門工事だから、私は、品川区のほうでもちろんできないと思うのですが、そうすると、ほぼ特定の業者との随意契約みたいな形になって決まってしまうのかなということすら思うのですけれども、実際、入札価格を出すに当たって、区としては、どのように対応しているのですか。","respondent":"関根河川下水道課長","answer":"もちろん委員もおっしゃったように、特別なものと、一部そういった材料については見積りを徴収するような形もありますが、その際にも一定金額以上の材料の場合は、下水道局が行う特別調査を活用しながら、適正な発注価格になるような積算をしています。","voiceIndex":72,"id":"exchange-014"},{"speaker":"塚本副委員長","kind":"質問","question":"その額も５割増しぐらいのものが２つぐらいあって、このぐらい大きな金額になってきてしまうと、やはり財源的に工事自体を支えられるのかというか、必要だから払わざるを得ない、工事を達成するには、予算を何とか確保しなければいけないということがあるのだと思うのですけれども、そこら辺は、当初予算の中でどれぐらい耐えられるように考えているのかということと、もう１つは。","respondent":"関根河川下水道課長","answer":"基本的には、やはり工事と一体となって試験掘りもするということが効率的かなというふうには考えているところですが、下水道局のほうでは、一部、明らかに台帳上も輻輳しているといった場所については、事前に試験掘りを行うといったことも実施しておりますので。","voiceIndex":74,"id":"exchange-015"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"例えば、どうしても契約金額に大きな変更が起きて財源が新たに必要だとなると、場合によっては補正予算ということも手法としてはあると思うのですけれども、そういうときに充てるべき財源は、どういうところが想定されるのかということだけ最後に教えていただきたいと思います。","respondent":"加島財政課長","answer":"工事を進めている中で特殊な事情といいますか、特別な事情があって補正予算を必要とする場合の財源というところですけれども、今回のような工事であれば、一定程度、議会のご判断も必要ですが、公共施設整備基金であったり。","voiceIndex":76,"id":"exchange-016"}]},{"id":"topic-05","title":"第４４号議案、鈴ケ森小学校校舎改築工事請負契約","agenda":"第４４号議案、鈴ケ森小学校校舎改築工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１校当たり、ほかの学校を見てもそうなのですが、非常に疑問に思うのと、それと、やはり入札に当たって、今回、応募が２者あって、１者が辞退というようなことですが、これを見る限りにおいては、公平公正な入札制度にのっとっていないのではないかなということすら感じられるのですが、その辺について、経理課としてどのようにお考えなのでしょうか。","respondent":"荒木学校施設担当課長、佐藤経理課長","answer":"ですので、この単価に関しても適正な単価で積算をしているのですけれども、やはり規模の面、あとは求められる性能が上がっているという面で、このように非常に大きな工事金額になっているというふうに認識しております。それに基づいて技術者の配置を社内で検討するというふうに聞いております。その中で辞退が出てしまうということはあり得るところだと考えておりますので、今回に限らず、入札に関しては適正に行われていると認識しております。","voiceIndex":91,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"もう１つだけお聞きしたいのですが、この中には、工事請負契約の中で、電気設備工事、空調設備工事、これは全部一緒で総額が約７６億円ということなのですか。以前は、電気設備工事は電気設備工事できちんと分かれて入札をされていたと思うのです。今回は、なぜこれ一体でやったというのは、私もしばらくぶりに見るのですが、その辺についてご見解をお聞かせください。","respondent":"荒木学校施設担当課長","answer":"そうした際に、先ほども経理課長から説明があったのですけれども、電気と機械の業者にとっては、その間、手持無沙汰になるといいますか、技術者として配置しておくことがやはり惜しい期間がありますので、そういう費用面なども鑑みて、業者のご要望なども鑑みて。","voiceIndex":94,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"ということは、これ、後からまた工事請負契約が、電気とか空調についても後からこれが出てくるというふうに考えていいのでしょうか。","respondent":"荒木学校施設担当課長","answer":"委員お見込みのとおりです。令和８年度の第２回定例会での契約を目指して、今後、発注してまいります。","voiceIndex":96,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうことは、私は、教育に関して予算を使うことは、それはやって構わないと思うのですけれども、果たしてそれだけ高額な、１校当たり、規模が大きいといえども、１００億円を超えるのではないかと予想されるような、想定されるような金額が、こうやって平然と出てくるということは、私は、少しいかがかなと思うので、本来なら、もっと多くの方が入札に参加できるようにして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"正確な数値でなくていいのですけれども、全体でどのぐらいを見通していたらいいのですか。多分１００億円を超えると思ってはいるのですけれども、今、１つの学校規模が、ほかよりも規模が大きいと言ったとはいえ、どのぐらい見積もっておけばいいのでしょうかということと、それから、多分、現校舎を使いながら工事をしていくのかなと思うのです。校舎の位置が変わるのですよね。変わってくる。","respondent":"荒木学校施設担当課長","answer":"２点ご質問いただきました。１点目の全体の金額ですが、今後の予算特別委員会でもご審査いただこうと考えていますが、電気と機械の設備工事で、令和８年度予算として、債務負担行為も組んでなのですけれども、約２６.８億円で予算を組ませていただいております。","voiceIndex":99,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"大体１００億円になると言っても、１００億円ではないですよね。これ、解体が入っていないのですか、解体も入れての１００億円なのか、総整備という形で、さっきの金額ぐらいに考えておけばいいのかということと、それから、今、場所がないということもあって、現校舎を使いながら、反対側というか、校庭側のほうに新しい校舎を建てるという方式なのですよね。","respondent":"荒木学校施設担当課長","answer":"１点目の費用の面です。説明が不足しておりました。今回、本日ご説明した資料の中の建設工事の中に解体も含まれております。ですので、今回は、既存校舎と仮設校舎を同じ敷地内に併用しながら、うまくやりくりをしていくということで、今回の工事計画を立ててまいりました。","voiceIndex":101,"id":"exchange-022"}]},{"id":"topic-06","title":"第４５号議案、源氏前小学校改築工事請負契約の変更","agenda":"第４５号議案、源氏前小学校改築工事請負契約の変更","exchanges":[{"speaker":"西本委員","kind":"質問","question":"もう少し詳しく知りたいです。変更理由です。それで、これ、契約変更を２回やっているのです。これはもう今のご時世だから仕方ないということなのか、これからもこういう形で１億円以上の差額が出てくる形で変更をしないといけない。今、どういう感じなのでしょうか。その辺の見通しというか、分かりますでしょうか。","respondent":"荒木学校施設担当課長","answer":"今回、２回目の変更でございまして、１回目の変更はインフレスライド対応による変更対応です。今回、２回目の変更のより詳細な説明ですが、２点あります。建設発生土の処分方法ですが、これにつきましては、今回の改築工事で地盤改良を実施しております。","voiceIndex":117,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"インフレスライド条項は、これからも続くのだろうなという思いはあるのですけれども、まず、これからの動向、これからも続くのかなという思いがあるので、そのシミュレーションまではいかなくても、だいたいこのぐらい上がってくるのではないかというところを立てられているのか、そこを教えてほしいのと、六価クロムということは、地盤改良ということは。","respondent":"荒木学校施設担当課長","answer":"今後のインフレスライドの見込みですけれども、やはりまだ資材価格の高騰、労務費のほうでは特に今後は顕著になっていくだろうというふうに考えてありますので、今後もインフレスライド対応が発生していくというふうに見込んです。","voiceIndex":119,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"話がずれてしまったら、ごめんなさい。軟弱だということは、柔らかいわけですよね。あそこの地域は全体的にそうなのですか。それとも、この源氏前小学校のところが、特段、特筆してそういう面があるという形での、設計段階にいろいろ調べられていると思うのですけれども、それはどういう経緯があったのでしょうか。","respondent":"荒木学校施設担当課長","answer":"設計段階では、先ほど、土木のほうのお話でもあったのですけれども、ボーリング調査を敷地内で何か所も実施して、地盤面の強さを測っております。","voiceIndex":121,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"今、地盤が思ったより軟らかかった、それから、六価クロムのお話がありました。これ、受注業者、建設業者というのは、本来、事前にやはり地質調査を、そのぐらいするべきではないでしょうか。自分が請け負った事業に対して、こういうことを怠っているということは、逆に、何か少し誠実さに欠けているのではないかな。後からこうなりました。いや、六価クロムが多かった。","respondent":"荒木学校施設担当課長","answer":"その点につきましては、私の説明が少し不足していた点があったのですけれども、今回は、区として、設計段階で地盤改良するために硬化剤として、六価クロムの溶出量低減型を指定して発注をしております。","voiceIndex":124,"id":"exchange-026"}]},{"id":"topic-07","title":"第１０号議案、品川区公告式条例の一部を改正する条例","agenda":"第１０号議案、品川区公告式条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"それをウェブにも掲載するということなのですか。それに対して、何か意見とか、そういうことも受け取れるような状況になるのでしょうか。意見交換まで求めないのか。掲示したほうがいい文書だったと思うのですけれども、もちろん受け付けないということではないと思うのですが、意外と仕組みがよく分かっていないのではないかと思うのですが、その辺の周知はどう考えられていますか。","respondent":"藤村総務課長","answer":"今までは、議会でご議決いただいた後に掲示板に張りつけるというような対応をとっておりましたので、それをウェブ上で、今後、掲載していくという形になると思います。","voiceIndex":139,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"ぜひいい機会ということもあるので、こういう仕組みになっていますよということは知ってほしいなと。できれば、区報、広報紙があると思うので、そこで少し宣伝していただくと、ありがたいかなと、結構、皆さん、広報紙は見ているものですから、なので、そこで何かの機会に掲載して、見てくださいみたいな、ウェブで配置しますみたいなところをぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"この公示送達で掲示板とインターネットということですけれども、行政手続法の改正でということなので、前にも税務のところであって、公示送達がインターネットでできるのですけれども、そのためにこういうふうに手続を進めていくために公示送達が必要だということだったのですけれども、今回の総務での行政手続法改正というところですけれども、その中身、どういうことでの公示送達。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-029"}]},{"id":"topic-08","title":"第１１号議案、品川区行政手続条例の一部を改正する条例","agenda":"第１１号議案、品川区行政手続条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この聴聞の手続というのが、今、若干説明があったと思うのですけれども、具体的にどういうふうなやり取りになって、それで誰が得というか、意義というか、そういうものがどういうやり取りで、聴聞の手続のことを少し教えていただきたい、どういうものなのかということ。どう見ていくのかということを伺いたいと思います。","respondent":"藤村総務課長","answer":"パソコンの設置というところですけれども、今回の法改正が、ホームページ上に公示送達の情報を載せることと、もしくは、公示送達を載せるというのがパソコン上のウェブ上に載せることが必須なのですけれども、それとプラスして掲示板の掲示、もしくは。","voiceIndex":160,"id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"このインターネットによる公表が、この聴聞自体がそもそもあまりないということですし、しかも、区から相手方に、「弁明できます」、「抗弁できますよ」というふうに「抗弁させてほしい」と区民が言っているものに対して出すわけですから、それが届かないということの現実性というものもあるのだろうかという感じなのですけれども、聴聞について、言わせてほしいと区民が言っているので。","respondent":"藤村総務課長","answer":"プラスの面もあれば、マイナスの面もあるというようなお話がありましたけれども、公示送達ということで、２週間、掲示板に貼り付けて、誰も見ないで、それが確定してしまうと、その方が弁明する機会を失ってしまいますので、今までは。","voiceIndex":162,"id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"とはいえ、いいことでも、名前が全世界に発信されるというところでは、プライバシー保護に大きく関わることだと思いますので、示されるわけですから、見ようと思えば、全世界で見られるということで、いいことでも、やはり名前を出してほしくない。プライバシーの保護はあると思いますので、そこは様々、自治体でも工夫ができると思いますので、そうした配慮をしていただきたいと感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-032"},{"speaker":"松本委員","kind":"質問","question":"先ほども、最近、ほぼ事例はないという話がありましたけれども、もう一度、過去、まず前提として、聴聞するということは、郵送で通知が行く、それでも届かないから公示送達という手続がとられると思うのですけれども、公示送達は、過去、品川区でとられたことはあるのかということはどうなのでしょうか。","respondent":"藤村総務課長","answer":"近年の実績と申し上げているのですけれども、確認できるところであれば、聴聞に係る手続で公示送達したところは、現在、発見はできなかったということです。","voiceIndex":165,"id":"exchange-033"},{"speaker":"松本委員","kind":"質問","question":"ということなので、もうこれは質問というよりも、むしろ説明のところで、ほぼない事例ということと、あと、ほとんどの聴聞は、取り消される人たちにとっては利益があるので、むしろきちんと本当は伝えないといけないことで、そのことを掲示板に張って、届いていないということであれば、むしろインターネット上で公開するというのは、きちんと知ってくださいねというレベルの話だと思うのです。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"聴聞については分かりました。あれとはまた違う、ごめんなさい。だけど、できないから掲示板で、２週間の掲示をして、申立てがあればという形で言っているのだけど、それがなかった場合には処分するよというような、そういう書き方をされていたと思うのですけれども、それのことを言っているのですか。それも含まれるということでいいのですか。","respondent":"藤村総務課長","answer":"公示送達というのが、例えば、今申し上げているような聴聞に関する公示送達ですと、例えば、税の支払いの督促であったりとか、あとは、契約書外では裁判とか、そういったところも全て宛所に尋ね当たらずに、何らかの方法を尽くして住所が分からないというところがあれば。","voiceIndex":168,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"そうすると、それも含めて、ウェブとかを使って、それをお知らせするという手法を使われるという認識でよろしいですか。","respondent":"藤村総務課長","answer":"そうですね、公示送達に係るというところであれば、ウェブ上に掲載できる形になりますので、ただ、例えば、今回この行政手続法の改正というところでご案内しているところですけれども、前は、令和７年の第２回定例会で、地方税法の件に関しての公示送達は。","voiceIndex":170,"id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"意見","question":"今回、この議案については、公示送達のみが諮られているということなので、反対をします。やはり先ほども言いましたけれども、公示送達を受ける側の防御権を保障するべきだと思いますし、公示送達は、行政としても最後の手段だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":177,"id":"exchange-037"}]},{"id":"topic-09","title":"第１２号議案、品川区長等の損害賠償責任の一部免責に関する条例の一部を改正する条例","agenda":"第１２号議案、品川区長等の損害賠償責任の一部免責に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"意見","question":"今回は、大本の法が変わったのでということ、それは分かりました。大本のところなのですけれども、品川区長等の損害賠償責任の一部免責ということなのですけれども、すみません、これについて、どういう一部免責になっていたのか。変わっていないということなので別にいいのですけれども、そもそもこれがどういうものなのかだけ、簡単に説明いただけると助かります。","respondent":"藤村総務課長","answer":"こちらについても当区において例があるわけではないのですけれども、住民訴訟が提起された際に、例えば、長が被告となってしまったというときに、最終的に区が敗訴して、何かしら損害賠償の金額が裁判所に認められたという中で。そうですね。長の場合は基準給与年額の６倍という形なので、すみません。基準給与年額が定まっていて、長の場合はそれの６倍。例えば、副区長等は４倍、職員は１倍という形で、その階層に応じて負担額が異なっているという形です。","voiceIndex":186,"id":"exchange-038"}]},{"id":"topic-10","title":"第１３号議案、品川区職員等のハラスメントの防止等に関する条例","agenda":"第１３号議案、品川区職員等のハラスメントの防止等に関する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これ、事前に説明を受けてはいるのですけれども、まず、制定理由の中で、指摘はしましたが、どうも私は納得いかない文言がありまして、「昨今、他自治体で職員のみならず首長等によるハラスメント事案の発生」とあるのですけれども、これ、他自治体ですか。そういうことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"これ、職員アンケートをとって、いろいろ議論がこの間ありましたけれども、私は情報公開制度を使って、開示請求を行いました。そうしたら、非公開という形になったので、今それに対する手続をとっている段階なのですけれども、アンケートの結果をどう捉えてこれになったのでしょうか。全く関係なくこれは出てきているのか。この出所です。根拠というか。それを教えていただけますか。","respondent":"川村コンプライアンス推進担当課長","answer":"制定理由についてのご質問にお答えいたします。品川区におきまして、この条例制定は、具体の事案をきっかけにしたものではございません。職員アンケ－トにつきましては、具体的な事案を調査したものではありませんし、ハラスメントの事実が認定されたわけではございません。","voiceIndex":204,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"部長の３割以上の方々がハラスメントに遭っている、パワハラに遭っている。別にこの条例はいいことだと思っています。なので、そこは、アンケートの結果をどう捉えたのですかということ。そして、今、職場の環境、区の職場の環境は、どう考えてこれを決めたのかということは、はっきり説明に入れるべきではないのでしょうか。私は、そこが納得いかないのですけれども、いかがですか。","respondent":"川村コンプライアンス推進担当課長","answer":"職員アンケートにつきましては、職員の中でハラスメントに遭ったり、見聞きしたことがあるという職員がいるという実態は確かに明らかになっておりますが、以前もご議論あったような個別の事案について実施したものではございません。","voiceIndex":206,"id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"ここのところは認識の違いが出ているので押し相撲となりますから、あまり長く何回も繰り返し言う必要はないと思っているのですが、別紙２のところに表が入っています。この中で、今までと違うところがどうなのか、少しそこを説明してもらえますでしょうか。","respondent":"川村コンプライアンス推進担当課長","answer":"別紙２のハラスメント苦情相談に係る対応フローについてご説明いたします。","voiceIndex":208,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"そこの中で、副区長の場合はどこになりますかということ、これ、区長等となっているのですけれども、区長、副区長、教育長は、どういうフローになる、そこを少し説明をお願いします。それから、事実の公表ですが、この事実の公表というのは、どういう公表になりますか。マスコミ報道ということを言っているのか、どういう報道を想定しているのでしょうか。","respondent":"川村コンプライアンス推進担当課長","answer":"公表の在り方につきましては、条例には詳細を定めておりませんが、今後、検討してまいるところですけれども、少なくともホームページの目立たないところに掲載して終わりというような形は考えておりませんので、真摯に行動してまいりたいと考えております。","voiceIndex":210,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"相談した方の保護という意味では、どういう保護がされるのか。それをすることによって、安心して区の職員がお仕事できるかと思いますので、ここはしっかりと公表するという形をとっていただきたいとお願いしておきたいと思います。最後に、先ほど言った相談者に対する保護の観点から、どういう保護をしていただくのでしょうか。怖いと思うのです。それについての区の考え方を、教えてください。","respondent":"川村コンプライアンス推進担当課長","answer":"今後、事実の公表というところになった場合は、さらに不安が増すかとは思われますけれども、そこにつきましては、相談者が特定されないような配慮はもちろんいたしますし、調査開始時には。","voiceIndex":212,"id":"exchange-044"},{"speaker":"須貝委員","kind":"意見","question":"今、ハラスメント苦情相談に係る対応フローとあるのですが、これだけたくさん条例が出ているので、見落としていたら申し訳ないのですが、そういうハラスメント等々あった場合に、職員は懲戒処分を実施すると明確に表記されているのですけれども、これ、区長、副区長、教育長に当たっては、区長にもしそういう問題があったら、副区長が調査委員会を立ち上げてやっていくということですが。","respondent":"川村コンプライアンス推進担当課長","answer":"ただ、そこで上層部による恣意的なものによって公表されないのではないかというところにつきましては、今回、条例を定めた目的が、こういった対応を内外にしっかり発信していくという目的、また、職場環境の改善をしっかりしていくというところがありますので。","voiceIndex":214,"id":"exchange-045"},{"speaker":"須貝委員","kind":"意見","question":"しっかり、こういうふうに条例をつくって、区の姿勢は見せる、区民に見せるというのはいいのです、それは。いや、こういう取決めはあるのですよ、条例は。でも、そこで止まっているような気がするのですが、そこを明確に公表というのは、記者会見でもやるのだとか何かというものがない限り、私は有名無実の条例ではないかというふうに思うのですが、もう一度ご見解をお聞かせください。","respondent":"川村コンプライアンス推進担当課長","answer":"確かに、今、条例に公表については、そこまで詳細には決めておりませんけれども、条例の実効性を持たせるためには、重要な措置だと考えておりますので、今後どういった形で公表していくかというところにつきましては、しっかり検討してまいりますし。","voiceIndex":216,"id":"exchange-046"},{"speaker":"須貝委員","kind":"意見","question":"最後にもう１点。民間では、第三者機関がしっかり調べて調査権も持って、それなりの処分を公表してやっている。それが社長だろうが、副社長だろうが、やはり明確にそういう処分、処分の対象として公表してしっかり対応している。ところが、行政の場合には、こういうふうに途中でとまってしまっているということは、私は、何か早く検討して修正するべきだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":218,"id":"exchange-047"},{"speaker":"松本委員","kind":"質問","question":"ご説明ありがとうございました。今の公表の規定なのですけれども、他自治体の条例を調べると、公表できる条例にしているところが多いのではないかと思います。当区の場合は、検討に当たって、「できる」ではなくて「公表する」と、絶対にするのだというところを書いておりますので、ここの趣旨を伺えればと思います。","respondent":"川村コンプライアンス推進担当課長","answer":"ここにつきましては、今回、条例化するに当たって、よくよく議論をいたしまして、やはり区の姿勢として、しっかり公表するという姿勢を示すために、こういった文言にしています。","voiceIndex":219,"id":"exchange-048"},{"speaker":"松本委員","kind":"質問","question":"一方で、今回のハラスメント問題調査委員会は、条文を読む限りは、諮問があった場合に設置されるように読めるので、例えば、年に１回開催されて、報告を受けて、そこで報酬が発生するみたいな感じではなく、何かが起きたときに設置されて報酬が発生するというふうな仕組みになっているのか、この２点を伺えればと思います。","respondent":"川村コンプライアンス推進担当課長","answer":"常設かどうかという部分につきましては、相談があったときに迅速に対応できるように、あらかじめ委員を選定した上で、常設というような形を今は考えているところです。","voiceIndex":221,"id":"exchange-049"},{"speaker":"松本委員","kind":"質問","question":"そうすると、常設ではあるけれども、実際に多分、委員の方たちは出てこないと、日額報酬は発生しないと思うのですけれども、それは実際に定例会があるとかというものではなくて、あくまで招集単位、例えば、調査委員会の事務局は常設としてあって、それで何かあったときに招集がかかって来るというふうな仕組みになるというふうな理解でよろしいでしょうか。","respondent":"川村コンプライアンス推進担当課長","answer":"その辺、おっしゃるとおり、事案があったときに集っていただいて、調査・審議していただくような形の仕組みで考えております。","voiceIndex":223,"id":"exchange-050"},{"speaker":"松本委員","kind":"質問・要望","question":"それに対して実際に調査をするのだったら、例えば、２週間ぐらいずっと調査して、その人にだけ報酬を払うというのは、これもやはり適切な報酬の払い方としては大切になってくると思うのですけれども、この辺りの報酬の考え方は、最終的には、それはこの条例ではなくて、より内部的に決めていくと思うのですけれども、現状、どのように考えていらっしゃるか伺いたいと思います。","respondent":"川村コンプライアンス推進担当課長","answer":"報酬の考え方についてご説明いたします。","voiceIndex":225,"id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、そういうことを周知していく、広げていくためには、今まで以上に何か工夫されることがあるのかどうか、少し伺いたいと思います。","respondent":"川村コンプライアンス推進担当課長","answer":"職員への周知についてご説明いたします。","voiceIndex":227,"id":"exchange-052"},{"speaker":"山本委員","kind":"質問","question":"私からも質問いたします。今回、このようなハラスメント防止条例が設置されるということは、よいことだと考えています。今回、この条例によって新しく設置されるハラスメント問題調査委員会というのは、区長等からの独立性を担保するということはすごく大事なことだと思うのですけれども、委員会の委員長や委員をどのように選出していくか、その考え方があればお聞かせください。","respondent":"川村コンプライアンス推進担当課長","answer":"こちら、区長等からの中立性ですとか、第三者性を担保することが非常に重要と認識しておりますので、例えばなのですけれども、弁護士につきましては、弁護士会を通じた推薦を受けるですとか。","voiceIndex":229,"id":"exchange-053"},{"speaker":"山本委員","kind":"質問・要望","question":"これは私の意見です。最後に、お考えの確認になるのですけれども、この条例をつくった後、こういった相談がもし寄せられた際には、真摯に職員の方からのご意見を酌んで、しっかりと調査するということと、そして、ハラスメント防止に取り組んでいくというお考えでよいかということを確認させてください。","respondent":"川村コンプライアンス推進担当課長","answer":"こちら、条例をつくって終わりではなくて、しっかり職員からの相談に対応できるような体制をつくりたいと考えて、今回、条例を制定しておりますので、職員への周知ですとか、啓発活動も含めまして、職員に対して実効性のある取組を進めてまいりますし。","voiceIndex":231,"id":"exchange-054"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひお願いいたします。ほかの委員の方からもご要望がありましたけれども、これに相談を寄せられる方の立場を守るということもとても大事なことだと思いますので、私からも要望して質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-055"},{"speaker":"西本委員","kind":"確認","question":"ごめんなさい、１点だけ。確認だけです。苦情処理委員会というのは、これは、職員５名以内をもってということなのですが、ここの中には専門家の方々も入れないということですか。これはあくまでも職員５名ということは、部長とか、副区長とか、区長とかが入るのですか。これ、少しイメージが、誰がやるのですか。","respondent":"川村コンプライアンス推進担当課長","answer":"苦情処理委員会についてご説明いたします。こちらは確かに職員５名以内で設置される委員会でございまして、委員長は、区長室長というふうに定められております。","voiceIndex":234,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"これ、分かったら、職員５名と書いてあるだけで、誰々ということは書いていないのですけれども、今後入ってくるのですか。この条例の中に入ってきます５名という、「５名以内をもって組織する」と書いてあるのですけれども、その５名は誰ぞやというのは、ここに入る形になるのでしょうか。","respondent":"川村コンプライアンス推進担当課長","answer":"今、確定的に申し上げられることとしては、委員長が区長室長というところになります。","voiceIndex":236,"id":"exchange-057"},{"speaker":"松本委員","kind":"確認","question":"賛成です。大事になってくるのは、公表して、情報を公開していただいた上で、あとは我々議会側がきちんと確認していく、糾弾するべきところは糾弾していく。今後、規則もこれからつくられると思うのですけれども、規則をきちんと確認していくとかということが大事になってくるのかなと思います。以上が意見で、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":245,"id":"exchange-058"}]},{"id":"topic-11","title":"第１４号議案、品川区職員定数条例の一部を改正する条例","agenda":"第１４号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"小・中学校での固有教員が４名増となっていることも、とてもうれしいことだなと思うとともに、今後、品川区の教育をより深く理解して、品川区特有の固有教員の先生が、さらに増えていってほしいなという思いでありますけれども、用務の定数が７人減となっているのですが、これは、なぜ減になっているのかということと、用務の方が減となった理由、経緯などがあれば教えてください。","respondent":"宮尾人事課長","answer":"今回たまたま退職者が重なったということで、その分も従前の考え方にのっとりまして、業務委託にて新たに対応していくというような考え方です。","voiceIndex":254,"id":"exchange-059"},{"speaker":"澤田委員","kind":"確認","question":"改めて確認なのですけれども、では、その用務の方が全体として数が減ったわけではなくて、職員の方が減って、その分補ってはいるから、学校の中の業務自体は別に問題ないというか、誰かに負担が寄ったりとかということも、困ったりということもないという意味というか、形でいいのでしょうか。","respondent":"宮尾人事課長","answer":"確かに職員数、職員が退職をしたところを補充せず、業務委託を入れている、新たに入れるということになりますので、用務職全体としての数は減っていくのですが、ただ、減った分は業務委託にてそれはしっかりと業務の質は担保していますので。","voiceIndex":256,"id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、減らすのではなく、むしろ増やしてほしいし、委託はやめて直営にというのが共産党はずっと求めてきているところなのですけれども、今、委託で補充はされているということでしたけれども、今回、７人が減りますけれども、それを委託で補充というのは、７人まるまる委託で補充されるということでいいのかということをお聞きしたいのと、あと、新たな施策が打ち出されるもとで。","respondent":"宮尾人事課長","answer":"今後の職員定数の考え方ですけれども、こちらも、今回のご提案もそうですが、業務量が一定程度増えてきて、それが年間を通してずっと業務量の増大が見込まれるところには、しっかりと増員をさせていただいているところです。","voiceIndex":259,"id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"少し減っていますよということなのか、そこが分かれば伺いたいのと、あとやはり、職員の数ですけれども、その方々が、要は、区民へのサービス提供という形にもなっていくと思うので、職員の方が気持ちよく働けるということが区民へのサービスにもつながるということになると思うので、そこはぜひ各所管から、いろいろな職員増の要請等も来ると思うのですけれども。","respondent":"宮尾人事課長","answer":"ただ、委託を導入した園なり学校については、委託をしてくれているスタッフの方が入りますので、そこがゼロになるということは基本的にはあり得ないのかなというふうに思っておりますので、基本的には、職員の数というのでしょうか、そこは現状というか、担保、学校の数。","voiceIndex":261,"id":"exchange-062"},{"speaker":"西本委員","kind":"質問","question":"分かったらでいいのですけれども、主務教諭というのは何でしょうかということと、それから、付則のところですけれども、「１２０人を限度として」ということで、「定数外とする」、これ、意味がよく分からないので、これはどういうことなのかということと、それから、４９名ということなのですけれども、これは、現状、これから増やしますよという人数なのですか。そこを教えてください。","respondent":"宮尾人事課長","answer":"定数外を１２０人を限度に年度内にという考え方ですが、一番分かりやすい例で言うと、育休です。今は少し職員の年齢構成、それから、最近で一番大きいのは、やはり男性の育休です。育休に入って抜けた職員のところを正規の職員で補充するとします。","voiceIndex":263,"id":"exchange-063"},{"speaker":"西本委員","kind":"質問","question":"少し前だと、お互いに連携という形でやっているから、長がいて、それぞれの課長、その下という形でいろいろ協力しながら、連携しながらやっていたと思うので、やる仕事は仮に一緒だとしても、そちらのほうがやりやすかったのではないか、逆に、分散化することによって人数が必要になってしまっているという現象は起きていないのか、その辺はいかがですか。","respondent":"宮尾人事課長","answer":"例えば、ある所属は何人増やしてほしいというような要求をいただくのですが、我々、中身をしっかり見させていただいて、例えばこの部分は、今まさに委員がおっしゃられたように、「そこの係だけではなくて。","voiceIndex":265,"id":"exchange-064"},{"speaker":"西本委員","kind":"質問","question":"なので、もちろん、それに加えて、再任用とか、業務委託とかということをやっているということを考えると、これは、だから、この程度で済んでいますということなのか、まだまだこれを増やしていかなければいけないということなのか、今後、どういう構造的に考えていくのでしょうか。","respondent":"宮尾人事課長","answer":"ここから先というところなのですが、やはり業務量がこの先どうなっていくかというのは非常に見通しとしては難しいところではあるのですけれども、少なくとも急激に減っていくというような見込みは少し立てにくいのではないかなというのは。","voiceIndex":267,"id":"exchange-065"},{"speaker":"須貝委員","kind":"質問","question":"このたび、職員の人数が業務量に応じて増えていくのは致し方ないと思うのですが、今、民間ではＡＩを駆使して、職員の削減を努めているという動きがやはりあると思います。それは、そういうことに対して、今回、増員するということもあるのでしょうか。こういう方たち、業務遂行に対して不十分な方たち、区の現在の職員の中で、どれほどの人数がいらっしゃるのか、それを分かる範囲で教えてください。","respondent":"宮尾人事課長","answer":"いずれにせよ、休んでいる職員、あるいは、なかなか組織の力になりにくいような職員が、指導育成はもちろんですけれども、そういった職員が１か所に偏ったりしないような、そういったものも人事異動などでも対応しています。","voiceIndex":269,"id":"exchange-066"},{"speaker":"須貝委員","kind":"質問","question":"それぞれ皆さんには個性もあるし、考え方、判断力、様々違うと思うので、本当にご苦労されていると思いますが、１つだけ追加でお聞きしたいのは、約３０名という話ですが、これは、学校の教員、これは入らないということですよね。要は、学校の先生はあくまで東京都の管轄というか、管理なので、そこはこれに入っていないということでよろしいでしょうか。","respondent":"宮尾人事課長","answer":"先ほど私が申し上げた約３０名という数字の中には、あくまでも任命権者が区長ということなので、学校の先生、東京都の関係になってまいりますので、含まれていないというところです。","voiceIndex":271,"id":"exchange-067"},{"speaker":"須貝委員","kind":"質問","question":"私、いつも思うのだけれども、品川区の学校で、一応、品川区が管理していたら、やはり東京都の職員であろうと、やはり数字として、参考として載せるべきだと思うのです。やはりそういう学校の先生も、品川区の子どもたちのために働いていらっしゃる、指導しているのですから、そういう方たちの数字も載せていただけるとありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-068"},{"speaker":"塚本副委員長","kind":"質問","question":"そこはどのような状況なのでしょうか。","respondent":"宮尾人事課長","answer":"職員採用の部分ですけれども、委員のお見込みのとおり、基本的には２３区で人事委員会を持っておりますので、そこで共通して動いていくような形になります。","voiceIndex":274,"id":"exchange-069"},{"speaker":"塚本副委員長","kind":"質問","question":"今のお話で、ああ、そうなのですかと、少し意外な感じもしているのですけれども、人手不足の中で、必要な人数が集まらないというのは、いろいろな業界で言われている中で、公務員は、そういう意味では、必要な求人に対して十分な応募があるというような、応募と言っても、試験を通らないといけないから、希望すれば誰でも採用できるというわけではないという難しさもあると思うのですけれども。","respondent":"宮尾人事課長","answer":"倍率もやはり、これも職種によるのですが、減っていたりとかということはあるので、その辺は決して楽観はできないなということで、我々区のほうも、いろいろな対策をとって、少しでも品川区に。","voiceIndex":276,"id":"exchange-070"},{"speaker":"山本委員","kind":"質問・要望","question":"私からも質問します。先ほどのご説明で、主に増員は新規事業の追加によって、それぞれ増員になっているというご説明をいただいていたと思います。結果、これで令和８年度の新規事業も踏まえて、各部署で、これで十分というか、回るというご理解で進めていらっしゃるということでいいかということを確認させていただきたいというところです。","respondent":"宮尾人事課長","answer":"今後も、必要なところにはつける、それから、役目が終わったところからは引き揚げる、減ずるというようなことを両方しっかりと対応していきたいと考えています。","voiceIndex":278,"id":"exchange-071"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。採用のところです。一部集まりにくい業種があるということでおっしゃっていて、保育士などとおっしゃっていたのですけれども、その辺り、業種についてどういうものがあるのかを確認させていただきたいのと、そこに対しての打ち手はどのように考えていらっしゃるかということを確認させてください。","respondent":"宮尾人事課長","answer":"採用の部分ですが、２３区全体のテーマなのですが、やはり専門職系、例えば建築職、電気職、機械職、こういったところは、品川区に限ったあれではなく、２３区全体で、そもそもエントリーをしてくれる数がなかなか厳しい状況であるということで、先ほどと一部重複しますが。","voiceIndex":280,"id":"exchange-072"},{"speaker":"山本委員","kind":"質問・要望","question":"分かりました。そのような工夫を進めて、採用が進むことを願っております。業務量に応じた適正な定数配置を実現していただいて、一部の方々に負担がかからないように進めていただきたいということと、新任の方が増えると、またそれをお教えしたりする負担もかかってくるというところで、そういったところも考慮して組織運営を円滑に回るように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":282,"id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"共産党は、用務職の役割としてのことを、先ほど、用務職のこともお聞きしたのですけれども、やはり教員とは別の目線で子どもの成長を支えることができるということがあると思いますし、そうした技術と経験を検証するためにも、退職不補充ではなくて、直営で採用すべきと求め続けております。その用務職を減らしていくという議案には反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":293,"id":"exchange-074"}]},{"id":"topic-12","title":"第１５号議案、公益的法人等への職員の派遣等に関する条例の一部を改正する条例","agenda":"第１５号議案、公益的法人等への職員の派遣等に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"地方税共同機構へ派遣するのは、なぜなのでしょうか。","respondent":"宮尾人事課長","answer":"この組織には、当然、２３区が順番に職員を派遣しておりまして、この４月から品川区の番が来たということで、条例の改正をご提案させていただいたです。","voiceIndex":302,"id":"exchange-075"}]},{"id":"topic-13","title":"第１６号議案、非常勤職員の報酬および費用弁償に関する条例の一部を改正する条例","agenda":"第１６号議案、非常勤職員の報酬および費用弁償に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"報酬額が高くなるのは別にいいのですけれども、これは人事委員会勧告を踏まえということは、何かこの計算とかがあるのですか。このベースを考えるに当たって、どういうところからこれを持ってくるというものはあるのでしょうか。","respondent":"宮尾人事課長","answer":"ばらばらにしてしまいますと、低いところになかなか人が集まりにくくなってしまうというようなことも趣旨の１つとしてはあります。ですので、今回は、これ、昨年秋の東京都の人事委員会勧告の給与改定率、これをベースに改正の額を算出しているです。","voiceIndex":318,"id":"exchange-076"},{"speaker":"須貝委員","kind":"意見","question":"一言だけ。これが一般的な通例のお医者さんの日額報酬等だと思うのですが、これが一般の通例の金額なのでしょうけれども、一般の人が見たら、随分高い金額だなと思ったので、意見だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":321,"id":"exchange-077"}]},{"id":"topic-14","title":"第１７号議案、職員の給与に関する条例の一部を改正する条例","agenda":"第１７号議案、職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、こうした管理職をさらに増やすというところで、人材の確保をしていくためにも、この賃金アップというのは大事だと思うのですけれども、区としては、こうした管理職をさらに増やしていくために、等級を上げることを積極的にやっていこうとか、頑張っている人は昇給させていくということをもっと積極的にやっていくべきだということが、労働組合からも求められていると思うのですけれども。","respondent":"宮尾人事課長","answer":"頑張っている職員へ報いるというところですけれども、現在も評定の中でしっかりとそういったところはやらせていただいて、給料も、どんどん、きちんと連動していくような仕組みもありますし、これからもしっかりとそういったところも対応していければと考えています。","voiceIndex":335,"id":"exchange-078"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、大変さがにじみ出ると、そちらまで昇給したくないというような職員も出てきかねないですから、そこら辺をさらに充実させるということを私も求めたいと思います。それで、終了される方に対しても、要は、給料が下がってしまうということなのか。そして、その差額分は、もう出ないのか、何か対策は打たれるのかをお伺いしたいと思います。","respondent":"宮尾人事課長","answer":"こういった職員も、この３月いっぱいで、この差額支給は終わるのですが、委員のご質問にもありました、では、その代替措置ということで、今年度、特例の昇任選考を実施しております。","voiceIndex":337,"id":"exchange-079"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。１３人ということで、この方々は、全員、特例昇任選考は受けられているということでいいのか、自分の申請によってということだったので、それはどうなのか伺いたいと思います。","respondent":"宮尾人事課長","answer":"当然、この１３人の方たちは全て対象になります。委員お話しのとおり、申込みをいただくということが前提になっておりますので、申込みをいただいていない方は、当然ですが、選考の対象には乗ってこないという、そういう仕組みになってあります。","voiceIndex":339,"id":"exchange-080"},{"speaker":"西本委員","kind":"確認","question":"だから、優秀な方はやはり採用してほしいなという思いはあるのですけれども、ここのところは、民間だと、もうとにかく初任給とかも非常に高くなっていて、なかなか公務員という形で考えていただけるのは競争に負けてしまう現状ではないのかなと思うのですが、その現状としてどうなのか、そこを何とかカバーすることが、今回、給料改定はあるものの、民間と比較して不十分なところがあるのではないかなと。","respondent":"宮尾人事課長","answer":"それが４月からは９段階に、１号給から９号給に変わります。ですので、ぐっと給料表がコンパクトになって、１つ１つの段差が大きくなるということになります。９段階しかありませんので、普通の方ですと、昇給はしない仕組みになります。","voiceIndex":344,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"等級というより、号給の間隔を変えましたよということなのですけれども、分かりますが、逆に、チャンスもあり、チャンスでもなくという部分もありますよね。逆に、部下の評価を制度でやっているところがあるではないですか、民間で。部下が評価をして、評価が高いというのであれば、成績優秀とかは別にしてという評価対象にしてもいいのではないかなと思うのですが、いかがですか。","respondent":"宮尾人事課長","answer":"特別区全体で取り組むこと、それから、品川区が単体でできることは、制約、制限がありますけれども、評価について言えば、まず、しっかりと、例えば、管理職になった方には、その評価をつけるための訓練、研修というようなものもやらせていただいているところですので。","voiceIndex":346,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"まとめます。上のいい子ちゃん、言い方は悪いけれども、言いなりで、何でも「はい」と言うような状況では駄目なわけであって、部下をいかに育てるか、それから、部下の人たちが、いかに働きやすい環境になっているか、自分たちの能力を存分に発揮できる職場にしているのかどうかということは、すごく大切な関係だと思いますので、ぜひそういう形で評価をしていただきたいとお願いして、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":348,"id":"exchange-083"},{"speaker":"須貝委員","kind":"質問・要望","question":"社会では、Ｋ字型経済、またはＫ字型給料体系といって、給与が増える一方の人と、逆に下がる一方の人と２つに分かれています。それをＫ字型というのでしょうが、ぜひそういう一般の区民の困っている方々のことも考えて、こういう職員給与改定をしていただきたいと思います。今回のこの管理職の給与改定については、私は賛成できません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":349,"id":"exchange-084"},{"speaker":"松本委員","kind":"質問","question":"そうすると、この４級と５級のところの重複を解消していくということも１つの課題だと思います。これは特別区の人事委員会勧告を受けてなので、品川区でできることは限られているかと思うのですが、我々で実数として把握しておきたいのが、今、４級の方で、５級の方よりも給料が高い方がどのくらいいるのかということは、データとしてありますでしょうか。お願いします。","respondent":"宮尾人事課長","answer":"今回の改正前ですと、４級と５級の重なりが、約８割あったものが、今回の改正で、それが約３割にまで減少するという改正内容になってあります。こういったところを踏まえますと、今回、少しでもこの改正によって処遇面で管理職の魅力の向上につながってくれればです。","voiceIndex":350,"id":"exchange-085"},{"speaker":"松本委員","kind":"質問","question":"給料表の上では、重なりが３割になるということだと思うのですけれども、実際に、品川区は、今、データはないと思うのですけれども、人事委員会が、例えば、実際に特別区で重なっている人数がどのくらいとかというデータは出ているのでしょうか。","respondent":"宮尾人事課長","answer":"特別区のほうからも、そのような詳細なデータは示されていないのですが、区議会のほうから、そのようなご意見をいただいたということは、機会を捉えて発信できればと考えています。","voiceIndex":352,"id":"exchange-086"}]},{"id":"topic-15","title":"令和８年２月８日執行 衆議院議員選挙の結果","agenda":"令和８年２月８日執行 衆議院議員選挙の結果","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"このたび、選管においては、本当に大変だったと思うのです。これ、経費なのですが、通常よりプレミアムがついて、多くくれるようになったのでしょうか。恐らくかなり遅くまでやって、朝も早くまでいろいろ準備したり手配したり大変だったと思うので、通常の業務とは違うと思うのですが、その辺、何か感謝の言葉も含めて、お金も、予算もそうですけれども、上から来ているのでしょうか。教えてください。","respondent":"今井選挙管理委員会事務局長","answer":"何かプレミアムのようなお話がありましたけれども、そういうことはございませんで、逆に、私ども、今、東京都が、まず２６日までに概算を一旦出した上で、東京都が国のほうに予算要求をするのが６月頃になる予定ですので、状況によっては、私どもで要求しておかないと。","voiceIndex":380,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問","question":"本当に大変な思いをされたのではないかと思います。これは取締りできないのでしょうか。やはり証紙が貼ってあるということは、選挙期間中に使ったものであるので、それは貼り替えてもらうとか、撤去してもらうという、それぞれの選挙事務所のほうに依頼してもいいのではないかなと思うのですけれども、それはできないのでしょうか。","respondent":"今井選挙管理委員会事務局長","answer":"選挙後のポスター、証紙が貼ってある、選挙運動期間中は適法だったものが、今も貼ってあるのではないかというお話ですけれども、こちらにつきましては、選挙の、今回ですと、東京都選管が、やはり選挙運動前。","voiceIndex":382,"id":"exchange-088"},{"speaker":"西本委員","kind":"意見","question":"今回、残念だったのが、アトレです。アトレで、結構重宝して行かれている方、今回、投票率が高くなったので、それもすごいなと思ったのですけれども、ぜひアトレの協力はこれからも引き続きお願いしたいなと思っています。いっぱいありますよ、証紙が貼ってあるポスター。ありますよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":384,"id":"exchange-089"},{"speaker":"澤田委員","kind":"質問","question":"１点目というか、今、アトレの話が出たのですけれども、時間の都合とかで今回は難しかったというところで、便利というお声がたくさんあったので、次回はぜひやっていただけたらいいなということは気持ちとして伝えておきたいということと、あと、お聞きしたいのは、入院中の有権者の方、不在者投票指定施設であれば、不在者投票ができると思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":387,"id":"exchange-090"},{"speaker":"澤田委員","kind":"質問・要望","question":"していますか。すみません、ポスターとか、例えば、この病院は不在者投票施設でありますよとか、何日までだったら投票用紙を取り寄せられます、投票用紙を取り寄せるには、看護師さんとか、いろいろな病院内の方に聞いてくださいといった案内みたいなものをしているのかということを教えていただきたいなと考えています。","respondent":"今井選挙管理委員会事務局長","answer":"ただ、やはり病院の中には、とても大きい病院ですと、例えば、何日ということを決めた後で入院されてきた方への対応が少し前後するところがありますので、そういうところにつきましては、私たちも期日前期間は不在者投票指定施設にできますということの説明を徹底して。","voiceIndex":388,"id":"exchange-091"},{"speaker":"澤田委員","kind":"質問","question":"ポスターとかそういうものはあるのでしょうか。説明会みたいなものはやっていらっしゃる、すごく丁寧でいいなと思うのですけれども、例えば、その後、説明後に今おっしゃったように入ってきた方とかも、それを見るだけで、「この病院、やっているんだ」と分かるような、何かがあればと思うのですが。","respondent":"今井選挙管理委員会事務局長","answer":"私どもが単独でつくっている場合には、ポスターなどを渡しているのですが、今回、単独のポスターもつくらなかったので、もしかしたら、病院の中ではポスターなどの周知はしていないかもしれないのですが、基本的には、施設の中で周知はされていると思いますので、今後。","voiceIndex":390,"id":"exchange-092"},{"speaker":"石田（ち）委員","kind":"質問","question":"投票入場券というのですか、あれが届かないという問合せが私たちもすごく寄せられたのですけれど、私たちは、先に説明をいただいていたので、１４日前になりますということで、そういうこともこちらからはお伝えしていたのですけれども、そういった異例の短い選挙での問合せの数は、これまで以上に多かったという印象はあるのでしょうかということと、あと、やはり当日、天気が悪いということもあって。","respondent":"今井選挙管理委員会事務局長","answer":"今後は、やはり代理投票が来たときにもスムーズに運営できるということが大切なのですけれども、やはりどうしてもお待たせしてしまうということもありますので、最初の声かけのときに。","voiceIndex":392,"id":"exchange-093"}]},{"id":"topic-16","title":"第４７号議案、遺贈の放棄","agenda":"第４７号議案、遺贈の放棄","exchanges":[{"speaker":"西本委員","kind":"質問","question":"品川区に遺贈するということは。それで、現在、２階に借家人が住まわれているということですから、品川区がいただきましょうと言った場合に、この借家人はどうなるのですか。それから、この遺贈という形で区への提供という、私も指摘しましたけれども、国際友好協会、これも遺贈なので、遺贈という状況ですから、そういうことの件数はどれぐらいあるのですか。現状を教えてください。","respondent":"佐藤経理課長","answer":"１点目の、こちらの資料の３番目のところ、遺言執行者宛てに通知するというところですけれども、こちらは、ご本人、遺言者の方が亡くなられて、その遺品を整理するということで。","voiceIndex":407,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"この遺贈という形では、相談だけで、今、何件抱えているか、何件いただくことになっているというのは、秀だけですか。名前を言ってはいけない。どうですか。","respondent":"佐藤経理課長","answer":"経理課で把握しているところについては、特にございません。","voiceIndex":409,"id":"exchange-095"},{"speaker":"西本委員","kind":"質問","question":"ということであるならば、今までの前例は、では、あってないようなものですか。すみません、勝手に言っているという、そういう受け止め……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":412,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"だから、そういうものを含めて、私は何件あるのですかと聞いているので、もうありませんと言うのだったら、では、ないのねという理解でいますけれども、よろしいのですか。","respondent":"佐藤経理課長","answer":"先ほど申し上げたのは、遺贈に関しては、ご本人が亡くなったときに権利が発生するという形になりますので、その間までは、経理課は財産を管理する部門ですので、そういった視点からはないということですけれども、もちろんこの間の議会でのやり取り等を把握しておりますので。","voiceIndex":413,"id":"exchange-097"}]},{"id":"topic-17","title":"令和８年請願第２号、インボイス制度の見直しの意見書提出を要望する請願","agenda":"令和８年請願第２号、インボイス制度の見直しの意見書提出を要望する請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"改めてインボイス制度についての請願が出されて、本当に出されるたびに、大変な状況ということを知らされるわけですけれども、今回は、この請願の中に、公明党の名前が出されているということで、インボイスへの立ち位置というか、考え方は変わったということなのかということをまず教えていただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":428,"id":"exchange-098"},{"speaker":"石田（ち）委員","kind":"質問","question":"公明党の立ち位置。インボイスへの態度が、ここでは、請願の中では、「制度導入に賛成してきた政党自身が見直しの必要性に言及している」というふうに書かれているので、そこはどうなのですか。国の話かもしれないのですけれども、ご見解を伺いたいということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":430,"id":"exchange-099"},{"speaker":"塚本副委員長","kind":"意見","question":"中道改革連合の中で廃止を訴えたという事実はありますけれども、我々としては、党としては別ということもあるのですけれども、そもそも中道改革連合が１月１６日に結党されて、この政策を、インボイスに対する政策を発表したのが１月２７日。その間に我々としての政策協議とかをしてきた経緯もないので、これは少し、公明党が考えを翻したというような認識は少し違うと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":431,"id":"exchange-100"},{"speaker":"石田（ち）委員","kind":"意見","question":"本当にどう理解していいのか私も分からなかったので、聞かせていただきました。公明党としては、立ち位置というか、考え方は変わっていないということでした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":432,"id":"exchange-101"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これ以上、廃業や倒産へ追い込むインボイス制度は見直すべきだと、私たちは廃止すべきだと思っていますが、この請願では見直しということなので、見直しすべきだと思っています。大変な状況が分かると、皆さん、これまで言われてきていると思いますけれども、であるならば、見直しを求めるこの請願を採択していくべきだと思いますけれども、皆さん、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":434,"id":"exchange-102"},{"speaker":"澤田委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。理由としましては、免税事業者が適格請求書発行事業者の登録が取得できないとありますけれども、登録して課税事業者になれば、取得できますので、必要ないと考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":436,"id":"exchange-103"},{"speaker":"山本委員","kind":"質問・要望","question":"以下、会派としての見解と理由を述べます。これは基礎自治体の区の議会が意見書をもって見直しを求めるものとは異なって、税制を所管する国政レベルで議論を深めて決定すべき問題であると認識しております。一方で、制度によって実際に影響を受ける方々が存在することは重く受け止めるべきであって、その声が政府決定に適切に反映されるよう求めていく必要があると考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":437,"id":"exchange-104"},{"speaker":"塚本副委員長","kind":"意見","question":"インボイス制度というのは、やはり益税の問題というのが、この間ずっとある中での税の不公平性を正していくと、不公平感をなくしていくという意味では、大事な課題であるし、また、透明性、取引のトレーサビリティということで、そういう透明性を明らかにする、守っていくためにも必要というところでのインボイス制度の１つの重要性があるので、そういったものを損なわずに、いかに小規模事業者等に対して。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":438,"id":"exchange-105"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"このインボイス制度についての意見書を提出してほしいという請願は、何度か出されてきていますけれども、何も議論や討議もないままということが、本当に恥ずべき状況だなというふうに私は感じます。それで、この請願者が出された添付資料、これにも消費税減税やインボイス廃止などを求める意見書が可決された自治体ということで、１２月だけで出していますけれども、２５か所もあるということでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":439,"id":"exchange-106"},{"speaker":"須貝委員","kind":"質問・要望","question":"私も、今回、インボイス制度見直しの意見書提出を要望する請願に対しては、今回は不採択でお願いしたいと思います。本来は国の制度なので、私は、国に直接、皆さんの団体ではっきりと要望するほうがいいと思うし、この区議会で、こういう意見書を要望する請願を認めてくれと言われても、私は少し方向性が違うのではないかなというふうに思います。品川区議会で受ける話ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":441,"id":"exchange-107"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。この間、インボイス制度そのものが国の検討事項であるので、国が決めていくべきものだと思うのです。現状をまだまだ把握し切れていないという、これは反省でもあるのですけれども、その中で、今の段階で国のほうに意見書を申し上げるまでの品川区内でのデータがないということは感想なので、今回は不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":442,"id":"exchange-108"}]},{"id":"topic-18","title":"令和８年陳情第２号、災害が起きても大惨事にならないために、公共施設の既存不適格を是正するよう、区に計画的に改修することを求める陳情","agenda":"令和８年陳情第２号、災害が起きても大惨事にならないために、公共施設の既存不適格を是正するよう、区に計画的に改修することを求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これからしていくという説明だったと思うのですけれども、そうすると、今、既存不適格とされているエレベーターについては、もしこの５１基が全て完了したら、完了した率を教えていただきたいのと、あと、使用年数の長いエレベーターから改修をということですけれども、大体どれくらいの期間を見ているのか伺いたいと思います。","respondent":"長尾施設整備課長","answer":"５１基を、今年度中に改修が完了する予定となっております。率で言いますと、おおむね全体の数の３割弱程度になっております。エレベーターの更新の年数としましては、目安としては２５年から３０年程度となっております。","voiceIndex":450,"id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"５１基、結構改修されるのだなと思っても、それが完了しても全体の３割弱ということで、やはり建てたときが１００％でも、法律が改正されていくと、やはり既存不適格になっていくということはあると思うのです。なので、区有施設のエレベーターで、この戸開走行保護装置と、地震時管制運転装置がついたものはどれぐらいあるのかということが分かれば教えていただきたい。","respondent":"長尾施設整備課長","answer":"その義務付けられた後に新しくつくられたエレベーターについては、６０基から７０基程度あります。ですので、そちらのエレベーターにつきましては、現行法にきちんと合った形で設置はされております。","voiceIndex":452,"id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この事故で息子さんを亡くされた親御さん、または、その息子さんと同級生や、その親御さんたちが、赤とんぼの会という会を立ち上げて、今もエレベーターの安全性について声を上げ続けています。事故が起きた当該区ということもあるのでしょうけれど、品川区としても、まず、区有施設への設置を早急に検討していただきたいと思うのですけれども、いかがでしょうか。","respondent":"長尾施設整備課長","answer":"今、港区の事例が出たところですけれども、品川区としましても、区有施設に設置されているエレベーターについては、順次改修を続けてきておりますし、今はまだ既存不適格が残った状態のエレベーターにつきましても、順次改修を進めていくように。","voiceIndex":454,"id":"exchange-111"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やらないということではないので、進めていくということで、ぜひやっていただきたいのですが、２０１６年の、平成２８年ですけれども、国交省が各都道府県に、エレベーターの安全確保の徹底についてという文書を出しました。市区町村においては、速やかに制度の整備を進めることというふうにもあるのですが、国がこういうふうに言っていることは把握されているでしょうか。伺います。","respondent":"長尾施設整備課長","answer":"既存不適格の解消に対する国の補助制度については、把握しております。品川区の中では、そういった補助制度が今はないというところも確認しております。","voiceIndex":456,"id":"exchange-112"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひ、この補助制度をつくっていくべきだと思うのです。区有施設は区でやることなのですけれども、やはりこういう制度をつくって、民間のエレベーターにも波及させていくということが必要ではないかと思います。こういうふうに国交省も言っているので、国も支援するから補助制度をつくりましょうということが言われているのですけれども、なぜ品川区ではやられていないのか伺いたいと思います。","respondent":"長尾施設整備課長","answer":"施設整備課の立場でお答えしますけれども、まずは区有施設のエレベーターの改修を今後も進めていければと、区民の皆さんが使われている施設もありますので、そちらのエレベーターの安全性確保というところをさらに進めていければと考えております。","voiceIndex":458,"id":"exchange-113"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"はい、分かりました。区が積極的に進めていくということが民間にも広がっていくということになりますので、ぜひそこは、こういう補助制度をつくるということの区の姿勢を示すということになりますので、ぜひ進めていただきたいなというふうに思います。国も設置するように進めているのに、それをやってこないで事故が起きたとなれば重大問題だと思いますので、ぜひそこは早急に進めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":462,"id":"exchange-114"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。すみません。なので、戸開走行保護装置と地震時管制運転装置を設置すべきだと思います。そして、早急に、障害者施設や高齢者施設、保育施設にという思いも分かりますので、ぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":466,"id":"exchange-115"},{"speaker":"西本委員","kind":"意見","question":"今の議論を整理してください。既存不適格というのは分かりました。それで、今、５１基、完了ということなのですけれども……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":467,"id":"exchange-116"},{"speaker":"西本委員","kind":"意見","question":"だから、全体で何基あって、もう不適合ではないものが何基あって、不適合なものが何基あって、その中に、もう終わっています、これからやります、これからはいつまでにできますかという数字で挙げられますか。それがよく分からなくなってしまった。","respondent":"長尾施設整備課長","answer":"そのうち、法改正後につくられたものが６０基から７０基程度となっております。ですので、既存不適格が残っているものが１２０基から１３０基ぐらいの状況となっています。そのうち５０基程度が、今年度までの工事の中で改修が完了するという状況になっております。","voiceIndex":468,"id":"exchange-117"},{"speaker":"西本委員","kind":"質問","question":"その８０基の予定は、いつぐらい、めどが立っているのですか。何年ぐらいでやっていくとかという計画はあるのでしょうかということと、この後ろに資料が添付してありますけれども、これ、駆動装置等の耐震対策とか、後ろにありますよね。そして、このデータは、情報公開請求か何かでとったのですか。どこからこれを引っ張ってきたのかなということがお分かりになっていれば教えてほしいのですけれども。","respondent":"長尾施設整備課長","answer":"既存不適格が残っているエレベーターの改修予定につきましては、具体的に何年度までに何基というような計画は、まだ今はございません。","voiceIndex":472,"id":"exchange-118"},{"speaker":"西本委員","kind":"質問・要望","question":"急にやれと言っても難しい話なので、もちろん今の法的なところで保障されたものになればいいのですけれども、徐々にやって、なるべく早くということで、定期検査をやっているわけですから、そこで安全性も常に確認をしている中でのことなので、そこは最低限やっていただきたいと思っています。もう１つ、この後ろの表はすごいなと思いました。とにかく安全に使えるようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":474,"id":"exchange-119"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、このような陳情ですが、品川区として改修を進めていると、それに対しては本当に安心しました。やはり、いざどういうことが起きるか、閉じ込めが多数発生したら、それこそ、その中にいる多くの区民の方が、老若男女、あと、子ども、それからご年配の方、本当に心配されますので、今後とも、できるだけ早く進めていただきたいと思います。頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":475,"id":"exchange-120"},{"speaker":"山本委員","kind":"質問・要望","question":"当然、危険性の高いものに対しては、すぐに是正していくべきですし、あれだと思うのですけれども、この陳情者の人が書かれている公共施設等管理計画の中での文言として、１枚目の最後から２枚目のところにかけて書かれている点検、診断等の結果によって、緊急度、危険度の高いものに対しては早期に修繕等の対策を講じるというようなことで計画にはあるという文言が書かれておりますけれども。","respondent":"長尾施設整備課長","answer":"公共施設等総合計画の中で、陳情書にも書かれている部分につきましては、点検とか診断等の結果を踏まえて、緊急度、危険度の高いものに対しては早急に修繕等対策を講じるというところが書かれておりますが、これは冒頭でご説明したように、定期点検のほか。","voiceIndex":476,"id":"exchange-121"},{"speaker":"澤田委員","kind":"確認","question":"本日結論を出す、不採択でお願いします。理由としましては、陳情者の方のお気持ちは大変理解できるものではありますけれども、ご説明にあったとおり、定期的な安全確認もされていますし、安全確保のほか、今後も順次古いものから改修をされていくということですので、これからも区民の安全のために進めていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":479,"id":"exchange-122"},{"speaker":"山本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。福祉施設から順次改修するというよりは、理事者の方の説明もありましたように、そのほかの施設も高齢者や障害がある方々もご利用する施設でもありますので、そういった意味からも、古いものから順番に適切に修繕をしていただくことを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":480,"id":"exchange-123"},{"speaker":"塚本副委員長","kind":"意見","question":"本日結論を出します。不採択でお願いします。既存不適格ということで、そういったものを一日も早く、すべからく修繕してほしいというのは、考え方としてはもっともだと思いますけれども、現実問題として、区が総合的に優先順位を決めて工事を進めていただいているということが、そのとおりに進めていってもらいたいと思いますので、本陳情については不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":481,"id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。陳情者の方も一度には難しいと思いますというふうにもおっしゃっていますので、そこは随時進めていただきたいと思うのですけれども、安心して利用するために、利用する方も多いと思われる障害者施設や高齢者施設から早急にという思いはよく分かりますので、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":482,"id":"exchange-125"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。陳情の趣旨のところで、要支援者が多くいる福祉施設からというふうに書かれております。福祉施設が、恐らく修繕、改修の必要性が高い１つの要素になり得ることは否定しませんが、実際には、安全の観点から見ていかないといけないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":483,"id":"exchange-126"},{"speaker":"須貝委員","kind":"意見","question":"本日結論を出すということと、不採択でお願いします。区では、今、もうエレベーターの修繕工事を着々と進めているということと、これからも修繕、ほかのエレベーター、まだ未修繕のものに対して、これからも修繕していくという、そういう考えていらっしゃるということで、私は、この陳情に対しては不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":484,"id":"exchange-127"},{"speaker":"西本委員","kind":"意見","question":"本日結論出す、不採択でお願いします。先ほど質疑の中で申し上げました。とにかく安全を確保していただくという対処をぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":485,"id":"exchange-128"}]},{"id":"topic-19","title":"令和８年陳情第１０号、シナモロール投票済証が衆議院選挙で配布されなかった説明と補填を求める陳情","agenda":"令和８年陳情第１０号、シナモロール投票済証が衆議院選挙で配布されなかった説明と補填を求める陳情","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"もう一度確認だけさせていただきたいのですけれども、投票済証自体は、今回、シナモロールではないですけれども、くださいという方については、いただけたのでしょうか。","respondent":"今井選挙管理委員会事務局長","answer":"そちらの投票済証につきましては、今回、イラスト入りではないのですけれども、東京都選管がデザインをしております投票済証を活用して、ご希望の方には１人１枚交付するという形で対応しています。","voiceIndex":493,"id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"認識不足で申し訳ないのですが、投票済証は、期日前投票だけですか。当日も配布ですか。","respondent":"今井選挙管理委員会事務局長","answer":"こちらにつきましては、投票済証は、投票が済んだ請求があったときに交付することとしまして、期日前投票だけではなく、当日投票でも交付しているものです。","voiceIndex":495,"id":"exchange-130"},{"speaker":"西本委員","kind":"質問","question":"よく期日前投票ではそういうものがあるという感じがあるけれども、当日は結構あるものなのでしょうか。先ほど、投票率には影響ないというお話もあったのですが、啓発になるという陳情者の方のお話もあるのですが、区としては、直接的な投票率を上げるというところまでには至っていないというものなのか、それはいかがですか。","respondent":"今井選挙管理委員会事務局長","answer":"先ほど申しましたとおり、何かすてきなデザインでということで工夫して、令和４年から７回にわたりシナモロールなどを活用してきましたけれども、この投票済証のみをもって投票率が上がったというのは、因果関係はなかなか難しいところですが。","voiceIndex":497,"id":"exchange-131"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も認識不足なのですけれども、他区にも誇れる特色ある取組とおっしゃられているのですけれども、これ、他区ではあまりやられていない、キャラクターがついてということはやられていないことなのでしょうか、伺いたいと思います。","respondent":"今井選挙管理委員会事務局長","answer":"今、２３区の中で、オリジナルと言われるイラストが入っているかどうかは別にしても、例えば、その自治体のお花の写真ですとか、あと、大田区もキャラクターを使っていると認識しておりますが、そういう自治体は全部で１８区、実際に投票済証、今回。","voiceIndex":499,"id":"exchange-132"},{"speaker":"澤田委員","kind":"意見","question":"私もシナモロールは大好きなキャラクターでもあるので、コンプリートしたいお気持ちは理解できなくはないですが、そもそもコンプリートを区として目的にしているわけではないこと、そもそもの目的は、投票率の向上や選挙啓発であって、税金を使っているため、個人の嗜好だけを加味するものではなく、キャラクターの使用料など費用対効果なども考慮し、区として検討の上、デザインを決定されていると思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":502,"id":"exchange-133"},{"speaker":"山本委員","kind":"質問・要望","question":"先ほど、理事者の方からのご説明のとおり、投票を促進するだったり、当日投票したことを証明するためのものですので、今回の陳情者の要望である投票が終わった今、投票済証をシナモロール投票済証に引き換えるというのは、今からやるというのは合理性に欠けるのかなというところです。今後の投票済証へのご要望のところについては、ひとつのご意見として、ご要望として受け止めるということだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":503,"id":"exchange-134"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"本日結論を出します。不採択です。説明と補填を求めるということなのですけれども、これまでの説明に加えての説明の必要性、また、何らかの補填といったことについても、必要性は認められないので、私としては不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":504,"id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。今回の選挙は、本当に突然の解散でして、時間もないというのは多くの方が分かっていたと思います。なので、そこに理由を説明することは、少しやり過ぎかなというか、そこまで求めますかという感じが私はしました。なので、様々あっていいと思いますので、そこはぜひ検討しながら進めていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":505,"id":"exchange-136"},{"speaker":"松本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。本陳情は、「補填」という言葉まで使われております。それに対して補填というのは、補填ということは、権利があって求めるというふうな論理構造になっていると思うのですけれども、そこまで言われてしまうのは、少し残念だというふうに思います。なので、本件については不採択というふうな意見を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":506,"id":"exchange-137"},{"speaker":"須貝委員","kind":"意見","question":"本日結論を出すということと、不採択でお願いいたします。短期間の中での選挙準備をしていました。その中において、投票済証の問題をここで言うのではなく、無事に投票が終了したこと私は称賛したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":507,"id":"exchange-138"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いいたします。ここまで求められてもということがあります。それと、先ほどもシナモロールだけではなくて、いろいろなキャラクターもいれば、そこは選挙管理委員会とか、明るい選挙推進協議会とか、いろいろありますので、そこで検討していただければいいのではないかなと思います。ここまでは言われるほどのものではないのではないかと、少し残念な気持ちでいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":508,"id":"exchange-139"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7321#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":98722,"voices":514}},{"id":"r08-20260225-6","meetingId":"r08-1t","date":"2026年2月25日","dateIso":"2026-02-25","committee":"区民委員会","time":"午前１０時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"しながわ生活応援事業の進捗報告","agenda":"しながわ生活応援事業の進捗報告","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"昨年末に引き続きまして進捗報告ということで、今回バニラＶｉｓａギフトカードを選定したというのはあちらこちらで使えるから、品川区だけでなくいろいろなところで使えて、とにかく生活支援、物価高騰対策を主軸にこれでやっていくということでこれになったと思うのですけれども、基準日が令和８年１月１日になっておりまして、これは全国統一なのでしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"設定の理由といたしましては、今回は国の補助金を受ける事業ですので、年度内にその補助金の精算をしなくてはいけないという精算作業のバッファーをある程度持たせて、３月３１日から２か月程度の精算期間を持たせて。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"お引っ越しされた方にも送付はされるのでしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"失礼いたしました。転居された方におきましては、転居先にギフトカードが送られることになります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おぎの委員","kind":"提案","question":"そうしますと、自治体ごとですので個人によってはあぶれてしまう方も出てくるのかというのは仕方ないのかとは思います。簡易型プロポーザルについて、先ほどご説明いただいた４番の(1)から(4)の項目でやっていただける事業者の中でよりよいところから選定するということで、コールセンターもまとめて全部委託するという認識でよろしいのでしょうか。この辺、いかがでしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"今回の契約の形式ですけれども、基本的には２つに契約が分かれる予定です。１つは、資料の表面で言いますと事業予算の部分です。バニラＶｉｓａギフトカードの調達の部分です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"こんの委員","kind":"質問・要望","question":"何点かあります。次はギフトカードの件ですけれども、バニラＶｉｓａギフトカードを選んだ理由はどういうものなのかということを教えていただきたいです。このカードを頂いて買物をしたときに、最後に端数が残ってしまうということがあるではないですか。その辺についても、配ったときに使い切り方みたいなものの周知が必要だろうと思うのですが、その辺はどういうふうにご用意をされていくのでしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"ただ、転入手続の猶予期間と言いますか、１月１日にすぐ手続を取れない方というのは一定いらっしゃるかというところがありますので、その辺は少しバッファーを持たせて対応するということも今検討していますけれども。","voiceIndex":13,"id":"exchange-004"},{"speaker":"こんの委員","kind":"質問・要望","question":"ありがとうございました。転入者については分かりました。それから、ギフトカードについて。なので、先ほどご説明がありましたリーフレットは、品川区としての案を提示してということですので、その辺のところを分かりやすく、また、コールセンターのほうもこうした質問があった場合に、より詳しくお話ししていただきたいというところではあるのですが、ちなみにコールセンターは何台設置する予定でしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"コールセンターの部分につきましては、これから簡易型プロポーザル方式の中でその体制も含めて事業者の方から提案をしていただいて、その中で最も手厚い体制の部分を評価した上で決定していくというような形になりますので。","voiceIndex":15,"id":"exchange-005"},{"speaker":"こんの委員","kind":"提案","question":"プロポーザルなので、事業者の提案を待つということは理解するのですけれども、区としてこれまでのコールセンターの在り方として一応腹案というか、要するにゼロベースで事業者からのプロポーザルを待つというよりは、大体これくらい必要ですよね、品川区としてこういう体制ですよねというのは持ち合わせていらっしゃるのではないですか。","respondent":"今井しながわ生活応援担当課長","answer":"申し訳ありませんが、プロポーザルの実施概要の中にはそこまで細かい規定については入れておりませんけれども、過去のしながわ活力応援給付金事業の中でコールセンターには１万６,０００件の問合せが入ったというところも事業者には説明をさせていただいて。","voiceIndex":17,"id":"exchange-006"},{"speaker":"こんの委員","kind":"確認","question":"すみません。その辺というところでは、区としてどう課題を捉えていて、精度を上げたコールセンターにしていこうと思っていらっしゃるのか、お考えだけ確認させてください。","respondent":"今井しながわ生活応援担当課長","answer":"業務フローにつきましては、区と協議しながら受託者において資料ですとか対応フローを事前に作成して、適宜対応を適切にできるように体制をつくることというところを示しておりますので、そういった最低限の条件を受けた上で事業者の中から提案をしていただいて。","voiceIndex":19,"id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"フローも分かりました。その辺の対応力が必要かと思ったので、このお話をさせていただきました。ぜひプロポーザルの中で、どういうふうにそれを対応されるのかというところをしっかりお聞きしながら進めていただきたいと思います。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これからは事業者選定段階になっていきますけれども、今品川区のホームページ上で生活応援事業の周知、告知をしていますよね。しながわ生活応援担当が担当になっていて、現時点で問合せがあると思うのですけれども、今はどういう感じなのか最初にお尋ねします。","respondent":"今井しながわ生活応援担当課長","answer":"１日１０件以上問合せは頂いているところでございまして、多い質問としては春以降配布開始ということでお伝えしておりますので、具体的にいつ頃発送なのかというようなお問合せを多く頂いているところです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。事業者が決まったら、当然ホームページも更新しなければいけないではないですか。そこの更新時期がいつ頃というのは多分見えていないと思うのだけれども、それをなるべく早めに決まった時点で周知活動もやっていただきたいということがあります。事業者が決定してからだと思うのですけれども、区としてはどういう方向性でいるのかお尋ねしたいと思います。","respondent":"今井しながわ生活応援担当課長","answer":"コールセンターの設置場所につきましては、事業者からの提案にもよりますけれども、基本的には事業者の用意した場所で設置していただくことになります。","voiceIndex":25,"id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"提案","question":"どうもありがとうあります。最後に、４番の簡易型プロポーザル方式により提案を受ける業務の概要の中で、誤封入防止の作業があって、誤封入は一番あってはいけないけれども、人がやることだからあり得る話です。そこは、区のほうで徹底していただくということをお願いしたいと思います。これはお願いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-011"},{"speaker":"おぎの委員","kind":"質問・要望","question":"すみません。使用期限が迫ってくるとぎりぎりの使用なども増えてきますので、残額をうまく使い切れるようにプラスアルファで１点これを足して買うとぴったりですよみたいな、お店の売上げにもつながりますので、なるべくそういった声かけを高齢者の方などには積極的にしていただいて、お店の売上げもそうですし高齢者もしっかり使い切れるみたいなそういった形にしていただきたいです。要望です。","respondent":"今井しながわ生活応援担当課長","answer":"今回の事業を実施するに当たって、区内各商店の協力が必要だと所管としても考えているところでございまして、先月の商店街連合会の担当者の説明会で、今回ギフトカードを春以降に配布する旨、またこういった使用方法になりますということで。","voiceIndex":28,"id":"exchange-012"}]},{"id":"topic-02","title":"臨海斎場増築計画の進捗","agenda":"臨海斎場増築計画の進捗","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"何点かお伺いしたいと思います。都市計画変更決定の今のご説明で確認ですが、３月２７日に住民説明会を大森スポーツセンターで行いますという説明について、これは全区民にお知らせをしていくものなのか。いわゆる火葬炉の機能向上というところは、どうなっているのか確認させていただきたいです。２階の平面図で、こちらは待合室のみになっていますが、新たにできるところに売店はつくらないのでしょうか。","respondent":"築山戸籍住民課長","answer":"しかしながら、臨海斎場は立地しているところから１km圏内に住宅がありませんので、基本的には近隣への説明という形ではないのですが、やはり近くにいらっしゃるということで、大田区にある大森スポーツセンターで実施することとしたものです。","voiceIndex":34,"id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"ありがとうございました。住民説明会、分かりました。広報しながわでも、もしかしたらこういう説明がありましたという記事にするということもあるかもしれないですが、両方、紙媒体もホームページでもより多くの方がこうした内容が分かるようにお知らせしてさしあげたらどうですかということがあります。それから、平面図のほうですけれども、風除室は分かりました。その辺の様子を伺いたいと思います。","respondent":"築山戸籍住民課長","answer":"住民説明会の資料等につきましては、臨海斎場のホームページで掲載される予定となっておりますので、区のほうもリンクを貼るなどして区民の方にアクセスしやすいよう考えたいと思います。","voiceIndex":36,"id":"exchange-014"},{"speaker":"こんの委員","kind":"確認","question":"いずれにしても必要な設備、こうした対応ですので、より今ある既存のものよりも機能を強化したものがつくられていくということが必要かと思ったので細かい点を何点か確認させていただきましたが、いずれにしても令和１２年に供用開始となりますので、その時期までに既存の対応で非常に込み合っている葬儀、火葬炉ですけれども、いろいろな対応を今考えてくださっておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"おぎの委員","kind":"確認","question":"１点だけ確認させてください。今のお話をお聞きしまして、今後のスケジュール等も遅れがなく進んでいるということをお聞きして安心しました。今、既存棟は改修してお部屋を増やすということですけれども、今後は増築棟と既存棟を交互に改修して交互にお休みしてという形を取られていくという認識でよろしいでしょうか。","respondent":"築山戸籍住民課長","answer":"増築棟ができると、増築棟と既存棟をくっつける必要がありますので、既存棟から増築棟に行き来ができるような形にしますので、その辺りで既存棟の部分、増築棟に接する部分の階段の改修が必要になると聞いておりますので。","voiceIndex":40,"id":"exchange-016"},{"speaker":"おぎの委員","kind":"質問","question":"接合する部分で改修工事は入ると思います。前にお聞きしたときに、それぞれの機能が独立しているので今後１０年、２０年計画で改修工事というものはそれぞれにということでしょうか。","respondent":"築山戸籍住民課長","answer":"委員のおっしゃるとおり、増築棟と既存棟の機能をそれぞれ独立させることによって今後将来的に大規模改修が必要になった場合にどちらかを止めてどちらかを運営して、いずれにしても火葬事業は継続できるような形にすると聞いております。","voiceIndex":42,"id":"exchange-017"},{"speaker":"こしば委員","kind":"質問・要望","question":"広報しながわになぎさ会館の閉館の記事が出ていまして、地域の方も大変関心を持たれているというのが実際のところですけれども、意外に臨海斎場の存在が知られていない、知らないという方もいらっしゃって、まずはそこら辺の周知をぜひお願いしたいと思います。その辺の影響についてどう見込んでいるのか、教えていただきたいと思います。","respondent":"築山戸籍住民課長","answer":"そういった中での廃止となっております。一方、臨海斎場が新たな式場を増やしておりますので、増やした式場の中で十分に式はできるというところで、式場利用という面において、影響ははないと考えております。","voiceIndex":46,"id":"exchange-018"},{"speaker":"こしば委員","kind":"質問・要望","question":"説明していたらすみません。先ほどのこんの委員の質疑の中で、告別式をやってだびに付して収骨室からご自宅に持ち帰るけれども、その時間帯がかぶらないように事業者のほうで設定をしていくということであるので、そうなりますと一般的には１１時前後がこれまでの告別式の大体の時間帯であると思うのですが、それが例えば午後になってくるとかそういうような捉え方でよろしいでしょうか。","respondent":"築山戸籍住民課長","answer":"火葬の時間は、朝早い時間から夕方までやっておりますので、そういった中で新たな式場も増えるというところで、式場の告別式につきましてはご家族のお考えにもよるかと思いますけれども、朝の早い時間帯から夕方までの時間帯。","voiceIndex":48,"id":"exchange-019"},{"speaker":"こしば委員","kind":"質問","question":"恐らく、葬祭業者の方からもそういった説明や案内もあると思います。待合室ですけれども、多分１階で告別式を行いまして、だびに付している間に２階の待合室でお待ちになると思います。こちらのほうは、料金は特にかからないというようなイメージでよろしいでしょうか。それはまた、葬祭業者との兼ね合いもあるので、違ってくるのかもしれませんけれども、その辺りを教えていただければと思います。","respondent":"築山戸籍住民課長","answer":"火葬待合室ですが、現在品川区民の場合ですと使う場合は２万円の使用料金を頂いております。新しい式場でも料金は取ることになるかと思いますので、そこはまた臨海斎場のほうで検討して、決まりましたら委員会でもご報告をさせていただきたいと考えております。","voiceIndex":50,"id":"exchange-020"},{"speaker":"こしば委員","kind":"意見","question":"やはり、今はいろいろな需要があると思いますけれども、特に東京都内の葬儀場が大変高騰しているということがずっとこの一連の話が出てきた中で、最期の見送りというのは尊いものでありますので、品川区はこの臨海斎場の運営に携わってはいますが、品川区だけでは決定することはできないかもしれませんけれども、利用される方の負担を減らしていくようにお願いしたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-021"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。民間の火葬場だと超大型炉というのはどのくらいあるのですか。例えば、桐ヶ谷斎場とか。私は把握していないのだけれども、数がどのくらいあるのか教えてほしいです。","respondent":"築山戸籍住民課長","answer":"２３区でいきますと、町屋斎場にあると聞いております。町屋斎場に超大型炉が何炉あるかまでは分からないのですけれども、１２０kgを超えるような大きな体型の方がお亡くなりになった場合は、町屋斎場で火葬していると聞いております。","voiceIndex":56,"id":"exchange-022"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。では、今度臨海斎場にできるというのはやはり需要があるから、１か所しかないわけだから、やはり絶対に必要になってくると思います。なので、また分かり次第教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-023"}]},{"id":"topic-03","title":"区民葬儀における助成制度","agenda":"区民葬儀における助成制度","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"支給要件のところを確認させていただきたいと思います。１番は、要するに火葬券が使えないから、祭壇券あるいは霊柩車券を活用した方には火葬料金の補助をしますという理解でいいでしょうかという確認です。最もだから一番下なのかということをイメージするのですが、その辺のところをもう少し詳しく教えていただきたいと思います。お願いいたします。","respondent":"築山戸籍住民課長","answer":"最も低廉という部分ですが、現在東京博善の火葬が９万円になっております。これが４月１日から８万７,０００円になるというふうに東京博善のほうからプレスされておりますが、この８万７,０００円が最も低廉な火葬料金ということで考えております。","voiceIndex":63,"id":"exchange-024"},{"speaker":"こんの委員","kind":"確認","question":"確認させていただきました。直葬の方も結局祭壇はつくらない、霊柩車も使わない、いわゆる臨海斎場で言うお別れのお部屋みたいなものがここに書かれている火葬場にあるかどうか分からないです。その人たちも対象になるのかということをもう一度確認させてください。だから、一番低い火葬炉を使用された場合の金額に対してという理解でいいでしょうかということをいま一度確認させてください。","respondent":"築山戸籍住民課長","answer":"次の火葬炉の値段の部分です。８万７,０００円が一番安い火葬料金となっておりますので、ここを利用された方ということで考えております。","voiceIndex":65,"id":"exchange-025"},{"speaker":"こんの委員","kind":"確認","question":"直葬も対象になるといったところも確認させていただきましたので、いずれにしても亡くなられた方がお金のあるなしに関わらず、きちんと弔われるというこの体制は非常に大事なことだと思います。なので、この体制を品川区としてもつくっていただいたのは大変ありがたいと思います。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-026"},{"speaker":"おぎの委員","kind":"質問・要望","question":"もし、そういった情報等があれば教えていただきたいと思います。","respondent":"築山戸籍住民課長","answer":"ただ、今回区民葬儀を脱退することによって、その持ち出し分相当額については火葬料金を下げる、９万円の火葬料金を８万７,０００円に下げるということで、全体に還元をするという考えを示しています。","voiceIndex":69,"id":"exchange-027"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今回は、高くなっているから区民と都民のためにお金を出します、助成金制度をつくりますというのは、当面の対応としては仕方がないかとは思いますが、今後さらにどうしていくのか。東京博善がまた値上げしていく部分ももちろんあるとは思いますので、引き続き色々な方法で模索していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-028"},{"speaker":"こしば委員","kind":"質問・要望","question":"その組合も、当然に区民葬の対象の店舗です。これが今後ビジネスの１つとして、例えばホームページにうちで火葬する場合にこの助成の制度を使えますといったメッセージが発信されていくのではないかということをすごく懸念しています。これまでの日本の慣習に合わないと私は思いますので、この辺は品川区からも自治体の権限というものが法律上ありますので、ぜひその辺はくぎを刺していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7329#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":22087,"voices":80}},{"id":"r08-20260225-7","meetingId":"r08-1t","date":"2026年2月25日","dateIso":"2026-02-25","committee":"厚生委員会","time":"午前１０時００分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区障害福祉計画・障害児福祉計画策定のための基礎調査結果報告","agenda":"品川区障害福祉計画・障害児福祉計画策定のための基礎調査結果報告","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"それと、８月の段階でこういう調査をしますよということでご報告をこの委員会でいただいているのですけれども、そのときに例えば、サービスの利用されている方は受給者証を持っている人だけではなくて、持っていないけれども、地域生活支援事業などを利用されている方も含まれているのかどうかというふうなことも伺ったと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何て言うのですか、この結果はこうでしたという、その結果の事実だけを書いていて、その結果からこういうふうなことが考えられるとか、こういうふうなことが明らかになったとか、そういうような分析というものがないと思うのですけれども、この分析ということについては、どう区としては考えられていて、前回も本文の中にもあまりなかったような気がするのですけれども、分析はどのように考えられていて。","respondent":"田中委員長、佐藤障害者施策推進課長","answer":"最終的にそれを踏まえて、載せる載せないの判断は正副と理事者との調整で対応しますが。医療的ケアに関する……。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"前回の８月のところでも本来であれば策定委員会をもっと前につくって、策定委員会でも調査項目とか何かをいろいろ検討してもらって、より障害者の方々がもうどんなことで困っていて、何が必要で、どうしなければならないのかということが見えてくるような調査項目にしたほうがいいのではないかという意見がここの委員会でも出されていたと思うのですけれども、でも、策定委員会というのは取りあえず。","respondent":"佐藤障害者施策推進課長","answer":"こちら、１１月から１２月にかけて実施したところで、こちらに関しても今、まとめているところで、これに関しても策定委員会のほうでまた報告等はする予定です。","voiceIndex":13,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私はそれは、今回終わってしまったのであれなのですけれども、医療的ケア児者の方々に対してはぜひ全員に、サービス使っている方全員にというふうなことでやっていただいていますけれども、それと同じように医療的ケア児者の方って、医療だけ使っているという方も結構いらっしゃるので、困りごとも含めて、また、サービスも知らなかったりすることもありますので、ぜひ今後に向けて。","respondent":"佐藤障害者施策推進課長","answer":"資料、次回策定委員会に出す資料につきましてはこれから調整等含めまして、それから事務局のほうで調整して出すというところになりますが、委員のご指摘も踏まえまして、なるべく完全な資料、それから今回出た結果の概要ですとか。","voiceIndex":15,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"そういうものの中からやはり今後の計画にどう反映していくのかというふうなものが出てくると思いますので、そこら辺の現場の人材の確保の問題だったりとか、そういうふうなこともあると思うのですけれども、そういうところでの、何と言うのですか、今後、障害者福祉をより充実をさせるための計画になるように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"今のご質疑で大分いろいろなことが分かってきたのですけれども、一点、分析まで委託したのだというか、分析を委託するとしても、分析の視点と言うのでしょうか、それは区の計画ですので、当然区のほうでそれは出されていると思うのです。それから、策定委員会についてなのですけれども、さらっと障害者団体の方も参加してというふうになっていましたけれども、今の障害者７団体に限るということでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"策定委員会への部分ですけれども、まず、団体につきましては現時点では前回と同じ、こちら７団体というところは今回も予定しています。","voiceIndex":19,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"繰り返しになりますが、７団体の功績は本当に評価をしておりますし、７団体がみんな参加できるようになったのが比較的最近なので、それができるようになったということも、いろいろな、自立支援協議会でも参加できるようになったというのは本当に評価をしておりますけれども、一歩踏み込んで、やはりその方たちに影響がある計画を策定するわけですから。","respondent":"佐藤障害者施策推進課長","answer":"そういう意味ではヒアリングに関しても先ほど１５と申し上げましたけれども、それが全てかと言われると、様々な活動をされていらっしゃる団体というのはあるかと思いますけれども、なかなか把握し切れていないといったところも場合によってはあるところで。","voiceIndex":21,"id":"exchange-007"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お伺いしたいことがありまして、アンケートの８ページです。前回の調査も見てみたら、結構同じぐらい多かった、４割ぐらいだったと思うのですけれども、これって無回答というのは区としてどういうふうな理由というか、何かこれだけ、要は一番多いわけです、４割占めているわけで。どのように認識されていらっしゃいますでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"こちら、主な介助者のほうが、例えば、在宅障害者のところ、回答者数が６４９というところで、回答していただいた方の数が限られるというようなところ、こちら、この前に介助を受けているかどうかというようなところの設問がありまして。","voiceIndex":24,"id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ごめんなさい。私が認識できなかった。では、この３９パーの無回答というのは何か区として特定のというか、介助して、第１、第２介助者がいるという前提での回答で、無回答になっていてというところで、特に何か把握していることはないということですか。","respondent":"佐藤障害者施策推進課長","answer":"すみません。要は介助がお一人でされていて、第２介助者までいる方、２人目と言いますか、介助されている方が６割の方、４割の方はお一人、介助されている方がお一人というようなところでの状態であるのかなというふうに、こちらの結果については認識をしています。","voiceIndex":26,"id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ちょっと次の質問に移るのですけれども、先ほど分析の話がありまして、区としても今のところ、ある程度は、今の段階でも分析はしているということでよろしいですか。ちょっとそれを踏まえてお伺いしたいことがあるので、お伺いします。","respondent":"佐藤障害者施策推進課長","answer":"結果につきましては一通り目を通しているところはありますので、どうしてこういう数字になったかというのは全て把握できているところではございませんが、先ほどのものになりますけれども、一部の数字についてはこういった施策の効果が現われているのかなですとか。","voiceIndex":28,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"意見","question":"というのを考えると、先ほどの最初のところと合わせると、金銭的に不安を感じている方も増えているし、そして働きたいという方も増えているというような状況が見てとれて、やはり区としても様々な施策、今、超短時間雇用とか含めてですけれども、していただいていると思うのですけれども、こういったところは調査結果からもぜひ酌み取っていくべきかなと思うのですけれども。","respondent":"佐藤障害者施策推進課長","answer":"やはり委員おっしゃるとおり、まず、困りごとに関して経済的な部分等について数字が伸びているという部分は社会全体の状況というのも、おっしゃるとおり、あるのかというふうなところ、それから今後の就労希望につきましても、おっしゃっていただいたとおり、年齢別で見ますと。","voiceIndex":30,"id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問","question":"最後に一つだけ、別の項目なのですが、１６ページのところのサービス利用の際の困りごとというところで上から３番目の利用したいサービスが利用できないというのが今回、５％ほど増えてしまっているというところがありまして、これに対して、要は３割ぐらいの方が利用できないという困りごとがあるというか、これに対して区としての受け止めというか、何かあればお伺いしたいのですけれども。","respondent":"佐藤障害者施策推進課長","answer":"こちら、利用したいサービスが利用できないというところでは、障害児というところで考えると、サービスなど、そういったところについて利用したいけれどもというようなところがあるのかというふうなところ、そういう意味では、今年度。","voiceIndex":32,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問","question":"これで回答者、１,８３２人なので、そこを割り返すと２６４人という数字が出てくるのですけれども、今度の計画を立てるに当たって必要量、どれくらい区として必要と考えているかという必要量を様々出していかれるということだと思うのですけれども、今まではこれくらいになるのではないかという見込み量だけだったと思うのですけれども、見込み量と必要量というのは。","respondent":"佐藤障害者施策推進課長","answer":"２２ページのところの例を挙げていただきましたけれども、こういったところ、まさに委員おっしゃっていただいたとおり、施設の整備の今後の方針等につきましては必要量、おっしゃっていただいたとおり。","voiceIndex":35,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"意見","question":"その必要量をどう出していくのかというのは世田谷区の方針とか何かを見ても、かなり、もう本当に……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"あと、医療的ケアの２倍も増えているというところが、レスパイトとかの仕組みもあるにもかかわらず、こういうふうな状況になっているというふうなところで、レスパイトも時間数が増えてもそれを受けてくれる事業者がなくて、なかなかそれが思うように使えないというふうなことも伺ったのですけれども、医療的ケア児のレスパイトについては私も決算特別委員会のときだったと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-015"}]},{"id":"topic-02","title":"国保財政健全化計画","agenda":"国保財政健全化計画","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"２の計画内容のところの4)の柔道整復療養費に対する二次点検の実施というところなのですが、具体的にどういったことを実施しているのかお伺いしたいのですけれども。","respondent":"山下国保医療年金課長","answer":"そういったものを突合してご照会をしたものについて実際に施術をされていらっしゃる事業所のほうに調査のほうを実施するといった内容です。","voiceIndex":48,"id":"exchange-016"},{"speaker":"やなぎさわ委員","kind":"質問","question":"委員長、すみません。ちょっと今、聞き逃して。二次点検自体が２,０００件で突合が１,４００件でよろしいですか。","respondent":"山下国保医療年金課長","answer":"そちら、アンケートのような形でちょっとご回答、ご協力いただいた方の結果を踏まえて、実際に施術をしていらっしゃる方にご照会をかけているところは１,４００件余というような状況で実施をいたしたところです。","voiceIndex":54,"id":"exchange-017"},{"speaker":"やなぎさわ委員","kind":"確認","question":"２,０００件が照会で、１,４００件が実際治療院に送付しているとかいう、確認を行っているという件数ということでよろしいでしょうか。","respondent":"山下国保医療年金課長","answer":"実際に送付した件数と必ずしも一致しないかも知れないのですが、アンケートを踏まえて突合の点検を実施した件数になりまして、その後、郵送した件数というのは、すみません、手元にはちょっとございません。","voiceIndex":56,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ちなみに、それでこういった療養費を抑えるための取組だと思うのですけれども、こういったところで年間どのぐらいの削減というか、イメージというか、具体的な数字があればいいのですけれども、あれば教えてほしいし、どれぐらいの削減につながっているのかなというのがもしお分かりになればお伺いしたい。","respondent":"山下国保医療年金課長","answer":"こちらの実施の効果額、ジェネリックですとか、柔道整復のものが幾ら効果、寄与したか、財政的な金額的な面で具体の数字としてお示しをすることは難しいのですけれども、件数として大体２,０００件からそういった１,４００件というところの確認をしておりますので。","voiceIndex":59,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7327#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":21911,"voices":69}},{"id":"r08-20260225-8","meetingId":"r08-1t","date":"2026年2月25日","dateIso":"2026-02-25","committee":"建設委員会","time":"午前１０時００分～午後 ２時２７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"戸越公園駅交通広場事業等の都市計画事業認可取得","agenda":"戸越公園駅交通広場事業等の都市計画事業認可取得","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"その上で幾つか質問させていただきたいのですが、事業期間について、駅前広場のほうが連続立体交差事業より長いというのはなぜなのか。この期間の根拠を伺いたいと思います。それと３点目で、駅前広場なのですが、お祭りや商店街のイベントで使えるようにして欲しいというような話も地域のほうからは出てるようなのですが、こちらは使えるのかどうか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"基本的な考え方といたましては、最終的には当然、通常の道路になりますので、道路使用許可だとかそういったものが必要にはなってくるかと思うのですけれども、使えるように地元ともお話しさせていただきまして、今後まちの皆様と協議しながら。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"棟数ですね。連続立体交差事業プラス側道のほうの事業と、あと駅前広場のそれぞれについて数を伺いたいです。それと、もし分かれば居住世帯数や居住の人数などを伺いたいと思います。それと、用地測量を実施した中で、権利者と接触することがあると思うのですけれども、連続立体交差事業や交通広場等の整備に伴う立ち退きに対して、どのような声が寄せられたのか、それぞれ伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましては、引き続き交通広場の必要性をしっかりと丁寧に説明しながら、事業のほうを進めてまいりたいと考えているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、これから都の事業と区の事業があるのですけれども、私たちは、補助２９号線と併せてなのですけれども駅前広場は必要ないのではないかという立場です。憲法第２９条にあるように、財産権を守るということ。先ほど具体的な例も挙げましたが、そういったことも含めて区として、生活再建、補償への責任を果たしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"事業による補償の詳細につきましては、今後実施を予定しています用地補償の説明会の中でしっかりと説明いたしまして、各権利者それぞれのケースによりその後の具体的な補償内容が異なってくるため、個別に相談に応じていくような形で対応してまいりたいと考えているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"それが基本なのでしょう。ですから、区には様々な事業があります。従前居住者住宅等ですね。そういった様々な横の連携も使って、個別のケースによると思うのですけれども、やはりその方が生活を再建するにあたって求めることに、なるべく寄り添って、実現していただきたいという思いで聞いてるのですが、そういったことの責任について、改めて最後伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"引き続き、しっかりと事業の必要性等を説明しながら、補償の面につきましても、今後必要な対応を図ってまいりたいと考えているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"どちらも連動して１０年、１２年後のまちの姿のイメージを持ちながら進めていくという説明だと思います。なので、踏切解消は地元の強い要望でもありますけれども、タワーマンションをどんどん造っていくことは住民は望んでいないと私は思うのです。伺いたいことは、この交通広場の整備、踏切解消は、戸越公園駅周辺再開発を進めるためのインフラ整備という位置づけでよいのか、ご説明いただきたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"連続立体交差事業につきましては、今委員からもありましたとおり、地域からの要望が事業の始まりという形で、区としても認識しています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"これはだってどう考えても、再開発のためにやるのではないですか。再開発を誘導するそのものだと思うのですが、なぜそこを認めず、むしろ否定をするのか。いや、そう思っているのだったら、そう思っていると説明すればいいだけだと思いますので、改めて伺います。そこに合わせてこの２つの事業が進んでいると私は思っているのですけれども、違いますでしょうか。ご説明ください。","respondent":"大石まちづくり立体化担当課長","answer":"２棟以外に戸越で再開発が進められるのかというところがございましたけれども、まちづくりビジョンにおきましては、戸越公園駅を挟んで北側と南側に各拠点を整備していくという形で示しています。現時点で、地域からほかの再開発の事業を聞いているところではございません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"何でここに交通広場を造るのか。立ち退きを求める事業なわけですから、一つの事業として生活再建策のスキームをしっかり説明をするということは当然の姿勢ではないかと思うのです。今後、用地補償説明会が開かれるということですけれども、その生活再建策のスキームをしっかりと建設委員会でも示して、説明して、質疑を保障すべきではないかと思うのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"用地補償説明会の開催概要が決まりましたら、建設委員会のほうで開催の時期だとかをお知らせする予定ですので、そちらで基本的な補償の内容など、そういったものはお話しできると考えているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"生活再建策のスキームがあるわけですから、今建設委員会への説明のことは述べられましたけれども、用地補償説明会の前にそのスキームを示していただきたいと思います。交通広場の工事自体は品川区も別に初めてではないですから、ここだけ特別に何か今までと仕組みが違うとも考えにくいのです。３つ目が、事業認可が取得されたとはいえ、土地建物は任意売却ということで良いのか、そこを伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"補償費、いわゆる建物の解体費だとか引越しに要する費用だとか、そういった補償費に関しましては、東京都や品川区の補償基準に諮りまして、しっかりと算定するという形になってあります。２点目の引越し先は自分で探すのかというご質問です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"土地と建物は財産価値審議会にかけて区が決定するということです。区が協力できるところというのは具体的にどういうところなのか伺いたいと思います。こういう手法もあるのだと。聞いた話なので、今の説明で間違いがあったら指摘してほしいのですけれども、だとすると引越し先は自分でなどと言わないで、そういう手法も検討することはできないものなのか、最後に伺いたいと思います。","respondent":"森用地担当課長、大石まちづくり立体化担当課長、溝口防災まちづくり部長","answer":"今、まちづくり立体化担当課長から説明がございましたけれども、財産価格審議会の答申に基づいて価格を決定するです。具体的にこの場で今お話しできることがないのですけれども、区といたしましては、まずはしっかりと権利者の意見を聞きながら。今回の交通広場の整備とかそういう都市計画にはなるのですけれども、まちづくりの中で従前居住者の権利を守るというか。","voiceIndex":21,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"引越し先は原則自分で。それで伺います。今土地の価格がどんどん値上がっているので、１年でも変わってくる。自分の財産ですから。今、これだけ２３区内、品川も含めて土地の値段がいわゆる不動産バブルのような状態が起きているわけですから、そういう意味ではもう少し土地の価格が上がるのを待ちたいと思うのは、私は正当な主張だと思うのです。これで最後にしますが、それぞれいかがでしょうか。","respondent":"森用地担当課長、大石まちづくり立体化担当課長","answer":"ですので、任意でしっかりと売却を行っていただいて譲っていただくために、用地担当も所管課もしっかりと説明を尽くしてまいりたいと思っています。いずれにいたしましても、権利者の皆様には事業の必要性だとか補償の内容、その辺も含めてしっかりとご説明いたしまして、寄り添った対応をして、事業に協力していただけるよう尽力してまいりたいと考えているところです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"ゆきた委員","kind":"確認","question":"事業費についてですけれども、戸越公園駅交通広場事業が４４億円で、立体交差事業が４２７億円。この中に用地取得費と、あと移転補償費等も含まれているという認識ですけれども、改めて確認できればと思います。これらの用地取得費、補償費が、総事業費のうちのどのぐらいの割合を占めているのか、現時点での規模感の内訳というものが分かれば教えていただければと思います。","respondent":"大石まちづくり立体化担当課長","answer":"合わせて４４億円余という状況になってあります。委員ご指摘のとおり、ほぼというか４４億円のうちの３７、８億円が、いわゆる用地取得費になっているというものです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。先ほど、ここも変わらないという議論がありましたが、現時点での積算は将来的な変動リスクを一定程度織り込んだ積算になっているのか、変動リスクへの備えについてどのように考えているのか、改めてお聞きできればと思います。","respondent":"大石まちづくり立体化担当課長","answer":"事業費につきまして、物価変動等を考慮しているかです。こちらにつきましては現時点での想定の金額を入れているものです。今後どのような形になるか分からないので、今現状といたしまして、現時点での価格という形で算定しているものです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"松永委員","kind":"質問","question":"３点ほどお伺いしたいのですが、まず１点目は、この交通広場の場所に町会会館があると思うのですけれども、その町会会館の方、町会としてはどういった形でお話をされてるのかというのが少し気になったので、お伺いしたいと思います。タクシープールとかバスとか、公共交通に関してどのような考えを持っていらっしゃるのか。以上、３点伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"こちらにつきましては、今検討されております北地区の再開発事業と一部重複している部分となりまして、今後、今も準備組合と協議を進めているところなのですけれども、こちらについてはしっかりと対応してまいりたいと考えているところです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"松永委員","kind":"質問・要望","question":"戸越五丁目の町会会館に関しましては今度３月にお話をされるということで、しっかり丁寧にご説明をしていただいて、その後どういった回答になるか分かりませんが、代替地というか、そういったところも含めて丁寧に相談に乗っていただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"}]},{"id":"topic-02","title":"ボタン電池の回収","agenda":"ボタン電池の回収","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"再商品化とあるのですけれども、ちょっと伺いたいのは、再商品化というのは具体的にどのような感じになっていくのか。行政としてはコストがかかるのだけれども、やはりリサイクルですよという意味でやるのかということとも関わってくるので、事業費というかその辺をお伺いします。ここに書いてあるから絶縁しなくてはいけないものなのでしょうけれども、そこら辺をお伺いします。","respondent":"篠田品川区清掃事務所長","answer":"ただ、なかなかしていただいてる方も少ないですし、現実の問題として、このボタン電池は今も実際には一緒に出ていたりもするので、それを改めて周知を図るという形で考えているところです。","voiceIndex":42,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"原材料になるということでしたけれども、そのままボタン電池の原材料になるということの理解なのか、ちょっと違っていたら後で指摘していただきたいのですけれども、そういうことも含めてその周知ですね。様々行うというご説明でしたけれども、かなりやはりリサイクルとか環境に対する関心が高まっていますので、そういった区民の方々の関心に届くように、ぜひ様々工夫していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"現状、ほかにまたこういう事業を考えているものがまだ何かあるのですか。それと、ボタン電池の回収、２３区ではどのような感じなのでしょうか。ごみの回収のことなので、どこの自治体でも広がっていければ良いとは思いますけれども、２３区清掃一部事務組合での議論とか、要するに品川の状況を広げていけたらなという思いで質問したいのですけれども、それぞれいかがでしょうか。","respondent":"篠田品川区清掃事務所長","answer":"このボタン電池も昨年の特別区制度調査会でご要望いただいたものですから、そういったところで対応を考えているということがあります。区民の方からそういったご意見をいただければ、その都度検討してまいりたいと思っています。","voiceIndex":45,"id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"今回ボタン電池を週１回、資源の日に回収するということです。そこで、今回の変更でボタン電池を資源回収日に回収できるだけでなく、もちろん考慮している点だと思われますが、電池の種類ごとの排出量一覧で分かるようにする周知の工夫についてはどう考えているのか、それについて教えてください。","respondent":"篠田品川区清掃事務所長","answer":"そういった形でリチウムイオン電池等だけは残ってしまった状況があります。ですので、その辺の安全性の確保ができれば、まとめて収集しながら、分け方等もあまり細かくならないような形でできるように、今後は対応していきたいと考えているところです。","voiceIndex":47,"id":"exchange-018"},{"speaker":"ゆきた委員","kind":"確認","question":"現在あるものの一覧表は私も確認させていただきました。さらに分かりやすいように周知を進めていただければと思います。ボタン電池は一時保管後、専門業者へ委託し再商品化。そこで、事前に写真等で比較のイラストを用いた具体的な注意点といったものが、周知にも今後必要になると思いますけれども、改めてお聞きできればと思います。","respondent":"篠田品川区清掃事務所長","answer":"先ほどの私の説明がちょっと行き届かなかった部分があるかもしれません。リチウム電池等を除いた乾電池、それからコイン型電池、それとこのボタン電池、こちらに関しましてはもう一括してお出しいただけるようにしてます。","voiceIndex":49,"id":"exchange-019"}]},{"id":"topic-03","title":"電線共同溝等工事（競馬場通り）の委託変更","agenda":"電線共同溝等工事（競馬場通り）の委託変更","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２番の1)の（２）なのですけれども、働き方改革というのは、具体的にはどういう改革になっているのかというのを伺いたいと思います。","respondent":"森道路課長","answer":"例えば今までは土曜日も工事としては実施をしておりました。働き方改革として、実際に施工期間として、区の工事でもそうですけれども、週休２日制を原則として昨今やっております。先方からもそういった形で進めたいというお話がございまして、今やっているところです。","voiceIndex":55,"id":"exchange-020"}]},{"id":"topic-04","title":"第二戸越幹線整備工事（取水および空気抜き設備等整備）","agenda":"第二戸越幹線整備工事（取水および空気抜き設備等整備）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回の追加工事の取水、マンホールというのは、第二京浜と中原街道の間というか、どちらかというといわゆる上流の部分の工事になると思うのですけれども、今回の第二戸越幹線整備工事により、下流のほうの取水３ですとか取水４ですとか、西品川公園付近の豪雨対応というのも向上するということになるのか伺いたいと思います。よろしくお願いします。","respondent":"関根河川下水道課長","answer":"ただいまご指摘いただきましたとおり、この事業が完成した際には、図の取水３、取水４と記載されているところも含めて、また今回工事で作る取水１、２、合わせてこの４か所から水を取り込む計画になってありますので、今お話をいただいたエリア・区域におきましても。","voiceIndex":61,"id":"exchange-021"},{"speaker":"安藤委員","kind":"意見","question":"大変な工事がこれからも続くと思うのですけれども、安全に気をつけて迅速に工事を完了させることをよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-022"},{"speaker":"ゆきた委員","kind":"質問","question":"今回の工事は当初から令和１０年３月に完了予定ということで、工事の中では様々な予測できないことが出てくることがあり得ると思いますが、この中で出てきている発進位置が変更になるための開口補強を追加、工法変更、試験掘りすることとなるための追加とありますが、当初の工事期間は延長されないのか、延長されないのであれば無理な工事にならないのか。この辺についてお聞きできればと思います。","respondent":"関根河川下水道課長","answer":"もしやはりどうしても予測し得ない何か事象、大きなものが発生した際には、場合により工期の延伸というところも可能性としてはあり得ますけれども、可能な限り現工期の中で完了できるように、かつ安全にというところで施工を進めてまいりたいと考えています。","voiceIndex":64,"id":"exchange-023"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。１点だけ確認ですけれども、大規模工事というのは、こうした不測の事態が起きた場合というのは、あらかじめ工期は余裕を持って設定されているという理解でよろしいでしょうか。","respondent":"関根河川下水道課長","answer":"一定、例えば天候不順による日数を一定の係数をかけて見込むということはありますが、何か不測の事態を想定して、余裕を見て、例えば何日間プラスをしておくといったようなことは、基本的にはございません。","voiceIndex":66,"id":"exchange-024"}]},{"id":"topic-05","title":"しながわ防災区民憲章の制定","agenda":"しながわ防災区民憲章の制定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"パブリックコメントなのですけれども、３６件ということですが、こちらの人数は何人だったのかというのをお伺いしたいです。それで「行動する」の最終文言を変えたということです。それで、３月５日には品川区防災会議があると思うのですけれども、そこに一旦案を出して、そして決定するということで流れとしてはよろしいのか伺いたいと思います。","respondent":"羽鳥防災課長","answer":"パブリックコメントの人数というか、件数は１２件になります。同じ方が回答されている可能性もありますので、１２件ということでお伝えします。","voiceIndex":75,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。本会議の答弁もありました。そういったパブリックコメントでの具体的なこうしたらどうかという意見もそうですし、例えば本会議での答弁を基にするのであれば、前文の「自助・共助」の前に「公助に加え」という区が本会議でも答弁したようなそういった文言を入れるなど、やはりそういった修正というのはぜひしていただきたいのですけれども、どうでしょうか。","respondent":"羽鳥防災課長","answer":"公助についてのご質問です。公助につきましては、減災を進める上で重要であると認識をしています。こちらのしながわ防災区民憲章は区民による憲章ですので、公助の表現という形ではなく、やはりそこは自助と共助の意識を高めるというところで書かせていただきました。","voiceIndex":79,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"パブリックコメントの２９番のところに、防災について自助・共助だけではうまくいかないため、行政をうまく活用するのも区民の務めであると書いてあるのです。ですから、私はやはり区民憲章だから公助はちょっと入れませんというのは、私は違うと思うのです。今まだ案の段階だということなので、そういったことも踏まえて、ぜひ何とか公助の要素を入れていただけないでしょうか。改めて最後に伺います。","respondent":"羽鳥防災課長","answer":"ただ、一番やはり大事だったのは人の意識だったとおっしゃっており、やはりハードとそれぞれ意識の部分、自助・共助の部分、それぞれを高める必要があるということは区としても認識していますので、それぞれ力を高められるように、公助もしっかり取り組むというところで。","voiceIndex":81,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"３月１１日の式典も欠席します。障害者、高齢者、低所得者に自助・共助を求めるというのは間違っています。もちろんどの災害も大事ですけれども、要するにここで言う災害とは何を指しているのか、主要な災害とは何か、そこを伺いたいと思います。２点目ですけれども、品川防災会議にもかけるということですけれども、しながわ防災区民憲章です。議会の議決を求めないのはなぜなのかなと思ったのです。","respondent":"羽鳥防災課長","answer":"一定、丁寧な対応はさせていただいてきたという認識ではあります。今回は議決というプロセスではありませんが、多くの方の意見を聞いて、それを組み立てて防災会議へ諮るということで進めさせていただいていますので、ご理解いただければと思います。","voiceIndex":83,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"議決のことですけれども、ちょっと短かったというのを意外とさらっとお認めになったので、ああ、そうなのだと思って、やはり憲章というときは時間をかけたほうが良いですよ。多くの方の意見を聞くことは大事ですよ。大事だし、私は十分だと思っていませんけれども、もっと時間をかけてやるべきだとは思っていますけれども、やはり議決を経るということ、そこは改めて求めたいと思いますが、いかがでしょうか。","respondent":"羽鳥防災課長","answer":"委員がおっしゃるとおり、この最初の「備える」というところ。災害はいつ起こるか分からない。ここで言う災害は、おっしゃるとおり首都直下地震で、その後の「伝える」というところの過去の災害というところで、私が説明したような過去の災害という表現をしています。","voiceIndex":85,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはりこの内容はもちろんですけれども、決め方についても反対です。しながわ防災区民憲章ですから、やはり区民同士の議論をしっかり保証した機関や仕組み、最終的には議決を経るというプロセスがやはり必要かなと述べておきたいと思います。施政方針ですからぎゅっと縮めて整理されるのは必要なことだと思いますけれども、この区長が聞いた話というのはどういう話だったのか、中身を伺いたいと思います。","respondent":"羽鳥防災課長","answer":"宮古市は、東日本大震災の前に明治と昭和と２回大きな津波の被害を受けていたということがあります。それに応じて防潮堤も整備をして、山の避難路というものも一定整備をされていたということです。ですので、津波に対する公助のところの対応というのは、ある程度進んでいたです。","voiceIndex":87,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"どう逃げるのか。そのためにどういう計画を立てるのか、誰がどう手をつないでいくのか。やはり津波は必須なのですか。地震だ、要するに海面から離れろということですから、それがこの品川で言う首都直下型地震や風水害のしながわ防災区民憲章につながるというところが、何かスタートからして違うのではないかと私は思うのですけれども、違わないと思うのであれば、そこをご説明いただきたいと思います。","respondent":"羽鳥防災課長","answer":"災害対応に必要な自助・共助・公助というのも、災害対応に応じて様々です。災害の種類によって避難の形態は、もちろん異なります。今、区では在宅避難も推奨しています。いずれにいたしましても、首都直下型地震で在宅避難をするためにも、やはり備えが必要です。","voiceIndex":89,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"津波は地震の後ですから、正確に言えば避難のためにも住宅を安全にするということが必要なのだけれども、やはり津波というのはどれだけ高い防潮堤を造っても、逆に日常の生活に不便になるぐらいの要するに海が見えないような防潮堤を造ったら、住んでいる方はどう思うのかという議論を聞いたときに、やはり３０メートルの防潮堤ではなくて、やはり逃げると、そのための計画や訓練をすると。","respondent":"羽鳥防災課長","answer":"こういった内容も、多くの区民の皆様からいただいたご意見で多く使われているワードを抽出して、行動指針のほうも作っているところです。ですので、区民の皆様がそのように意識されているところを、今回、行動指針も併せて表現をしていくということで取り組んでいるところです。","voiceIndex":91,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"すみません、１点だけ。先ほど行動指針の話が出ていたので。ぜひその行動指針を作るにあたっては、案の状態のときに一回建設委員会や議会に報告を入れてほしい。いろいろな大事な部分が行動指針につながってきていると説明が何度もあるので、その行動指針を決めるにあたって、要するに区が意思決定するにあたって、案の状態で建設委員会に報告して質疑を保証していただきたいと思いますが、いかがでしょうか。","respondent":"羽鳥防災課長","answer":"行動指針につきましては日程の関係もありますので、どういった形にするかは調整が必要ですけれど、議会の皆様にご報告するように調整をいたします。","voiceIndex":93,"id":"exchange-033"},{"speaker":"ゆきた委員","kind":"確認","question":"変更点の説明については、今ありましたので、私からは１点のみ確認でお聞きしたいと思います。しながわ防災区民憲章の今後の活用方法について、どういったところで活用されていくのか、この１点だけお願いします。","respondent":"羽鳥防災課長","answer":"今回ご提案させていただいているのは、例えば防災区民組織で町内で安否確認訓練をやるというところがございましたら、そのツールとして、その安否確認タオルをこちらから提供するというようなことを考えて、しながわ防災区民憲章をきっかけに。","voiceIndex":95,"id":"exchange-034"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"在宅避難を推奨とありまして、資料の今後の取組というところにも書いています。伺いたいのは、在宅避難者でも支援物資は受け取れるというルールになっていると思うのですけれども、それをどう周知するのかという点について。私たちは１００％耐震化する計画というのをやはり持つべきだと思っているのですが、そちらを区のほうから都のほうに求めていくというお考えについてはどうなのか伺いたいと思います。","respondent":"遠藤防災体制整備担当課長、関根河川下水道課長","answer":"こちらについても、東京都が在宅避難の方向性を今後示していくといった中で、東京都と連携した形で一定の方向性が示されたところで、避難所運営マニュアル等に記載していくことを検討しております。ですので、直ちに１００％を求めることは考えてございませんが、水道でも下水道でも、それぞれ東京都では対象を拡大をして実施をしてきているところです。","voiceIndex":103,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"避難所の負担も減るということで、こちらについては注視しつつ、ぜひ１００％の耐震化を求めていっていただきたいと思います。区は発災後７２時間は人命救助を最優先とした活動を実施すると。現時点でマンホールトイレというのは、何か所ぐらいの公園に何か所ぐらい配置されていて、そのうちの下水道直結型というのはどれぐらいなのかというのを、急な質問で申し訳ないのですが、分かれば伺いたいと思います。","respondent":"遠藤防災体制整備担当課長、大友公園課長","answer":"私からは、いわゆる避難所の開設までの時間についてご回答します。それにあわせて必要な井戸であったり、電気であったりというのも併せて整備する予定です。現在のマンホールトイレの設置件数なのですけれども、公園内に今現在２１０基設置しています。","voiceIndex":106,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"ＴＫＢ４８なのですが、４８時間以内にトイレ、キッチン、ベッドを整えるというのが人命救助には大変重要だと、災害関連死を防ぐために重要だと提言されているわけですから、現在それを実現する上での障害になっているものというか課題になっているものは何なのかというのを伺ったので、もう一度お願いしたいと思います。それと、キッチンカーのほうに移ります。","respondent":"遠藤防災体制整備担当課長","answer":"その流れ、フローに従って展開することによって、災害時でも速やかな運用ができるということを両者で共通認識を持っているところです。","voiceIndex":109,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"様々あるのですね。なかなかすぐ解決できるのかなという難しい課題もあり、具体的に検討していくと。最後に２つなのですが、段ボールベッド１,０４０台、間仕切り２,６００台ということなのですけれども、これはどういう規模の数なのか今ひとつぴんとこないので、避難所に来る避難者の数に照らしてどうなのかという感じで伺いたいのが１つです。もう一つは生活用水です。","respondent":"遠藤防災体制整備担当課長、羽鳥防災課長","answer":"例えば避難所に一斉に入った場合本当に確保できるのか、全員に配れるのかどうかといったところも、こちらについても今後どのような形で、今後運用をどのようにしていくかということを検討していこうと考えています。主な協力の内容といたしましては２点あります。１点目が、井戸や貯水槽を活用させていただいて、区民に対して給水を行うこと。もう一点が浴場を開放していただいて、罹災者への入浴支援を行うことの２点が協定内容になってあります。","voiceIndex":111,"id":"exchange-038"},{"speaker":"安藤委員","kind":"提案","question":"耐震化についてはまだ未確認ということなのですが、これは部署によっては確認しているかもしれないので、横断的に各部署で連携をしてぜひここは確認していただきたいと思います。そしていざというときに入浴施設として使えるようにするまでが担当部署の頑張りどころというか責任だと私は思うので、ぜひ確認をしていただいて、必要な施策を今後打っていただきたいと要望いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-039"},{"speaker":"中塚委員","kind":"確認","question":"実際の計画どおりに事が運ぶような訓練を見ても、実際に起こり得る被害に対しては、計画も訓練もまだ程遠いなというのが私の認識です。私は食事の質の確保、キッチンカー、そこに絞って伺いたいと思います。方向性が出てきたということですので、今時点で業者に確認できているもの、引き続き協議を続けているもの、簡単に言えば、今、具体的にどういう状況なのか、そこを伺いたいと思います。","respondent":"遠藤防災体制整備担当課長","answer":"委員の質問、２点お答えいたします。１点、キッチンカー団体とどれぐらい協議をしているのかといったところです。発災時の対応フローを作成しまして、品川区、キッチンカー団体、それと実動部隊となるキッチンカーの３者がどのように動けばよいのか。","voiceIndex":115,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"それが、その３者それぞれ手元にあって、日常的にも確認・訓練しているのかということを伺いたいと思います。ぜひその文書があるのだった見せていただきたいのです。以前にも伺ったのですけれども計画上は具体的に何日目ぐらいから避難所に入るのか。１時間にどういうベースで食事を提供していくのか、ここも具体的に落とし込んでいく必要があるかと思いますけれども、それぞれいかがでしょうか。","respondent":"遠藤防災体制整備担当課長","answer":"計画上何日目からキッチンカーが現地に入れるのかといったご質問ですが、能登半島地震の事例でいきますと、遠方から来たキッチンカーが依頼して３日目に入ったというお話をいただいていますので、区としては一番日数がかかるところで３日ということで検討はしております。","voiceIndex":117,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味で見せてほしいという述べました。ぜひこの間の話合いで積み上げてきたものを、多くの人に触れていただいてブラッシュアップできるようにしていただきたいと思いますけれども、いかがでしょうか。つまりホームページ上でやっていただきたいと思うのですが、いかがでしょうか。そういうメニューの協議も引き続き必要ではないかと思うのですけれども、いかがでしょうか。","respondent":"遠藤防災体制整備担当課長","answer":"１００食から２００食出せるようなメニューを開発できるかといった点につきましては、こちらについても引き続き事業者のほうと協議を重ねて、どのようなメニューが提供できるのかといったところも検討していきたいと考えています。","voiceIndex":119,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"様々協議が始まり、具体的に決められ、引き続き協議をしているところもありますけれども、一定程度まとまった時点で整理してホームページにアップしていただきたい。もちろん大前提として、どういう被害が起きるのか、それを防ぐためには何が必要なのかというのはもちろん大前提ですけれども、ぜひ引き続きそういう姿勢で改善・改良していただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-043"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、在宅避難について改めてお聞きしたいと思います。一斉防災訓練を継続しつつも、在宅避難を推奨していくマンションとか集合住宅、マンションでの区民組織において、同時期にマンション防災訓練を行っていくということを今後考えていく必要があると思いますが、この辺についてお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"そういった中で、マンションごとに防災のマニュアルを作成して、それを「東京とどまるマンション」の登録までつなげて、そうすることによって、また東京都からの支援も受けられるような良い循環が回りますので、そういった取組は来年度以降も注力していきたいと考えています。","voiceIndex":122,"id":"exchange-044"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ここについては、今後またさらに深掘りしていければと思っています。議会・行政側での在宅避難についての認識と、あと地域住民と区民からの在宅避難の認識について、本当に温度感に違いがあります。在宅避難の必要性については、さらに周知を行うとともに慎重に進めていただければと思います。今回は要望で終わりたいと思います。","respondent":"大友公園課長","answer":"先ほどの安藤委員からのご質問で、マンホールトイレの数と、その下水道直結の件についてお話しいただいていたのですけれども、数が一定分かりまして、先ほど２１０基とお答えさせていただいたところ。","voiceIndex":124,"id":"exchange-045"}]},{"id":"topic-07","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"質問したいのは、現在、品川区ですとか、あるいは２３区区長会などでどのような検討が行われているのか。私としてはこの物価高ではそれと負担増の施策については言えないと思っていますので、区として反対などの意見を述べるべきだと思うのですけれども、いかがでしょうか。","respondent":"篠田品川区清掃事務所長","answer":"したがいまして、ごみの有料化という話になりますと、この２３区一体でまず検討が必要になるだろうと私どもも認識しておりますけれども、現在２３区として、このごみの有料化について具体的な検討を進めているという状況にはございません。","voiceIndex":128,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。そうですね。何よりも、やはり今これだけの物価高です。ですから非常に良い答弁なのではないかと思うのですが、ぜひ最後、２３区区長会でやはりこのごみの有料化についてはやるべきではないと区長から意見を言っていただきたいのですけれども、区長はいないのですけれども、そういう体制に区としてやはり考え持つべきだと思うのですけれども、それについてはご意見はいかがでしょうか。","respondent":"篠田品川区清掃事務所長","answer":"ごみの有料化に関しての区としての意見表明ですけれども、いずれにしても今現時点でそういった形での検討の場があるわけではないので、なかなか意見表明というのは難しいかと思いますけれども、ただ、いずれにしましても区としましては先ほど委員からのお話もあったとおり、当然。","voiceIndex":131,"id":"exchange-047"},{"speaker":"中塚委員","kind":"確認","question":"先ほど説明の中で２３区がごみの収集、一部事務組合が焼却、東京都が最終処分場のような説明がありました。区の職員の方に伺っても分からないのだけれども、つまり東京都知事は、ごみの有料化など、そのような権限はあるのですか。意見を表明するのはもちろんある意味自由かと思うのだけれども、自分の権限ではないだろうと報道を聞いていたのですけれども、ちょっとご意見・ご説明を伺いたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"最初の分業体制について改めてご説明いたします。平成１２年までは東京都が全部一体化してやっていました。それが移管をされまして、各区では家庭ごみの収集と運搬、運搬というのは清掃工場までの運搬を担うということになっております。","voiceIndex":133,"id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"分かりました。生ごみの水切りをどこまで徹底できるのか。私もマンションですから、どこに何を捨てるかというのは全部定められていて、分別は私も一生懸命やるのですけれども、いわゆるそもそもごみの総量を各家庭で減らす努力を、ごみ減量審議会の意見をしっかり力にしながら、引き続きごみの減量を進めていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-049"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"しながわ防災区民憲章の解説版ということなのでしょうか。まだ案の状態ですけれども、しながわ防災区民憲章はしながわ防災区民憲章で、この行動指針との序列、どういう関係の位置づけなのか、これを１点伺いたいと思います。裏側に、挨拶よる小さなつながりをさらに深めてと、そのとおりなのだけれども、町会・自治会に限定することはないのではないかと思うのですけれども、それぞれいかがでしょうか。","respondent":"羽鳥防災課長","answer":"あえてここで行動指針と示するのは、やはり町会・自治会の活動に対して、なかなか参加する機会、きっかけづくりというところのハードルがまだまだあるのかなというところを課題として認識してございましたので、ここは防災訓練という防災という分野だけではなくて。","voiceIndex":144,"id":"exchange-050","title":"町会・自治会支援"},{"speaker":"中塚委員","kind":"質問","question":"例えば防災訓練一つ取っても、私もマンションで防災訓練をやりましたけれども、やはりマンションですから、区分所有でみんなと同じ屋根の下にいるわけだから、やはり防災訓練は必要だろうということ、交流も必要だろうということで管理でやろうということでやったことはありましたけれども、何か町会・自治会に限定しなくて、今ある地域の様々なつながりを大事にしてこそ。","respondent":"羽鳥防災課長","answer":"挨拶するという表現自体が、もう様々なつながりを包含した表現だと認識しています。","voiceIndex":146,"id":"exchange-051","title":"町会・自治会支援"},{"speaker":"安藤委員","kind":"質問","question":"今のやり取りの中では、例えば防災訓練など町会・自治会の活動に参加するなどということです。ごめんなさい、この行動指針の位置づけについて説明があったのですけれども、先ほどしながわ防災区民憲章のほうでもこの使い方はどうするのですかという質疑もありましたが、この行動指針のほうはどのように使われるのかというのはもう少し伺いたいと思います。","respondent":"羽鳥防災課長","answer":"今後しながわ防災区民憲章を掲示する冊子等ございましたら、行動指針のほうも分量にも調整が必要かと思いますけれど、なるべく行動指針があったほうが、具体的にどういう動きをしたほうが良いのかというのが区民の皆さんには分かりやすいと思いますので。","voiceIndex":148,"id":"exchange-052","title":"町会・自治会支援"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7325#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":63985,"voices":152}},{"id":"r08-20260225-9","meetingId":"r08-1t","date":"2026年2月25日","dateIso":"2026-02-25","committee":"文教委員会","time":"午前１０時００分～午後 ２時０８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年度品川区教育委員会事務事業の点検および評価の報告書","agenda":"令和７年度品川区教育委員会事務事業の点検および評価の報告書","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"修学旅行費無償化事業が総合評価でＣ、あと給食運営もＣとなっていますけれども、その理由、背景を伺います。今後の取組については、手法等の改善をしていくということで、どういったことをやっていくのか、今、考えられていることを伺います。","respondent":"石井学務課長、新井特別支援教育担当課長","answer":"私から修学旅行無償化事業および給食運営についてお答え申し上げます。修学旅行無償化事業につきましては、令和７年度の実施に当たって、まず既に保護者から積み立てていただいたお金がありますので、それを返金する。私からはシート５番の発達障害教育支援員の配置の具体的な効果についてご説明いたします。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"別のところで、いじめ防止対策はＣですけれども、その理由を伺います。実際、今後、どういった形で進めていくのかを伺います。それと、中学校でのボランティアの受入れが小学校に比べて減るということで、全国的にそういう傾向があると書かれて、ここも課題とも言われているのですが、区として実際、現状がどうなっているのか、この課題についてどう対応されていくのかを伺えればと思います。","respondent":"丸谷教育総合支援センター長、三ツ橋品川図書館長","answer":"学校配置にすることで、より早期に児童・生徒の課題の発見と解決に向けた取組がスムーズに円滑にいくだろうということで、次年度、計画してまいります。学校ボランティアの育成ですけれども、学校ボランティアはボランティア養成講座を実施しておりまして、学校ボランティアをしたい方を募りまして、例えばこちらは小学校や中学校の卒業生のＰＴＡの方が対応していただいて。","voiceIndex":8,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"いじめ防止対策は、スクールソーシャルワーカーですとかスクールカウンセラーを各校に配置をしたということで、そこで早期に情報をキャッチして、即発見して、ＨＥＡＲＴＳにつなげていくということの、今後どう時間的に早めていこうというフローをお聞きしたいと思います。何かあれば伺いたいと思います。","respondent":"丸谷教育総合支援センター長、三ツ橋品川図書館長","answer":"ＨＥＡＲＴＳにつなげるというよりは、学校に配置しているスクールカウンセラーやスクールソーシャルワーカーが、直接学校と協議しながら対応していくといった体制を考えているものです。委員のご要望につきましては、やはり区といたしましても図書館司書は学校図書館運営にも必要だと考えていますので、引き続きボランティアを工夫しながら、また週３日になれるように工夫しながら対応していきたいと思います。","voiceIndex":11,"id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"修学旅行無償化事業ですけれども、１人当たりの金額をもう１回確認したいです。それとこういった物価が上がっていく中で、今年度の金額から今後の１人当たりの無償の金額をどうしていくのかというところが１つ。当然、非常に予算がかかることですけれども、今、１５学級以上が２人です。それについて、学級だけではなく、ほかの要素も出てくると思うのですが、配置の増員についていかがでしょうか。","respondent":"石井学務課長、新井特別支援教育担当課長、酒川指導課長、三ツ橋品川図書館長","answer":"今後、物価高騰への対応につきましては、もちろんそういったことも含めてやっていかなければならないので。委員、ご指摘のとおり、今年度から２名配置になった学校については。品川学園ではＧＴＥＣ ｊｕｎｉｏｒという技能面を測る試験に子どもたちは取り組んでおりますので。中学校の蔵書の整備ですけれども、なかなか中学校は蔵書に関しては難しい部分がありますが、こちらの学識経験者のコメントに書いてありますように。","voiceIndex":16,"id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"発達障害教育支援員は拡大を検討ということですから、令和８年度は予算の話ですけれども、なかなか現状、令和７年度と変わらない認識でよろしいのでしょうかというのが１つ。品川オンライン英会話レッスンもやはり経年変化を見てということですから、令和８年度は品川学園だけなのか、予算書をしっかり見てなくて申し訳ないのですけれども、まだ品川学園だけになってしまうのでしょうか。","respondent":"三ツ橋品川図書館長、酒川指導課長、新井特別支援教育担当課長","answer":"委員のご指摘にありますように、やはり書物を読む、また、いろいろ調べるというのはすごく大事だと考えていますので。品川オンライン英会話レッスンについては、令和８年度も品川学園１校です。やはり、今後、ニーズの高い事業だと考えておりまして、こちらは拡充の方向で、また予算要求は検討していきたいと考えています。","voiceIndex":21,"id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"意見","question":"最後、１つだけ。人材派遣なので、直接、学校の管理職が、発達障害教育支援員にいろいろ話ができないことがあって、そこのところの指導上のやり方については、どう配慮されていらっしゃいますか。","respondent":"新井特別支援教育担当課長","answer":"答弁漏れでございまして、基本的には校長が人材派遣の支援員に対してこの児童に支援をしてほしいといった指示ができるような形になってあります。","voiceIndex":25,"id":"exchange-006"},{"speaker":"まつざわ委員","kind":"質問","question":"７万５,０００円という金額のお話がありましたけれども、もっとお金を入れてもいい学びをしてほしいとか、何かそういった地域からこうやって子どもたちの修学旅行に関してもけちることなく学びを進めてほしいと言わせるような取組をぜひしてほしいのが１個です。この貸出し冊数の減少をどう考えたらよいか教えてください。","respondent":"石井学務課長、三ツ橋品川図書館長","answer":"どのような形でできるかについては、まだこれからだとは思いますけれども、その重要性については受け止めてまいりたいと考えています。そのほか、ブックフェアなども実施して、何とか図書離れを防ごうと考えております。こちら、閉館時間というのは、特に問題にはなっていないと捉えております。","voiceIndex":27,"id":"exchange-007"},{"speaker":"横山委員","kind":"確認","question":"ＨＥＡＲＴＳについてお伺いしたいのですけれども、私がうまく理解ができなかったので確認なのですが、ＨＥＡＲＴＳに専門家の方がいらっしゃって、また学校にもスクールカウンセラーであったり、スクールソーシャルワーカーであったりが配置されて、ＨＥＡＲＴＳとの関係性、どういった形で連携をしたり、学校との関係性を深めていったりするのかを、少し詳細を確認させていただけたらと思いますので。","respondent":"丸谷教育総合支援センター長、酒川指導課長","answer":"ですので、今のＨＥＡＲＴＳとは大きく形を変えて、次年度からは学校の中で、より円滑に早期に対応できる体制づくりを１年かけて整えていくというイメージでおります。それから令和４年度になりまして、９年生で実施。それから令和６年度に７年生も追加し、８年生、９年生、７年生と広げてきたものが今、６年生の１校で実施されているという経過です。","voiceIndex":31,"id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"ＨＥＡＲＴＳですけれども、この１年間をかけていろいろ整えていくということで、今、ＨＥＡＲＴＳ所属の専門家の方々が学校に行くという理解でよろしいでしょうか。学校の所属になるのではなくて、ＨＥＡＲＴＳ所属で、学校に日常的には通っていくといったイメージでしょうか。品川オンライン英会話レッスンの経過もありがとうございました。小学校６年生のところで拡大していっていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"保護者も含めて、様々、児童・生徒が支援対象になりますので、そのケースによって、学校の窓口になる方が、管理職は当然ですけれども、例えば養護教諭になったりとか、担任、学年主任になったりということで、変わっていくと考えています。","voiceIndex":34,"id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"２８ページの学校図書館ボランティアの育成と活動の支援ですけれども、現在の学校図書館ボランティアは地域の方、学校によってもまた変わってくると思うのですけれども、地域で図書に関わっていらっしゃる方ですとか、保護者のボランティアですとかになると思うのですけれども、どういった方が関わっていらっしゃるのか、割合、少し詳細、現状を教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長、酒川指導課長、三ツ橋品川図書館長","answer":"学校との連携ですけれども、現時点でもＨＥＡＲＴＳが関わっているケースについては、学校管理職とは連携を密にとりながら対応しております。それから指導したいという顧問教員。これで品川区立学校の部活動を１００％充足するといった考えです。学校図書館ボランティアですけれども、ＰＴＡの方が中心となっているものでございまして。","voiceIndex":36,"id":"exchange-010"},{"speaker":"横山委員","kind":"質問・要望","question":"学校図書館ボランティアにつきましては、ＰＴＡが中心となって行っているということで、今、お話があったのですけれども、例えば今後の話ですが、大学生の方とか、学芸員とかを希望されているような方がもしかすると近くでボランティアだったり、社会的な何か活動を希望されているような若者であったり、子どもたちに近い年齢の方がいるかもと思いますので、ぜひＰＴＡだけではなくて、さらに地域。","respondent":"三ツ橋品川図書館長","answer":"学校図書館ボランティアですけれども、主にＰＴＡの方、または小学校、中学校を卒業されたＰＴＡの方が主ですが、広く募集はしていまして、今後も工夫していきたいと考えています。","voiceIndex":40,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"先ほどいじめ防止対策について、ＨＥＡＲＴＳと学校現場のカウンセラー、ソーシャルワーカーとの関係性とか、今後はＨＥＡＲＴＳで抱えているものを、いわゆる現場にというお話がありましたけれども、そこら辺のお話はこの事業評価シートからは読み取れないのですけれども、これはどういう議論の経過なのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"現在、ＨＥＡＲＴＳが関わっている事案が複雑化していく中で、なかなか解決が難しい、要するにＨＥＡＲＴＳが関わる時点で、もう解決が難しくなっているということがありましたので、手法は見直すべきとして、学校配置型を検討するということで。","voiceIndex":43,"id":"exchange-012"},{"speaker":"若林委員","kind":"確認","question":"教育委員会での議論は非常に闊達で、なかなか読み取れない部分も私はあったのですが、この教育委員からの意見は、そういう踏み込んだ形はあの中で議論されたのか、一定の説明があったのか。教育委員の皆様はそこをどのように今、認識をして、また理解をしているのか、していないのか、経過を少し確認したいです。","respondent":"丸谷教育総合支援センター長","answer":"教育委員からの意見の最後の部分になりますけれども、より身近に感じられる仕組みづくりをしていただきたいとご意見をいただきまして、学校配置型にしていくという説明を先日も差し上げております。","voiceIndex":45,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"１日の教育委員会の議論の中で非常に大きく変わっていったという印象を受けました。教育委員の皆さんには、敬意を表したいと思います。経年、分からないのですけれども、Ｄ評価、廃止が、今回はない。それはなぜかという質問と、過去、この事務事業評価シートの中で、Ｄ評価のものは傾向性としてあるとか、ないとか、もし分かれば教えてください。","respondent":"舩木庶務課長","answer":"少し具体的なものがないのですけれども、私が認識している中ではＤ評価、完全に事業そのものを廃止していることはここ数年ではないと認識しておりまして、その背景といたしましては、やはりその事業のあり方、より教育現場ですとか。","voiceIndex":47,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"そうすると、Ｄ評価とここにあるのは、そもそももう無駄な評価にもなりかねない。この辺、今後、毎年これをやられて、評価が義務づけられていますので、１回参考に少しお聞きしたいと思います。","respondent":"舩木庶務課長","answer":"実は、本年度、この品川区教育委員会の事務事業評価の実施要領を教育委員会でお諮りをして、改正をしておりまして、昨年までは基本評価についてもＡからＤの評価をし、そして総合評価についてもＡからＤの評価をする仕組みでやっていたのですけれども、そうしますと。","voiceIndex":49,"id":"exchange-015"}]},{"id":"topic-02","title":"学校プール施設のあり方","agenda":"学校プール施設のあり方","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"改築がもう済んでいるところもありますけれども、そうしたところでは、優先順位をつけてということですけれども、基本的にはシェードを設置していくことでいいのか確認させていただきたい。日除けシェードを設置していくときにかかる金額はどのくらいになるのでしょうか。その中で、今、源氏前小学校はまだ調整中で、現在の状況と何か課題になっていることがあれば伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"大きく３点、ご質問いただきました。１点目の改築済みの学校および既存校の今後の改修の対応方針ですが、改修に当たっては日除けシェードを設置していく考えです。","voiceIndex":56,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、設計段階で盛り込もうとした場合は、どのくらいかかるのか分かれば伺います。源氏前小学校は、今、伊藤学園との調整中ということで、一番近いのが伊藤学園なのですか。８００ｍ圏内からはなかなか離れているので、いろいろ安全性とか考慮して、調整は進めていただきたいと思うのですが、荏原文化センターとかを利用できるとも思ったのですが、そうしたことは検討したのか伺います。","respondent":"荒木学校施設担当課長","answer":"２点目の源氏前小学校の共同利用の利用先ですが、学校でもやはり幾つか施設を当たっていただきまして、どうしても荏原文化センターですと、日中、民間の団体、個人の利用もあるので、まずは学校間、伊藤学園で今、円滑に調整が進んでおりますので。","voiceIndex":58,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ子どもたちがプールの授業、水泳授業をしっかりできるように、今後も様々、取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-018"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"やはり平置プールから最優先にやってほしいというのがあります。空調設備を備えた屋内スペースですけれども、これは多分、見学者の話です。これも確かに私も見ていて、ずっと外で日陰でもいるのはしんどいと思ったのです。それを設置するスペースをあの中に見つけるのはなかなか酷と思うので、どういった感覚でこういうお話があるのかを教えていただきたい。少し教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-019"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"温かくなるものです。だからこそ、日除けシェードは改築をなかなかやらない学校は、やはり少しやってほしいと今以上に思いました。スポーツクラブも、先ほどの伊藤学園の話も結局はバスを使って、やはり人件費がかかるわけですから、人件費、バス代ではなくて、やはり歩いて行ける施設もあると思うのです。だからそこら辺は要望で、いろいろ子どもにいいものを考えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"確認","question":"資料の後ろの詳しいところには、今後、改築する場合、集約化の中で、小学校にはプールはつくらないとあったのですが、現状、浅間台小学校までは計画があるのですけれども、それ以降には、集約化の予定でない、中学校を中心にという内容だったとあるので、そこの確認です。","respondent":"荒木学校施設担当課長","answer":"さらには屋内プール設置の場合は敷地の中を大分、圧迫してしまいますので、そういったことからも、やはり今後も各学校に整備して、各学校で水泳授業を実施してもらう考えで進めてまいります。","voiceIndex":69,"id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"意見","question":"小学校のプールについては、私の認識が少し違ったのですみません。屋外プールを原則としてというお話です。鈴ケ森小学校の件については、学校間の調整、話合いを教育委員会として支援していただけるということで、学校それぞれの事情があるので、今、お話があったように、学校間でうまくやっていくところを、今回はバスですけれども、支援していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-022"},{"speaker":"筒井副委員長","kind":"確認","question":"プール共同利用についてですけれども、もう既に出ていた話かもしれないですが、確認として少しお聞きしたいと思います。例えば共同利用で、城南第二小学校の生徒が品川学園で水泳の授業をやるということですけれども、これは城南第二小学校の生徒と品川学園の生徒合同で授業をやるのですか。","respondent":"荒木学校施設担当課長","answer":"城南第二小学校につきましては、４月下旬から５月の中旬ぐらいまでにかけまして、品川学園の中で利用できる時間、枠を確保して、城南第二小学校単独でその時間は授業を実施する計画で今、検討しております。","voiceIndex":73,"id":"exchange-023"},{"speaker":"筒井副委員長","kind":"質問","question":"各学校単独で授業をそれぞれ行っていくと理解しました。では品川学園の時期は何月になるのですか。","respondent":"荒木学校施設担当課長","answer":"品川学園に関しましても、当然１年中、プール授業ができる温水プールの環境ですが、やはりコアの期間として、夏場から秋ぐらいにかけてということで伺っております。","voiceIndex":75,"id":"exchange-024"},{"speaker":"筒井副委員長","kind":"質問","question":"やはり移動と準備を合わせて、行き帰りで１時間ぐらい、結構時間を取られると思いますけれども、その時間を消費する分、何か普通の授業に影響はあるのでしょうか。その影響があるのでしたら、それを補完するような対策、対応はどのようにお考えでしょうか。","respondent":"荒木学校施設担当課長","answer":"特に今、副委員長ご指摘の移動時間が課題と認識しております。","voiceIndex":77,"id":"exchange-025"}]},{"id":"topic-03","title":"学校改築の進捗","agenda":"学校改築の進捗","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"改築困難校について、今後、いろいろ検討していくということですけれども、３つの視点の中で５つ検討項目が出されていて、どういった手法が考えられるか現時点の状況を伺います。新校舎基本プランは、校舎規模の適正化をしていくというところと、仮設校舎用地の検討と、工事発注方法の検討で、今後、どういったことが考えられるかを伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"このため、学校敷地内での対応に加えまして、学校敷地以外の公有地の活用可能性についても視野に入れて、各関係と連携しながら、実現性があるものについて用地確保が可能か検討を進めてまいりたいと考えています。","voiceIndex":84,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"仮設校舎用地はあるのかというのが少しあるのですけれども、今、考えられるところ、もしあれば伺います。三木小学校は、いろいろな意見が出されているということで、全部、木造校舎にするという意見といったことも出されているそうなので、地域の意見をしっかりと聞いていただいて進めていただきたいと思いますけれども、いかがでしょうか。","respondent":"荒木学校施設担当課長","answer":"２点目の仮設校舎の用地ですが、こちらにつきましては、本当に来年度の基本構想策定の中で様々、検討してまいりたいと考えています。","voiceIndex":86,"id":"exchange-027"},{"speaker":"まつざわ委員","kind":"意見","question":"こういう資料は、世に出てしまうと、もうやってほしい地域はもうやるのだとなったときに、それが外れてしまうと、それはそれで大変ショックなことがあるので、そこら辺は期待感をあまり、持つのは自分たちの勝手で、勝手に持ってしまうこともあるのですけれども、慎重にこういう情報の間違いがないようなやり方をやってほしいと思っています。もう１個、１２年。１１年、延びて１２年、もう大分です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"地域の方々からの強い要望がこういう俎上に上がったということで、区で検討に入った。私もそういうものに詳しくないのであれですが、そういう発想はこの検討の中で、高さ制限とかあるのかもしれませんけれどもそういうご意見、区の検討の中では出てきたのかお伺いします。どうすれば短くなるのかは私も非常に難しくて、専門的で分からないので、そういうご意見があったので、それはいかがですか。","respondent":"荒木学校施設担当課長","answer":"１点目の情報発信の仕方、説明の仕方は今後も留意して進めてまいります。２点目の委員のご提案に関しましては、恐らく大崎中学校の敷地に施設一体型の何か学校をつくるご提案と認識しています。","voiceIndex":94,"id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"提案","question":"私が提案したのではなくて、地域の方でそういうお声があったので、そういうのも１つの方法だと思うので、ぜひ専門的な見地から検討していただければと思います。それは小中一貫校であっても、そうではなく、施設は一体だけれども、同じ敷地に学校があるという形は、そういう俎上に載ったときに考えればいいことで、それは後で２つの老朽化した学校をいかに早く改築できるかという方法をぜひ考えてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-030"},{"speaker":"横山委員","kind":"確認","question":"中学生には自転車利用であるとか、身軽なバッグを使うやり方を選択されている他の自治体もあると思うのですけれども、品川区の場合は、あくまでも令和８年度は三木小学校と大崎中学校のみを対象とした検討になるのか、また、それ以外の改築困難校も含めた形で広く検討されていくのか、その辺りを確認させてください。","respondent":"荒木学校施設担当課長","answer":"一方で、委員のご提案の渋谷区の事例にありましたような仮設校舎の共同利用などにつきましては、もし可能であれば、この２校に限らずいろいろな学校でできる可能性もありますので、そういったことは２校だけでなくて、ほかの学校改築にも活用できるように。","voiceIndex":98,"id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"もちろん、あくまでも対象は今回は２校ですけれども、様々、未来を見越した上で、モデル実施しているほかの事業や様々なこと、未来のことを含めた形で捉えて、検討を進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-032"},{"speaker":"若林委員","kind":"質問・要望","question":"引き続き、よろしくお願いします。何点か確認と要望という形でお願いします。来年度、基本構想をつくられて、そこからいつから設計をして、で、そうするといつまでにいわゆる校舎の解体・改築が終わるというのが見えてくると思うのですが、三木小学校と大崎中学校の竣工の目標、目安は、まずどこら辺に置いているか教えていただけますか。","respondent":"荒木学校施設担当課長","answer":"ただ、その上で仮にこの２校になった場合に関しましては、今、お示ししている約１０年超の工事期間を可能な限り短縮していきたいと思ってありますので、まだ明確に具体的な数値は申し上げることはできないのですけれども、目標感としては、１１年をできる限り短縮して。","voiceIndex":102,"id":"exchange-033"},{"speaker":"若林委員","kind":"質問・要望","question":"今日、ある程度、現段階では一定のまとまった数字とか、いろいろなグラフとか図とか出てきましたので、去年、地元の町会の方々が品川区にこの件に関して直接要望した経緯もありましたので、そうすると、それに対するアンサー、早速、地元の町会等の方々に、今のこの三木小学校と大崎中学校の教育委員会の考えていらっしゃることを速やかにご報告する。","respondent":"荒木学校施設担当課長","answer":"２点目の地元への説明ですが、こちらに関しましても、検討がまとまって最後に報告するのではなくて、当然こちら、令和７年度にも検討している状況ですので、この令和７年度の検討内容と、来年度、令和８年度の基本構想の策定に係る検討につきましても、随時。","voiceIndex":104,"id":"exchange-034"}]},{"id":"topic-04","title":"令和８年度新入学、学校選択の希望申請理由に関する調査結果","agenda":"令和８年度新入学、学校選択の希望申請理由に関する調査結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の調査結果の区の受け止めを伺います。これを学校運営の改善につなげていく、どう活かされていくのかを伺いたいと思います。選択理由の中で、学校の教育活動に魅力があるというのが上位になっていますけれども、これはどういう教育活動なのか、伺います。","respondent":"石井学務課長","answer":"調査結果の受け止めですけれども、アンケートを電子申請にしてから若干、回答率が落ち込んでいる中で、一つ一つ工夫を重ねながら、回答率が少しずつ向上しています。","voiceIndex":113,"id":"exchange-035"},{"speaker":"まつざわ委員","kind":"質問","question":"今、回答率の合計が１５.７％で少し高くなったのですか。","respondent":"石井学務課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-036"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"高くなったといっても、１５.７％なので、やはり努力されても少し低い。調査の中で選ばれた理由や選ばれなかった理由で、例えばこれを学校で校区教育協働委員会とかで、こういった課題を持ち出して、地域と一緒にキーパーソンの方がＰＤＣＡサイクルを回すような取組があるのか教えてください。","respondent":"石井学務課長","answer":"このアンケートはあくまでも全体の傾向性でこういう視点を持っている方々がいらっしゃるということを学校に提供するものですけれども、当然、各学校においては、そういった全体の傾向を押さえつつも固有の課題を恐らく各校長はご存じだと考えています。","voiceIndex":118,"id":"exchange-037"},{"speaker":"まつざわ委員","kind":"確認","question":"逆に分散してしまうことも考えられると思っているので、そういった教育委員会としても、新しい学校、新しくない学校、そこら辺の分析はどうしていくのか。やっていただいていますけれども、やはり改修がなかなか進まない学校には、学ぶ格差ができないように、新しい教材とか、電子黒板も含めてですが、そういった配慮がされていると思いますが、そこの確認をさせてください。","respondent":"石井学務課長","answer":"教育委員会としても、各校、例えば先ほどの議論にございましたとおり、どうしても改築困難校といったこともありますので、そういったところで、教育の格差ができないよう、きちんと全校が魅力ある教育に取り組めるようなバックアップをしていきたいと考えております。","voiceIndex":120,"id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問","question":"保護者の方のアンケートの回答については理解いたしました。小学校５校ぐらいで２０人ぐらいです。中学校は全校で入れたのですが、もし今、数字が分かっていれば、兄弟で、もう小学校などはほぼ決まって、中学校も私立受験が終わったので分かると思うのですが、現状で分かっている範囲の、兄弟枠での待機した方が入れなかった現状についての分析はいかがでしょうか。","respondent":"石井学務課長","answer":"具体的な細かい数字につきましては、現在、手元にございませんので、回答については差し控えしますけれども、やはり例年同様、兄弟枠でも入れない方がいらっしゃることは課題として受け止めております。","voiceIndex":123,"id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"課題として受け止めてるということなので、１００％は難しいかもしれませんけれども、９９％の可能性としてきちんと希望する兄弟枠については何らかの現状を少し変えるような方法を考えていただきたいと思います。やはり、ご兄弟で一緒の学区に通いたいというご希望は強いものがあるので、それを実現させてあげたいと思いますので、ぜひお願いします。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-040"},{"speaker":"筒井副委員長","kind":"質問","question":"インフルエンザが再び増加傾向という報道もなされておりますけれども、インフルエンザの型はＡ型、Ｂ型、いろいろあると思うのですけれども、小学校、中学校、義務教育学校では、インフルエンザは何型が多い傾向なのかと、区立幼稚園・保育園については、Ａ型、Ｂ型、どちらが多いのか、インフルエンザの傾向を少し教えてください。","respondent":"石井学務課長、染谷保育施設運営課長","answer":"東京都が発表している資料によりますと、今年度につきましては、Ａ型の中のＡＨ３、Ａ香港型が非常に割合として９割程度のデータであると言われております。幼稚園・保育園におきましても、型についての傾向は数字として持っているものでありませんけれども、やはり全体の流行の傾向として、通常、春先にかけてＢ型が流行するのが前倒しになって今、流行している状況が。","voiceIndex":132,"id":"exchange-041"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"インフルエンザについては、Ａ型にかかって治療したからといって、また今度、Ｂ型にかかるおそれもあるので、ぜひ、引き続き予防の呼びかけを行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-042"}]},{"id":"topic-05","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今年度、１２件目で、本当にいろいろ子どもたちが差別にさらされている結果と受け止めております。今、区でもいろいろ予防プログラムなどをやっていると思うのですけれども、この予防プログラムは全校で実施しているのかを伺いたいのと、あといじめが起きた後の対策がきちんとできているのか伺いたいです。実際、今、どういった取組をされているのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"子どもたちに対しては、年３回のいじめ予防授業を実施する中で、いじめの定義を学ぶとともに、学校風土をどうよくしていくかを子どもたち自身が考える授業となっておりまして、年に１回は学校で公開日を設けて、一部の学年でも、広く周知してくださいということで。","voiceIndex":141,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"プログラムは全校、全学年でやっているということです。やはり、子どもがいじめを受けていたとなれば、保護者も心配するでしょうし、そうした対応とかも出てくる中で、１人だけではなかなか対応も大変になると思いますので、集団的に対応していただきたいと思いますが、今、具体的に各校でどう全校でやっているか伺います。その対応、各学校はもちろん、職員とかで共有して、交流する場はあるのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"学校いじめ対策委員会の中で、学校管理職を中心にして、当該児童・生徒の担任であったり、主任であったり、生活指導、担当の教員、スクールカウンセラー、こうしたメンバーで対応策を考えて支援・指導に当たっていくのが原則であります。","voiceIndex":143,"id":"exchange-044"},{"speaker":"のだて委員","kind":"意見","question":"学校がチームで対応するのが原則だということで、ぜひ、そうしたことを見つけた教員の人が、教員だけではないかもしれませんが、しっかりチームに相談できるような相談しやすい環境もつくっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":145,"id":"exchange-045"}]},{"id":"topic-06","title":"令和７年度市民科検討委員会報告","agenda":"令和７年度市民科検討委員会報告","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この検討委員会は既に３回やられた中でどういった意見や議論があったのかを伺いたい。やはりきちんと子どもたちが考えていく、そうした授業にしていただきたいと思うのですけれども、いかがでしょうか。今回、品川区が子どもの権利条例の策定をすることも出されましたけれども、こうした子どもの権利条約を学んでいくのも、１つ重要だと思うのですが、いかがでしょうか。","respondent":"唐澤教育施策推進担当課長","answer":"最後の子どもの権利条約に関する学習内容の件ですけれども、現在も市民科の教科書の中で取り扱っていますが、学習内容は、今後、検討委員会の中でも、実際進めていくような形で認識しております。","voiceIndex":151,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"画一的な授業にならないように、そこから脱却していくということですので、ぜひ、やはり自分で考えることができる子どもたちを育てていただきたいと思います。子どもの権利条約については、取り扱っているということで、ぜひ、今回、つくるに当たっても、子どもたちが知らないのが１つ大きな課題だと思いますので、ぜひ位置づけていただいて、子どもたちが学べるようにしていただきたいと、要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問","question":"だから、市民科はこういう授業です、そのうちの今回はこういうことをやっているのです、こことここを目指しているみたいな、教員ではない保護者が圧倒的に多いわけで、もう少し分かりやすくすると、普通の算数とかは理解をしやすいのですけれども、そういうのが理解できれば、それで、いじめのプログラムみたいなものを今、こうやっているとか、例えばできると思うのですが、指導案なども必要ですけれども。","respondent":"唐澤教育施策推進担当課長","answer":"児童・生徒、教員の調査からも、こうした指導書、教科書については、一定の好意的な意見もありますので、ここも踏まえながら検討を進めてまいればと考えています。","voiceIndex":155,"id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問","question":"指導案プラス保護者向けの何か。学校の工夫になるので、少し負担感が出てくるかもしれませんが、簡単でいいので、見どころをつくっていただけるとありがたいと思います。それから評価については、市民科をやっているので、品川区の場合、通知表と指導要録と違うわけです。評価のところだけ、お願いします。","respondent":"唐澤教育施策推進担当課長","answer":"指導要録につきましては、現在、通知表で登録しているものをそのまま移せる形にはなっていますので、改訂に向けても、そういったことがスムーズにできるように考えていければと考えています。","voiceIndex":157,"id":"exchange-049"}]},{"id":"topic-07","title":"南品川児童センターの休館","agenda":"南品川児童センターの休館","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"休館期間が３年以上あるということで、ぜひ、利用者、子どもたちへのしっかりとした周知をしていただきたいと思います。いかがでしょうか。","respondent":"上野子ども育成課長","answer":"子どもたちへの周知についてですが、今後、北品川児童センター、東品川児童センターへの代替施設のご案内を進めてまいりますが、事前に子どもたちと一緒に職員が東大井児童センターですとか、北品川児童センター、それから東品川児童センターに行き方の確認ですとか。","voiceIndex":164,"id":"exchange-050"},{"speaker":"まつざわ委員","kind":"確認","question":"今のお話の中で代替地が国道１５号を越えて、川を越えてと、少し遠い部分があると思うのです。そうすると、移動が丁寧でも、子どもたちもよく分かると思うのですが、例えば、子育てする人はなかなか徒歩圏内は難しい。そうすると、多分、自転車の移動。１点が、防災倉庫にもなっていたと思うのです。代替地の中で防災倉庫がなくなったときの位置づけ、計画、何かそこら辺が現状あるのか、４つ確認です。","respondent":"上野子ども育成課長","answer":"それから休館中、３年間閉館してしまうので、空白ができないように、利用者の方への配慮ですけれども、先ほどご提案いただきましたすまいるとの協力、ほかの児童センターですまいると一緒に事業をしている事例もありますので、そういった好事例も活用しながら。","voiceIndex":167,"id":"exchange-051"}]},{"id":"topic-08","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"高橋（し）委員","kind":"意見","question":"それは教員の働き方改善、改革につながるということ、ガイドラインによる効果をお尋ねします。学校あるいは区全体として、教育委員会としてです。３つ目は（仮称）品川区学校・家庭サポートセンターという、天理市のようなのを設置したとして、どのような教員の働き方に影響があるか、プラスになる、それぞれのトラブル解消の設定に関してどのような効果があるかをお尋ねします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-052"},{"speaker":"横山委員","kind":"確認","question":"私からは同様に先ほどのガイドラインについて、地域ですとか議会や議員等への周知の部分をどのようにされるのかを確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"いずれにしても、子どもを真ん中にした支援が大切だと考えておりまして、学校の対応もそうですけれども、保護者の理解も得られるように努めてまいります。","voiceIndex":173,"id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これから品川区教育委員会として、アレンジして、どのような形にするか検討していくということでした。現時点で、都立の小中一貫や高校向けという側面が随分強いのですけれども、今回、発表された東京都教育委員会のこのガイドラインの評価、現状でそれを見ていただいたとき、どう考えているかをお尋ねしたい。それから、３つ目はガイドラインの１５ページに社会通念を超える要望に対して、こうですと。","respondent":"丸谷教育総合支援センター長","answer":"内容といたしましては、報道ではカスハラ対応というような言い方が随分されましたが、このガイドラインの前半部分については、やはり学校と家庭・地域がパートナーとして、協働して子どもを育てていくというメッセージが込められていると考えておりまして。","voiceIndex":177,"id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、お話のあったような形で検討を進めていただきたいと思います。そのためにも、仮称のサポートセンターがあることによって、こうだとご相談していただける形になるので、ぜひ、学校の対応について、直接相談をする、中立的な立場のものができると、セットで進めていただけると、より学校にもいいし、保護者の方にもいいと思うので、これは要望で進めてください。それだけもう１回お尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"本区にはコミュニティ・スクール、校区教育協働委員会もありますので、そういった場面もしっかりと活用しながら、学校と地域、また保護者が連携して、子どもたちを大人みんなで育てていくという風土を醸成していくことが大事だと考えております。","voiceIndex":179,"id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"意見","question":"今、お話にあったように、面と向かって、お話ししたり、挨拶したり、関係を日常的につくることが大事だというお話で、まさにそのとおりで、保護者会や品川区の場合、学校公開を数多くやっているので、そこで担任の先生とかにお話しする機会があって、トラブルがあって、初めて担任の先生と口をきいたなどとならないような状況がつくられていると思うので、ぜひ進めてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":181,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、天理市に視察に行ったときにも、保護者をクレーマーとして扱うのではなくて、しっかり話を聞いていけば、なぜそういうことを言っているのか理解ができる。やはりお互い理解していくことが大切ということで、時間のかかることですけれども、ぜひそうしたお互いを理解し合って、一緒にこの学校をつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":183,"id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7323#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":53639,"voices":194}},{"id":"r08-20260225-5","meetingId":"r08-1t","date":"2026年2月25日","dateIso":"2026-02-25","committee":"総務委員会","time":"午前１０時００分～午前１１時２７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和８年度 組織改正（案）","agenda":"令和８年度 組織改正（案）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１ページ目の施設マネジメント支援担当制というのが新設されるのですが、行政の仕事にマネジメントという言葉はあまりふさわしくないのかなと思うのです。区民サービスにしろ、支援にしろ、マネジメントとして、経営効率化とか、そういうことを考えながら事業を推進するというやり方は何かおかしい気がするのですが、そこをどのようにお考えなのでしょうか。","respondent":"崎村企画課長","answer":"そういった部分で今後の施設改修とか、施設の改築に当たってどのように進めていくのが効率的、効果的なのか、また経費も抑えられるのかというのをしっかり組織的に考えていかなければいけないという視点で、今回組織を新設させていただいたです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"それと、子ども未来部のほうで、在宅子育て支援係、保護児童支援担当、それから社会的養護推進担当というのが移管されるということで、これも別の事業部でそのまま移管して事業を進めていくというふうに考えていていいのでしょうか。","respondent":"崎村企画課長","answer":"２点目の子ども未来部の組織改正の部分ですけれども、説明が不十分だったかもしれませんが、在宅子育て支援係については、子ども育成課から子育て応援課のほうに移管し、事業自体がなくなるということでございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"今年の施政方針を読むと、障害者施策のさらなる充実を図ってまいります、本年４月より新たな障害者施設の司令塔機能を担う担当部長を設置し、取組を加速化してまいりますとあるのですけれども、これはどこに入るのですかということと、今質問がありました子ども未来部という中で、これは在宅子育て支援係が子育て応援課に移管ということなのですけれども。","respondent":"崎村企画課長","answer":"例えば、子どもの食の支援ですとか、児童手当の支給、医療費の助成事業と大分親和性があるといった部分がございまして、そちらに移管して、きめ細かな対応を図っていくというようなことがあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"３番目の部長級の退職者というのが結構いらっしゃるのですけれども、よく分からなかった。そうすると、部長級の方が部長のままでと、今まで再任用でやっていただいていたところがあったのですけれども、それは今後、来年度はどうなってしまうのでしょうか。まだ大丈夫ですというのか、私は役職定年制が敷かれているという認識を持っているのですけれども、人事はどういうふうになっているのですか。","respondent":"崎村企画課長、宮尾人事課長","answer":"担当部長のご質問ですけれども、区長が施政方針でお示ししたとおり、担当部長を設置する方針というところは変わりございません。私からは役職定年制のことについてお答えさせていただきたいと思います。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"具体的な部署の名前が入っていないので、どこでやるのという、ということは、今までの組織の中でやっていくということになるのですか、今の話だと、例えば福祉部とか障害者関係の部署があって、そこの組織は変わらず、担当が変われば名前も変わると思うのです。載っていないということは、その部署も名前を変えずにやっていくという認識でいいのかなと思うのですけれども、それでいいですか。","respondent":"崎村企画課長","answer":"部としては福祉部の中に担当部長を設置するです。今回福祉部の組織改正の中に入っているところについては、障害者の部門については基本的には障害者施策推進課、障害者支援課という２課の体制で引き続き進めていくです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"私からも質問します。その中で教えていただきたいのですけれども、担当主査の配置の基準を確認させてください。ご説明の中で複数の係長を設置できるというご説明があったと思いますけれども、複数の係長を設置することで、人員配置とか、想定している定員や業務量等の考え方などがあれば、併せて教えていただければと思います。","respondent":"崎村企画課長","answer":"そういったところで業務量が増えていて、１人の係長ではマネジメントがなかなか難しくなってきていところと、また、複数配置することによって機動的に進めていけるようなところについては、担当主査制ということで、複数の係長を配置して進めていくといったところです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。係長を配置することで全体の業務量の増に対応していくということで、それぞれの職員の定員については、それに応じて柔軟に配置されるということだと理解いたしました。この辺りは戸籍住民課に新設しながらも横串連携を図って取りまとめていくという位置づけなのかというのを確認させていただきたいと思います。","respondent":"崎村企画課長","answer":"戸籍住民課の窓口業務改革担当ですけれども、委員がご指摘のとおり、こちらは戸籍住民課の窓口だけを検討していくということではなくて、基本的には戸籍住民課というのは、手続の起点となる転出入の業務を所掌しているところですけれども、それ以外に。","voiceIndex":19,"id":"exchange-007"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれご説明ありがとうございました。窓口業務改革のところは、おっしゃっていただいているとおり横串連携をして、区民目線での使いやすい窓口になるようにぜひ進めていただきたいと思います。運用のほうもスムーズにいくように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"塚本副委員長","kind":"質問","question":"今までなかったもので、新しい視点での仕事とかが生まれるから、そこに組織を新しくつくるというのはなるほどという感じなのですけれども、情報公開担当の主査制ということは、業務量が増えたからというのと、主査制に移そうというような説明だったかと思うのですが、単に人を増やせばいいではないかという話ではなくて、ただ単に仕事が増えたのであれば、何も組織改正までしなくても。","respondent":"崎村企画課長","answer":"説明が不十分なところがございましたけれども、情報公開担当が担っている仕事というのは、一般の職員が担うべき仕事というより、さらに高度な知識とか経験を有する仕事というところがございまして、情報公開につきましても。","voiceIndex":22,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"１点だけ、もしあればなのですけれども、社会で多くの企業はＡＩを推進して、そういう推進する課みたいなものを設けて、様々な事業部に対して協力して社内を改善していこう、効率化も含めてやっているのですが、品川区としては、ＡＩを推進する部、推進する課、またはそういう事業部というのは存在するのですか。","respondent":"崎村企画課長","answer":"今は企画経営部のデジタル推進課において、例えばＡＩによる業務効率化、業務改善というのを担って検討しているところです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうことは事業部として全面に出して、各事業部は統括して積極的に進めていくというのが社会の流れだと思うので、そういう方面もぜひ検討していただきたいと私は思います。組織改正の中にそういう一言が入っていないというのは、ちょっと遅れているのではないかと私は思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"}]},{"id":"topic-02","title":"令和８年度都区財政調整","agenda":"令和８年度都区財政調整","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"５ページなのですけれども、再調整のほうなのですが、追加するということなので、６項目が、品川区の場合は幾らになっているのか、それが追加されるということなので、最終補正になってくるのかなと思うのですけれども、その確認をお願いします。","respondent":"加島財政課長","answer":"おっしゃるとおり、最終補正予算のほうに今、反映させていただいておりまして、その額は約２３億円です。","voiceIndex":31,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"それはそれでいいということなのか、でもほかのところにしてみれば、いや、そんなのはやりたくない、ほかのことをやりたいというところもあり、この算定の方法というのはどうなのでしょうか、何となく２３区の合意が取れている上での算定の中に入っていくというのだったら分かるのですけれども、先手でやった者勝ちみたいな形で、やらざるを得ない状況になってしまっていると。","respondent":"加島財政課長","answer":"品川区のほうでも仮に財調算定がされていなかったとしても、今の時代に照らし合わせて、社会経済情勢に合わせて、これはやる意義があると考えたのであれば、財調算定されていなくても実施することもあります。","voiceIndex":33,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"分かりました。それで５６％が今後どこまで伸びるのか、東京都はどこまで手を放してくれるのかなと思っているのですけれども、今ぎりぎりのところなのか、それとも６０％ぐらいはできるのかとか、そこら辺のめどはいかがでしょうか。今後も含めて、区の中でいうと大体これぐらいは欲しいなどというところは、２３区のほかの区の同意というか、方向性とかという考えはあるのでしょうか。","respondent":"加島財政課長","answer":"先ほど最後のほうで委員から区立児童相談所の話がございましたけれども、令和８年度にも２区の開設が予定されているところです。","voiceIndex":35,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"児童相談所のほうは、１２区でもう開設された。でも、それが入っているということは、やっていないところが１１区あります。そこはどういう配分になるのでしょうか。やっているところにということなのか、それを踏まえて品川区は来ているのかということを確認したいです。それから、在り方検討会は、確かに平成１２年の方針のままなのですか。その後、方針を変えたということはないのですか。","respondent":"加島財政課長、崎村企画課長","answer":"私のほうから児童相談所の関係についてお答えします。こちらについては、平成２３年１月までに、４４４項目のうち５３項目が区に移管する事務ということで整理されたところではあるのですが、その先に進むためには、東京都側としては。","voiceIndex":37,"id":"exchange-015"}]},{"id":"topic-03","title":"品川区総合庁舎における東京ベイｅＳＧプロジェクト先行プロジェクト（ＤＡＣコート）の実証実験","agenda":"品川区総合庁舎における東京ベイｅＳＧプロジェクト先行プロジェクト（ＤＡＣコート）の実証実験","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"ＤＡＣコートをやっていくに当たって、施工箇所が第三庁舎外壁と第一駐車場へのスロープ脇の腰壁ということになっているのですけれども、なぜここが選ばれたのか教えていただきたいということと、案内板を設置するということなのですが、どの辺りに設置されるのかなというところで、多くの人が行き来する第三庁舎の外壁なのか、各エリアに設置されるのかというのを教えていただきたいということ、もう一つが。","respondent":"佐藤経理課長","answer":"最後に、検証が終わった後のほかの区有施設への展開というところですが、今回実証実験ということで、市場に出る前の段階でデータを取って、その後につなげていくというところが目的ですので、具体的にはまだ特にありませんけれども、今後市場に出た後は。","voiceIndex":46,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"経費については、清水建設が全部経費を出していくのでしょうか。それから、検証とはどんなことやるのですか。せっかく場所を提供するわけだから、どういう結果なのかというのは興味があると思うので、それの公表というのはどういう形になるのか、東京都だから東京都から公表になっていくのかなというという思いがあるのですけれども、その進め方を教えてください。","respondent":"佐藤経理課長","answer":"２点のご質問かと思います。１点目の経費についてです。","voiceIndex":48,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"聞き忘れました。いつまでやるのでしょうか。庁舎の建て替えもあり、そんなに長くはやれないかなと思うのです。その期間で十分なのでしょうか。期間を教えてください。","respondent":"佐藤経理課長","answer":"期間については、今後先方と話し合ってというところになろうかと思いますけれども、先方の希望としては、この庁舎が解体されるまでということで聞いております。なるべく長くデータを取りたいというふうに聞いております。","voiceIndex":50,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"これは設置するだけなので、安全面とかは多分問題ないのかなとは思うのですけれども、そこら辺の業者とのやり取り、会社とのやり取りは、迅速に対応してくれる状況にあるのか、安全面について教えてください。","respondent":"佐藤経理課長","answer":"安全面についてですが、区のほうも庁舎を管理する立場ですので、事業者と東京都には確認しておりまして、問題ないという結論なのですけれども、ＤＡＣコートを塗ることで、ＣＯ２の固定化が図られるのですが。","voiceIndex":52,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"作業員の安全性の評価もまだ確立されていないということを考えるとどうなのかなという懸念があります。その状況下で、今回ＤＡＣの実証実験をやるということは、ちょっとおかしい、不可解な気もするのですが、どうなのでしょうか。これはＣＯ２の吸収量が増えるということがメインでうたってありますけれども、実際はかなり絶対量が少ないというふうに聞いております。","respondent":"佐藤経理課長","answer":"最後、ＣＯ２の吸収量なのですけれども、塗ることで１.５倍の吸収量があるというふうに、現在の実験の中では計測されているというふうに聞いておりますので、一定の効果はあるというふうに考えております。","voiceIndex":54,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"吸収量が１.５倍以上増えるというふうにありますが、実際既存のストックが約３００億ｔあるという話です。もう一度繰り返しますけれども、安全性に対して大丈夫だとおっしゃるならそれでいいのですが、まだ確立されていないような話も我々は聞いていますので、ぜひ確認していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"都からの要請に応じて塗布していくということで、これから市場に出していくに当たって検証していくということなのですけれども、塗布されるのは品川区だけなのですか。ほかの区でも取り組まれるのか伺いたいです。","respondent":"佐藤経理課長","answer":"今回この技術に関しては品川区だけということで聞いております。","voiceIndex":57,"id":"exchange-022"},{"speaker":"松本委員","kind":"質問","question":"今のところなのですけれども、逆に言ったら、なぜ品川区なのかというのがよく分からなくて、似たような構造物だったら、これは東京都のプロジェクトなので、都側がやればいいのではないのかとぱっと浮かぶのですけれども、ここはなぜ品川区なのでしょうか。","respondent":"佐藤経理課長","answer":"区では、東京ｅＳＧプロジェクトの関係で、八潮のこみゅにてぃぷらざで、垂直水耕栽培のところで協力したいというところで、東京都の取組は今後を見据えたところですので、広く言えば区民のためにもなるということもありますので、協力しているというところです。","voiceIndex":59,"id":"exchange-023"},{"speaker":"松本委員","kind":"確認","question":"今周りからもざわざわと出た、これは庁舎を取り壊す前提だから、それが理由であるということか、最後にそこだけ確認しておきます。","respondent":"久保田企画経営部長","answer":"今いろいろご質問いただきましたけれども、品川区としては、環境問題に対していろいろと取り組んできているというところがありまして、今、経理課長からも説明がありましたように、東京都のｅＳＧプロジェクトに対しては、区としても積極的に協力していくということで。","voiceIndex":61,"id":"exchange-024"},{"speaker":"松本委員","kind":"意見","question":"誤解が解けてよかったと思います。こういう実証実験はどんどん先進的にやっていきたいと思っていますので、区として環境問題に取り組むために、当局でもこういうことをやっていただけるのはよいことかなと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-025"}]},{"id":"topic-04","title":"固定資産税および都市計画税の軽減措置の継続","agenda":"固定資産税および都市計画税の軽減措置の継続","exchanges":[{"speaker":"西本委員","kind":"確認","question":"これは継続ということなのですけれども、軽減措置の内容は３つありますけれども、これは全く同じ、今までと変わらないという確認でよろしいでしょうか。それと、意見書の成果になるのだろうと思うのですけれども、毎回、毎回同じ内容で、この委員会でも、もうそろそろ恒常的にやってもいいのではないのかというふうな意見も出ていたと思うのです。そういうのは反映されなかったのでしょうか。教えてください。","respondent":"宮澤税務課長","answer":"１つ目の軽減内容です。これは例年継続している内容と変わりはないという状況になっております。２つ目の、毎年度継続しています。","voiceIndex":68,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"恐らく都議会においても品川区議会においても、意見書を出したり、審議するのは、お互い時間がもったいないと思うので、これだけ収入、税収を含めて、東京都は財源が豊かなのですから、こういうところはぜひ軽減措置の継続ではなくて、もう恒久的にやるということを、大変でしょうけれども、毎年向こうに申し述べていただきたいと私は思います。終わりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-027"}]},{"id":"topic-05","title":"被爆樹木二世の苗木の植樹","agenda":"被爆樹木二世の苗木の植樹","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"今、議長、副議長、総務委員会の皆さんもということだったのですけれども、これは誰が植えるのかなと、例えば、平和の啓発だったりを考えたら、近隣の小学生と一緒に植えたり、そういうのもあったらいいのかなどとふと思ったのですが、何かそういうイベント的な感じでやったりはしないのかというところをまず教えてください。","respondent":"藤村総務課長","answer":"今のところ植樹していただく方というのは、区長と教育長、議長、あと広島と長崎に今年度派遣ということで応募いただいた中学生と高校生がおりますので、その方たちに植樹していただくのと、もう一人、調整中ではあるのですけれども、広島。","voiceIndex":75,"id":"exchange-028"},{"speaker":"澤田委員","kind":"質問","question":"分かりました。千羽鶴とか、平和に関係する皆さんで植樹されるということで、それはそれで素敵だなと思って今伺っていました。その様子は、区の広報でいろいろと発信されるのかなというところと、広報紙に載せたりすることで、せっかく植えたので、これから育っていく経過なども時々報告されたらいいなと思っているのですが、いかがでしょうか。","respondent":"藤村総務課長","answer":"発信方法としては、まず植樹しますというところをホームページ、ＳＮＳ等で発信したいと考えています。その後の経過等につきましても、適宜状況を見て、成長に合わせて何かお伝えするところがあれば、ＳＮＳ等で発信したいと思っています。","voiceIndex":77,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"植樹した後、プレートか何かで説明文、看板を立てるとか、そういうのをやるのでしょうか。","respondent":"藤村総務課長","answer":"今のところ、プレートというのが、この樹木自体は平和市長会議という団体経由で譲渡いただくので、譲渡いただいたときにプレートのほうも同時にいただけるということですので、そちらのプレートを設置しようかと考えているところです。","voiceIndex":79,"id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"成長していくのを見守るのも大事ですけれども、小さ過ぎても時間がかかり過ぎてしまうと思うので、成長度合いが分かれば、教えていただきたいのと、先ほどプレートというお話があったのですけれども、時々木にプラスチックのプレートがかかっていて、だんだん経年劣化していくようなプレートを見かけるのですけれども、そういうのではなくて、ちょっとグレードが高いではないですけれども、劣化しづらい。","respondent":"藤村総務課長","answer":"そちらの写真を見ると、少し小さめのプレートという形で、木に設置しているものもあれば、地面に埋め込んでいるものもあるので、今回は取りあえずそちらのプレートを設置する形になりますが、今後その状況を見て。","voiceIndex":82,"id":"exchange-031"},{"speaker":"須貝委員","kind":"意見","question":"被爆樹木二世の苗木の植樹については、特段異論はありませんけれども、できれば苗木にも数に限りはありますけれども、将来的に小中学校の片隅において、先生に恒久平和の確立とか核兵器廃絶について、１分でも２分でも子どもたちにお話ししていただけるような環境のところに植樹したほうがすごく有効だと私は思います。意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7331#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":26839,"voices":92}}]);
